QT_ISI(4,{"386":["(Semua makanan halal bagi Bani Israel kecuali makanan yang diharamkan oleh Israel) atau Yakub (atas dirinya) yaitu unta yang ditimpa penyakit pada urat nadinya. Ia bernazar jika hewan itu sembuh tidak akan dimakannya, maka haramlah hukumnya bagi mereka (sebelum Taurat diturunkan) hal ini terjadi sesudah Ibrahim sedangkan pada masanya sendiri tidaklah haram sebagaimana yang telah diakuinya. (Katakanlah) kepada mereka (\"Ambillah Taurat lalu bacalah) agar nyata benar atau tidaknya ucapanmu itu (jika kamu orang-orang yang benar\") dalam masalah tersebut. Mendengar itu mereka pun kebingungan dan tak pernah mengemukakan Taurat. Maka Allah swt. berfirman:",[["۞ كُلُّ","Semua"],["ٱلطَّعَامِ","[the] makanan"],["كَانَ","adalah"],["حِلًّۭا","halal"],["لِّبَنِىٓ","untuk (the) Kanak-kanak"],["إِسْرَٰٓءِيلَ","(dari) Israel"],["إِلَّا","kecuali"],["مَا","apa"],["حَرَّمَ","dijadikan haram"],["إِسْرَٰٓءِيلُ","Israel"],["عَلَىٰ","ke atas"],["نَفْسِهِۦ","dirinya sendiri"],["مِن","daripada"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["تُنَزَّلَ","(telah) didedahkan"],["ٱلتَّوْرَىٰةُ ۗ","Taurat"],["قُلْ","Katakanlah"],["فَأْتُوا۟","Jadi bawa"],["بِٱلتَّوْرَىٰةِ","Taurat"],["فَٱتْلُوهَآ","dan membacanya"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"387":["(Maka barang siapa yang mengada-adakan kedustaan terhadap Allah sesudah itu) setelah terbukti bahwa diharamkan unta itu ialah dari pihak Yakub bukan di masa Ibrahim (mereka orang-orang yang aniaya) artinya melampaui batas kebenaran hingga jatuh dalam kebatilan.",[["فَمَنِ","Kemudian sesiapa sahaja"],["ٱفْتَرَىٰ","mengada-adakan"],["عَلَى","tentang"],["ٱللَّهِ","Allah"],["ٱلْكَذِبَ","[yang] pembohongan"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["ذَٰلِكَ","bahawa"],["فَأُو۟لَـٰٓئِكَ","kemudian mereka"],["هُمُ","mereka"],["ٱلظَّـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"388":["(Katakanlah, \"Benarlah Allah.\") dalam soal ini sebagaimana juga dalam segala soal yang diberikan-Nya (maka ikutilah olehmu agama Ibrahim) yang saya anut (yang lurus) yang meninggalkan semua agama untuk memeluk agama Islam (dan tidaklah dia termasuk golongan musyrik). Ketika mereka mengatakan bahwa kiblat mereka lebih awal dari kiblat kaum Muslimin turun pula ayat:",[["قُلْ","Katakanlah"],["صَدَقَ","(telah) bercakap benar"],["ٱللَّهُ ۗ","Allah"],["فَٱتَّبِعُوا۟","kemudian ikuti"],["مِلَّةَ","(agama)."],["إِبْرَٰهِيمَ","(dari) Ibrahim"],["حَنِيفًۭا","(yang) tegak"],["وَمَا","dan bukan"],["كَانَ","dia adalah"],["مِنَ","daripada"],["ٱلْمُشْرِكِينَ","orang musyrik"]]],"389":["(Sesungguhnya rumah yang mula-mula dibangun) untuk tempat ibadah (bagi manusia) di muka bumi (ialah yang terdapat di Bakkah) dengan ba sebagai nama lain dari Mekah. Dinamakan demikian karena Kakbah mematahkan leher orang-orang durhaka lagi aniaya. Baitullah ini dibina oleh malaikat sebelum diciptakannya Adam dan setelah itu baru dibangun pula Masjidilaksa dan jarak di antara keduanya 40 tahun sebagai tersebut dalam kedua hadis sahih. Pada sebuah hadis lain disebutkan pula bahwa Kakbahlah yang mula-mula muncul di permukaan air ketika langit dan bumi ini diciptakan sebagai buih yang putih, maka dihamparkanlah tanah dari bawahnya (diberi berkah) hal dari alladzii tadi (dan menjadi petunjuk bagi seluruh alam) karena ia merupakan kiblat mereka.",[["إِنَّ","Sesungguhnya"],["أَوَّلَ","(yang) Pertama"],["بَيْتٍۢ","rumah"],["وُضِعَ","sediakan"],["لِلنَّاسِ","untuk umat manusia"],["لَلَّذِى","(ialah) yang"],["بِبَكَّةَ","(berada) di Bakkah"],["مُبَارَكًۭا","diberkati"],["وَهُدًۭى","dan hidayah"],["لِّلْعَـٰلَمِينَ","untuk dunia"]]],"390":["(Padanya terdapat tanda-tanda yang nyata) di antaranya (makam Ibrahim) yakni batu tempat berpijaknya Ibrahim sewaktu mendirikan Baitullah itu. Kedua telapak kakinya meninggalkan bekas padanya sampai sekarang dan tetap sepanjang zaman walaupun pemerintahan yang berkuasa sudah silih berganti. Di antaranya pula dilipatgandakannya pahala kebaikan bagi yang salat di dalamnya dan burung tidak dapat terbang di atas Kakbah (dan barang siapa memasukinya menjadi amanlah dia) artinya bebas dari ancaman pembunuhan, keaniayaan dan lain-lain. (Mengerjakan haji di Baitullah itu menjadi kewajiban manusia terhadap Allah) Ada yang membaca hajja dengan makna menyengaja. Lalu sebagai badal dari 'manusia' ialah (yakni orang-orang yang sanggup mengadakan perjalanan kepadanya) yang oleh Nabi saw. ditafsirkan dengan adanya perbekalan dan kendaraan, menurut riwayat Hakim dan lain-lain. (Barang siapa yang kafir) terhadap Allah atau terhadap kewajiban haji (maka sesungguhnya Allah Maha Kaya terhadap seluruh alam) artinya tidak memerlukan manusia, jin dan malaikat serta amal ibadah mereka.",[["فِيهِ","Di dalamnya"],["ءَايَـٰتٌۢ","(adalah) tanda-tanda"],["بَيِّنَـٰتٌۭ","yang nyata"],["مَّقَامُ","tempat berdiri"],["إِبْرَٰهِيمَ ۖ","(dari) Ibrahim"],["وَمَن","dan sesiapa"],["دَخَلَهُۥ","memasukinya"],["كَانَ","ialah"],["ءَامِنًۭا ۗ","selamat"],["وَلِلَّهِ","Dan (disebabkan) Allah"],["عَلَى","ke atas"],["ٱلنَّاسِ","umat manusia"],["حِجُّ","(ialah) haji"],["ٱلْبَيْتِ","(dari) Dewan"],["مَنِ","(untuk seorang) siapa"],["ٱسْتَطَاعَ","mampu"],["إِلَيْهِ","kepada [itu]"],["سَبِيلًۭا ۚ","(mencari) jalan"],["وَمَن","Dan sesiapa"],["كَفَرَ","kufur"],["فَإِنَّ","maka sesungguhnya"],["ٱللَّهَ","Allah"],["غَنِىٌّ","(adalah) bebas daripada keperluan"],["عَنِ","daripada"],["ٱلْعَـٰلَمِينَ","alam semesta"]]],"391":["(Katakanlah, \"Hai Ahli Kitab! Kenapa kamu ingkar akan ayat-ayat Allah) yakni Alquran (padahal Allah menyaksikan apa yang kamu kerjakan.\") hingga akan memberinya balasan?",[["قُلْ","Katakanlah"],["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لِمَ","kenapa"],["تَكْفُرُونَ","(adakah) kamu kafir"],["بِـَٔايَـٰتِ","dalam (the) Ayat"],["ٱللَّهِ","(milik) Allah"],["وَٱللَّهُ","sedangkan Allah"],["شَهِيدٌ","(adalah) seorang Saksi"],["عَلَىٰ","atas"],["مَا","apa"],["تَعْمَلُونَ","kamu lakukan"]]],"392":["(Katakanlah, \"Hai Ahli Kitab! Kenapa kamu menghalang-halangi dari jalan Allah) dari agama-Nya (orang-orang yang beriman) melalui pendustaan kalian terhadap Nabi Muhammad saw. dan menyembunyikan sifat-sifatnya (kamu mengharap) menghendaki agama itu (menjadi bengkok) sebenarnya iwaja itu kata benda tetapi berarti sebagai kata sifat artinya bengkok atau menyimpang dari kebenaran (padahal kamu menyaksikan) mengetahui bahwa agama yang lurus lagi diridai seperti yang tercantum dalam kitab sucimu ialah agama Islam. (Dan Allah sekali-kali tidak lalai dari apa yang kamu kerjakan) berupa kekafiran dan mendustakan. Dia sengaja menangguhkan kamu sampai saatmu nanti buat menerima ganjaran dan balasan-Nya. Ayat berikut diturunkan tatkala beberapa orang Yahudi lewat pada sebagian orang-orang Aus dan Khazraj. Mereka berang melihat kerukunan mereka lalu mereka bangkit-bangkitkan fitnah yang terjadi di antara mereka di masa jahiliah sehingga mereka pun bersengketa bahkan hampir bunuh-bunuhan.",[["قُلْ","Katakanlah"],["يَـٰٓأَهْلَ","Wahai Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لِمَ","kenapa"],["تَصُدُّونَ","(adakah) kamu menghalang"],["عَن","daripada"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["مَنْ","(mereka) yang"],["ءَامَنَ","beriman"],["تَبْغُونَهَا","mencari (untuk membuatnya)."],["عِوَجًۭا","(nampak) bengkok"],["وَأَنتُمْ","sedangkan kamu"],["شُهَدَآءُ ۗ","(adalah) saksi"],["وَمَا","Dan tidak"],["ٱللَّهُ","Allah"],["بِغَـٰفِلٍ","(adalah) tidak sedar"],["عَمَّا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"393":["(Hai orang-orang beriman! Jika kamu mengikuti sebagian dari orang-orang yang diberi Alkitab niscaya mereka akan mengembalikan kamu menjadi kafir setelah kamu beriman.\")",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِن","Jika"],["تُطِيعُوا۟","kamu taat"],["فَرِيقًۭا","satu kumpulan"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["يَرُدُّوكُم","mereka akan membalikkan kamu"],["بَعْدَ","selepas"],["إِيمَـٰنِكُمْ","kepercayaan kamu"],["كَـٰفِرِينَ","(sebagai) orang-orang kafir"]]],"394":["(Betapa kamu menjadi kafir) pertanyaan sebagai celaan dan membangkitkan keheranan (padahal ayat-ayat Allah dibacakan kepadamu dan rasul-Nya pun berada di tengah-tengah kamu. Barang siapa yang berpegang teguh) atau mengikuti (agama Allah, maka sesungguhnya ia telah dibimbing ke jalan yang lurus.)",[["وَكَيْفَ","Dan bagaimana (boleh)"],["تَكْفُرُونَ","kamu tidak beriman"],["وَأَنتُمْ","manakala [kamu]"],["تُتْلَىٰ","dibacakan"],["عَلَيْكُمْ","ke atas kamu"],["ءَايَـٰتُ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["وَفِيكُمْ","dan di antara kamu"],["رَسُولُهُۥ ۗ","(adalah) Rasul-Nya"],["وَمَن","Dan sesiapa"],["يَعْتَصِم","memegang teguh"],["بِٱللَّهِ","kepada Allah"],["فَقَدْ","maka pasti"],["هُدِىَ","dia diberi petunjuk"],["إِلَىٰ","kepada"],["صِرَٰطٍۢ","satu laluan"],["مُّسْتَقِيمٍۢ","lurus"]]],"395":["(Hai orang-orang yang beriman, bertakwalah kamu kepada Allah sebenar-benar takwa) yaitu dengan menaati dan bukan mendurhakai, mensyukuri dan bukan mengingkari karunia-Nya dan dengan mengingat serta tidak melupakan-Nya. Kata para sahabat, \"Wahai Rasulullah! Siapakah yang sanggup melaksanakan ini?\" Maka ayat ini pun dinasakh dengan firman-Nya, \"Bertakwalah kamu kepada Allah menurut kemampuanmu.\" (dan janganlah sekali-kali kamu mati melainkan dalam keadaan beragama Islam.)",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["ٱتَّقُوا۟","Takut"],["ٱللَّهَ","Allah"],["حَقَّ","(sebagaimana hakNya)."],["تُقَاتِهِۦ","(bahawa) Dia (harus) ditakuti"],["وَلَا","dan jangan"],["تَمُوتُنَّ","mati"],["إِلَّا","kecuali"],["وَأَنتُم","[sementara kamu]"],["مُّسْلِمُونَ","(sebagai) orang Islam"]]],"396":["(Berpegang teguhlah kamu dengan tali Allah) maksudnya agama-Nya (kesemuanya dan janganlah kamu berpecah-belah) setelah menganut Islam (serta ingatlah nikmat Allah) yakni karunia-Nya (kepadamu) hai golongan Aus dan Khazraj (ketika kamu) yakni sebelum Islam (bermusuh-musuhan, maka dirukunkan-Nya) artinya dihimpun-Nya (di antara hatimu) melalui Islam (lalu jadilah kamu berkat nikmat-Nya bersaudara) dalam agama dan pemerintahan (padahal kamu telah berada dipinggir jurang neraka) sehingga tak ada lagi pilihan lain bagi kamu kecuali terjerumus ke dalamnya dan mati dalam kekafiran (lalu diselamatkan-Nya kamu daripadanya) melalui iman kalian. (Demikianlah) sebagaimana telah disebutkan-Nya tadi (Allah menjelaskan ayat-ayat-Nya supaya kamu beroleh petunjuk).",[["وَٱعْتَصِمُوا۟","Dan pegang teguh"],["بِحَبْلِ","kepada (tali)."],["ٱللَّهِ","(milik) Allah"],["جَمِيعًۭا","semua bersama"],["وَلَا","dan jangan"],["تَفَرَّقُوا۟ ۚ","berbelah bahagi"],["وَٱذْكُرُوا۟","Dan ingat"],["نِعْمَتَ","(yang) nikmat"],["ٱللَّهِ","(milik) Allah"],["عَلَيْكُمْ","pada kamu"],["إِذْ","apabila"],["كُنتُمْ","kamu dahulu"],["أَعْدَآءًۭ","musuh"],["فَأَلَّفَ","kemudian Dia membuat persahabatan"],["بَيْنَ","antara"],["قُلُوبِكُمْ","hati kamu"],["فَأَصْبَحْتُم","kemudian kamu menjadi"],["بِنِعْمَتِهِۦٓ","dengan nikmatNya"],["إِخْوَٰنًۭا","adik beradik"],["وَكُنتُمْ","Dan kamu pernah"],["عَلَىٰ","pada"],["شَفَا","(the) ambang"],["حُفْرَةٍۢ","(dari) pit"],["مِّنَ","daripada"],["ٱلنَّارِ","neraka"],["فَأَنقَذَكُم","kemudian Dia menyelamatkan kamu"],["مِّنْهَا ۗ","daripadanya"],["كَذَٰلِكَ","Demikianlah"],["يُبَيِّنُ","membuat jelas"],["ٱللَّهُ","Allah"],["لَكُمْ","bagi kamu"],["ءَايَـٰتِهِۦ","Ayat-ayatNya"],["لَعَلَّكُمْ","supaya kamu"],["تَهْتَدُونَ","(dibimbing)."]]],"397":["(Hendaklah ada di antara kamu satu golongan yang menyeru kepada kebaikan) ajaran Islam (dan menyuruh kepada yang makruf dan melarang dari yang mungkar. Merekalah) yakni orang-orang yang menyeru, yang menyuruh dan yang melarang tadi (orang-orang yang beruntung) atau berbahagia. 'Min' di sini untuk menunjukkan 'sebagian' karena apa yang diperintahkan itu merupakan fardu kifayah yang tidak mesti bagi seluruh umat dan tidak pula layak bagi setiap orang, misalnya orang yang bodoh.",[["وَلْتَكُن","Dan biarkan ada"],["مِّنكُمْ","antara kamu"],["أُمَّةٌۭ","[a] orang"],["يَدْعُونَ","mengundang"],["إِلَى","kepada"],["ٱلْخَيْرِ","yang baik"],["وَيَأْمُرُونَ","[dan] menyuruh"],["بِٱلْمَعْرُوفِ","yang betul"],["وَيَنْهَوْنَ","dan melarang"],["عَنِ","daripada"],["ٱلْمُنكَرِ ۚ","yang salah"],["وَأُو۟لَـٰٓئِكَ","dan mereka"],["هُمُ","mereka"],["ٱلْمُفْلِحُونَ","(adalah) orang-orang yang berjaya"]]],"398":["(Dan janganlah kamu seperti orang-orang yang berpecah-belah) dalam agama mereka (dan berselisih) padanya (sesudah datang kepada mereka keterangan yang jelas) mereka itu ialah orang-orang Yahudi dan Nasrani. (Merekalah orang-orang yang mendapat siksa yang berat).",[["وَلَا","Dan jangan"],["تَكُونُوا۟","jadilah"],["كَٱلَّذِينَ","seperti mereka yang"],["تَفَرَّقُوا۟","menjadi berpecah belah"],["وَٱخْتَلَفُوا۟","dan berbeza"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مَا","apa"],["جَآءَهُمُ","datang kepada mereka"],["ٱلْبَيِّنَـٰتُ ۚ","bukti-bukti yang jelas"],["وَأُو۟لَـٰٓئِكَ","Dan mereka"],["لَهُمْ","bagi mereka"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌۭ","yang besar"]]],"399":["(Ingatlah suatu hari di mana wajah-wajah ada yang menjadi putih berseri dan ada pula yang hitam legam) maksudnya pada hari kiamat. (Adapun orang-orang yang wajahnya menjadi hitam) yakni orang-orang kafir, maka mereka dilemparkan ke dalam neraka dan dikatakan kepada mereka sebagai celaan (\"Kenapa kamu kafir setelah beriman?\") yaitu sewaktu pengambilan ikrar dulu. (\"Maka rasailah siksa disebabkan kekafiranmu itu.\")",[["يَوْمَ","(Pada) Hari"],["تَبْيَضُّ","akan menjadi putih"],["وُجُوهٌۭ","(beberapa) muka"],["وَتَسْوَدُّ","dan akan menjadi hitam"],["وُجُوهٌۭ ۚ","(beberapa) muka"],["فَأَمَّا","Adapun"],["ٱلَّذِينَ","mereka yang"],["ٱسْوَدَّتْ","bertukar hitam"],["وُجُوهُهُمْ","muka [mereka]"],["أَكَفَرْتُم","Adakah kamu tidak beriman"],["بَعْدَ","selepas"],["إِيمَـٰنِكُمْ","kepercayaan kamu"],["فَذُوقُوا۟","Kemudian rasa"],["ٱلْعَذَابَ","azab"],["بِمَا","bagi apa"],["كُنتُمْ","kamu pernah"],["تَكْفُرُونَ","kufur"]]],"400":["(Adapun orang-orang yang wajahnya menjadi putih berseri) yakni orang-orang yang beriman (mereka berada dalam rahmat Allah) dalam surga-Nya (mereka kekal di dalamnya).",[["وَأَمَّا","Tetapi untuk"],["ٱلَّذِينَ","mereka yang"],["ٱبْيَضَّتْ","bertukar putih"],["وُجُوهُهُمْ","muka [mereka]"],["فَفِى","kemudian (mereka akan) masuk"],["رَحْمَةِ","(the) Rahmat"],["ٱللَّهِ","(milik) Allah"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"401":["(Itulah) maksudnya ayat-ayat tadi (ayat-ayat Allah. Kami bacakan kepadamu) hai Muhammad (dengan benar, dan tiadalah Allah menghendaki keaniayaan bagi seluruh alam) misalnya dengan menjatuhkan hukuman pada mereka tanpa dosa.",[["تِلْكَ","Ini"],["ءَايَـٰتُ","(adalah) Ayat-ayat"],["ٱللَّهِ","(milik) Allah"],["نَتْلُوهَا","Kami membacanya"],["عَلَيْكَ","kepada kamu"],["بِٱلْحَقِّ ۗ","dalam kebenaran"],["وَمَا","Dan tidak"],["ٱللَّهُ","Allah"],["يُرِيدُ","mahu"],["ظُلْمًۭا","ketidakadilan"],["لِّلْعَـٰلَمِينَ","kepada dunia"]]],"402":["(Kepunyaan Allahlah segala yang di langit dan di bumi) baik sebagai milik maupun sebagai makhluk dan hamba (dan kepada Allah kembalinya segala urusan).",[["وَلِلَّهِ","Dan kepunyaan Allah"],["مَا","apa sahaja"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa sahaja"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۚ","bumi"],["وَإِلَى","Dan kepada"],["ٱللَّهِ","Allah"],["تُرْجَعُ","akan dikembalikan"],["ٱلْأُمُورُ","perkara-perkara"]]],"403":["(Adalah kamu) hai umat Muhammad dalam ilmu Allah swt. (sebaik-baik umat yang dikeluarkan) yang ditampilkan (buat manusia, menyuruh kepada yang makruf dan melarang dari yang mungkar serta beriman kepada Allah. Sekiranya Ahli Kitab beriman, adalah ia) yakni keimanan itu (lebih baik bagi mereka. Di antara mereka ada yang beriman) misalnya Abdullah bin Salam r.a. dan sahabat-sahabatnya (tetapi kebanyakan mereka orang-orang yang fasik) kafir.",[["كُنتُمْ","kamu adalah"],["خَيْرَ","(yang) terbaik"],["أُمَّةٍ","(daripada) orang"],["أُخْرِجَتْ","dinaikkan"],["لِلنَّاسِ","untuk umat manusia"],["تَأْمُرُونَ","menyuruh"],["بِٱلْمَعْرُوفِ","yang betul"],["وَتَنْهَوْنَ","dan melarang"],["عَنِ","[dari]"],["ٱلْمُنكَرِ","yang salah"],["وَتُؤْمِنُونَ","dan beriman"],["بِٱللَّهِ ۗ","kepada Allah"],["وَلَوْ","Dan jika"],["ءَامَنَ","beriman"],["أَهْلُ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لَكَانَ","sudah pasti"],["خَيْرًۭا","kebaikan"],["لَّهُم ۚ","bagi mereka"],["مِّنْهُمُ","Antaranya"],["ٱلْمُؤْمِنُونَ","(ialah) orang-orang yang beriman"],["وَأَكْثَرُهُمُ","tetapi kebanyakan mereka"],["ٱلْفَـٰسِقُونَ","(adalah) durhaka"]]],"404":["(Mereka sekali-kali tidak akan dapat memberi mudarat kepadamu) maksudnya sedikit pun juga orang-orang Yahudi tidak akan dapat memberi mudarat terhadap kaum Muslimin (kecuali gangguan saja) yakni gangguan lisan seperti makian dan ancaman (dan jika mereka berperang dengan kamu maka mereka akan berbalik melarikan diri) karena menderita kekalahan (kemudian mereka tidak mendapat pertolongan) untuk menghadapi kamu sebaliknya kamulah yang akan mendapat pertolongan untuk menghadapi mereka.",[["لَن","tidak pernah"],["يَضُرُّوكُمْ","adakah mereka akan membahayakan kamu"],["إِلَّآ","kecuali"],["أَذًۭى ۖ","sakit hati"],["وَإِن","Dan jika"],["يُقَـٰتِلُوكُمْ","mereka melawan kamu"],["يُوَلُّوكُمُ","mereka akan berpaling (ke arah) kamu"],["ٱلْأَدْبَارَ","bahagian belakang"],["ثُمَّ","kemudian"],["لَا","tidak"],["يُنصَرُونَ","mereka akan dibantu"]]],"405":["(Ditimpakan atas mereka kehinaan di mana pun mereka berada) sehingga bagi mereka tak ada kemuliaan dan keamanan (kecuali) dengan dua hal: (dengan tali dari Allah dan tali dari manusia) yang beriman, yang merupakan janji dari mereka kepada Ahli Kitab bahwa mereka akan diberi keamanan dengan imbalan pembayaran upeti, maka tak ada jaminan bagi mereka selain dengan itu (dan mereka kembali mendapat kemurkaan dari Allah dan ditimpakan atas mereka kerendahan. Demikian itu bahwa mereka) artinya disebabkan karena mereka (kafir akan ayat-ayat Allah dan membunuh para nabi tanpa alasan yang benar. Demikian itu) sebagai pengukuhan (disebabkan mereka durhaka) akan perintah Allah (dan mereka melanggar batas) artinya melampaui yang halal hingga jatuh kepada yang haram.",[["ضُرِبَتْ","Terpukul"],["عَلَيْهِمُ","ke atas mereka"],["ٱلذِّلَّةُ","penghinaan itu"],["أَيْنَ","di mana sahaja"],["مَا","bahawa"],["ثُقِفُوٓا۟","mereka ditemui"],["إِلَّا","kecuali"],["بِحَبْلٍۢ","dengan tali"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَحَبْلٍۢ","dan seutas tali"],["مِّنَ","daripada"],["ٱلنَّاسِ","manusia"],["وَبَآءُو","Dan mereka ditanggung"],["بِغَضَبٍۢ","kemarahan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَضُرِبَتْ","dan dipukul"],["عَلَيْهِمُ","ke atas mereka"],["ٱلْمَسْكَنَةُ ۚ","kemiskinan itu"],["ذَٰلِكَ","Itu"],["بِأَنَّهُمْ","(adalah) kerana"],["كَانُوا۟","mereka dahulu"],["يَكْفُرُونَ","kufur"],["بِـَٔايَـٰتِ","dalam (the) Ayat"],["ٱللَّهِ","(milik) Allah"],["وَيَقْتُلُونَ","dan mereka membunuh"],["ٱلْأَنۢبِيَآءَ","para Nabi"],["بِغَيْرِ","tanpa"],["حَقٍّۢ ۚ","betul"],["ذَٰلِكَ","Itu"],["بِمَا","(adalah) kerana"],["عَصَوا۟","mereka ingkar"],["وَّكَانُوا۟","dan mereka pernah"],["يَعْتَدُونَ","langgar"]]],"406":["(Mereka itu tidaklah) maksudnya Ahli-ahli Kitab (sama) atau serupa. (Di antara Ahli Kitab ada golongan yang bersikap lurus) jujur dan teguh berdiri di atas kebenaran seperti Abdullah bin Salam r.a. dan sahabat-sahabatnya (mereka membaca ayat-ayat Allah di saat-saat malam hari sedangkan mereka bersujud) maksudnya salat, menjadi hal.",[["۞ لَيْسُوا۟","Mereka tidak"],["سَوَآءًۭ ۗ","(yang) sama"],["مِّنْ","antara"],["أَهْلِ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["أُمَّةٌۭ","(adalah) sebuah komuniti"],["قَآئِمَةٌۭ","berdiri"],["يَتْلُونَ","(dan) mengaji"],["ءَايَـٰتِ","(the) Ayat"],["ٱللَّهِ","(milik) Allah"],["ءَانَآءَ","(dalam) jam"],["ٱلَّيْلِ","(dari) malam"],["وَهُمْ","dan mereka"],["يَسْجُدُونَ","sujud"]]],"407":["(Mereka beriman kepada Allah dan hari yang akhir, menyuruh kepada yang makruf dan melarang dari yang mungkar dan berlomba-lomba mengerjakan kebaikan. Mereka itulah) yakni yang dilukiskan tadi (termasuk orang-orang yang saleh). Di antara mereka ada pula yang tidak seperti demikian dan tidak termasuk orang-orang yang saleh.",[["يُؤْمِنُونَ","Mereka beriman"],["بِٱللَّهِ","kepada Allah"],["وَٱلْيَوْمِ","dan Hari"],["ٱلْـَٔاخِرِ","yang Terakhir"],["وَيَأْمُرُونَ","dan mereka menyuruh"],["بِٱلْمَعْرُوفِ","[dengan] hak"],["وَيَنْهَوْنَ","dan melarang"],["عَنِ","[dari]"],["ٱلْمُنكَرِ","yang salah"],["وَيُسَـٰرِعُونَ","dan mereka bersegera"],["فِى","dalam"],["ٱلْخَيْرَٰتِ","perbuatan baik itu"],["وَأُو۟لَـٰٓئِكَ","Dan mereka"],["مِنَ","(adalah) daripada"],["ٱلصَّـٰلِحِينَ","orang yang soleh"]]],"408":["(Apa-apa yang mereka kerjakan) yang dikerjakan oleh umat yang lurus tadi, dengan ya atau yang kamu kerjakan, wahai umat dengan ta (berupa kebaikan, maka tidaklah akan tertutup) menurut dua versi tadi artinya tidaklah akan terhalang untuk mendapatkan pahalanya tetapi akan tetap diberi balasannya. (Dan Allah Maha Mengetahui akan orang-orang yang bertakwa.)",[["وَمَا","Dan apa sahaja"],["يَفْعَلُوا۟","mereka lakukan"],["مِنْ","daripada"],["خَيْرٍۢ","yang baik"],["فَلَن","maka tidak pernah"],["يُكْفَرُوهُ ۗ","adakah mereka akan dinafikan"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","(adalah) Maha Mengetahui"],["بِٱلْمُتَّقِينَ","daripada orang yang takut kepada Tuhan"]]],"409":["(Sesungguhnya orang-orang yang kafir tidaklah akan dapat menolak) menghindarkan (diri mereka atau harta benda maupun anak-anak laki-laki mereka dari Allah) dari siksa-Nya (sedikit pun juga) dikhususkan-Nya menyebutkan keduanya karena biasanya manusia membela dirinya adakalanya dengan tebusan harta dan adakalanya dengan bantuan anak-anaknya. (Dan mereka adalah penghuni neraka, kekal mereka di dalamnya.)",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["لَن","tidak pernah"],["تُغْنِىَ","akan mendapat manfaat"],["عَنْهُمْ","[untuk] mereka"],["أَمْوَٰلُهُمْ","kekayaan mereka"],["وَلَآ","dan bukan"],["أَوْلَـٰدُهُم","anak-anak mereka"],["مِّنَ","terhadap"],["ٱللَّهِ","Allah"],["شَيْـًۭٔا ۖ","sesuatu"],["وَأُو۟لَـٰٓئِكَ","dan mereka"],["أَصْحَـٰبُ","(adalah) para sahabat"],["ٱلنَّارِ ۚ","(dari) api"],["هُمْ","mereka"],["فِيهَا","di dalamnya"],["خَـٰلِدُونَ","(akan) kekal selama-lamanya"]]],"410":["(Perumpamaan) atau sifat (harta yang mereka nafkahkan) maksudnya orang-orang kafir (dalam kehidupan dunia) yakni dalam memusuhi Nabi bahkan bersedekah dan sebagainya (seperti angin yang mengandung udara yang sangat dingin yang menimpa tanaman suatu kaum yang menganiaya diri mereka sendiri) dengan kekafiran dan berbuat maksiat (lalu dirusakkannya) tanaman itu hingga mereka tidak memperoleh manfaat darinya. Maka demikianlah pula nafkah-nafkah mereka tadi habis tidak membawa manfaat apa-apa. (Allah tidaklah menganiaya mereka) dengan lenyapnya harta benda itu tadi (tetapi merekalah yang menganiaya diri mereka sendiri) dengan kekafiran yang menyebabkan musnahnya harta mereka.",[["مَثَلُ","Contoh"],["مَا","apa"],["يُنفِقُونَ","mereka belanjakan"],["فِى","dalam"],["هَـٰذِهِ","ini"],["ٱلْحَيَوٰةِ","[the] kehidupan"],["ٱلدُّنْيَا","dunia"],["كَمَثَلِ","(adalah) seperti (the) contoh"],["رِيحٍۢ","(dari) angin"],["فِيهَا","di dalamnya"],["صِرٌّ","(adalah) fros"],["أَصَابَتْ","ia melanda"],["حَرْثَ","(the) tuaian"],["قَوْمٍۢ","(dari) suatu kaum"],["ظَلَمُوٓا۟","siapa yang salah"],["أَنفُسَهُمْ","diri mereka"],["فَأَهْلَكَتْهُ ۚ","kemudian memusnahkannya"],["وَمَا","Dan tidak"],["ظَلَمَهُمُ","(telah) menzalimi mereka"],["ٱللَّهُ","Allah"],["وَلَـٰكِنْ","[dan] tetapi"],["أَنفُسَهُمْ","diri mereka"],["يَظْلِمُونَ","mereka melakukan kesalahan"]]],"411":["(Hai orang-orang yang beriman! Janganlah kamu ambil sebagai orang-orang kepercayaan) maksudnya sebagai teman-teman akrab tempat kamu membukakan rahasia kamu (orang-orang yang di luar kalanganmu) maksudnya orang lain, misalnya orang Yahudi, Nasrani dan munafik (tidak henti-hentinya mereka menimbulkan kesusahan bagimu) khabaala dijadikan manshub karena dihilangkannya huruf khafadh dan arti kalimat ialah mereka tidak putus-putusnya hendak membinasakan kamu (mereka ingin) atau mencita-citakan (supaya kamu menderita) artinya berada dalam puncak kesusahan. (Telah nyata) tampak (kebencian) permusuhan terhadapmu (dari mulut-mulut mereka) dengan menjelekkan kamu dan membukakan rahasia kamu kepada orang-orang musyrik (dan apa yang disembunyikan oleh hati mereka) berupa permusuhan (lebih besar lagi. Sungguh telah Kami jelaskan kepada kamu tanda-tanda) permusuhan mereka itu (jika kamu memikirkan)nya. Maka janganlah kamu ambil mereka itu sebagai orang-orang kepercayaan.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَتَّخِذُوا۟","ambil"],["بِطَانَةًۭ","(sebagai) intim"],["مِّن","daripada"],["دُونِكُمْ","selain diri kamu sendiri"],["لَا","tidak"],["يَأْلُونَكُمْ","mereka akan menyelamatkan kamu"],["خَبَالًۭا","(sebarang) kehancuran"],["وَدُّوا۟","Mereka mahu"],["مَا","apa"],["عَنِتُّمْ","menyusahkan kamu"],["قَدْ","Sesungguhnya"],["بَدَتِ","(telah menjadi) jelas"],["ٱلْبَغْضَآءُ","kebencian itu"],["مِنْ","daripada"],["أَفْوَٰهِهِمْ","mulut mereka"],["وَمَا","dan apa"],["تُخْفِى","menyembunyikan"],["صُدُورُهُمْ","buah dada mereka"],["أَكْبَرُ ۚ","(adalah) lebih besar"],["قَدْ","Sungguh"],["بَيَّنَّا","Kami membuat jelas"],["لَكُمُ","bagi kamu"],["ٱلْـَٔايَـٰتِ ۖ","ayat-ayat"],["إِن","jika"],["كُنتُمْ","kamu dahulu"],["تَعْقِلُونَ","(untuk menggunakan) alasan"]]],"412":["(Begitulah) sebagai peringatan (kamu) hai (orang-orang) yang beriman (kalian mencintai mereka) karena akrabnya persaudaraannya dengan kamu (tetapi mereka tidak mencintai kamu) karena perbedaan agamamu dengan agama mereka (dan kamu beriman kepada kitab-kitab kesemuanya) artinya kepada semua kitab, tetapi mereka tidak beriman kepada Kitabmu. (Jika mereka menjumpai kamu, mereka berkata, \"Kami beriman,\" dan apabila mereka telah berada dalam kalangan mereka sendiri, mereka menggigit ujung-ujung jari mereka disebabkan teramat marah kepadamu) melihat kerukunan kamu. Kemarahan diibaratkan dengan menggigit ujung-ujung jari, walaupun tidak sebenarnya terjadi. (Katakanlah, \"Matilah kamu dengan kemarahanmu itu!\") artinya tetaplah dalam keadaan demikian sampai kamu mati, karena tidak akan pernah kamu melihat hal-hal yang akan menyenangkan hatimu! (Sesungguhnya Allah mengetahui apa yang terdapat di dalam dada) maksudnya segala isi hati termasuk apa yang mereka sembunyikan.",[["هَـٰٓأَنتُمْ","Lo! kamu adalah"],["أُو۟لَآءِ","mereka"],["تُحِبُّونَهُمْ","kamu sayang mereka"],["وَلَا","tetapi tidak"],["يُحِبُّونَكُمْ","mereka sayang kamu"],["وَتُؤْمِنُونَ","dan kamu beriman"],["بِٱلْكِتَـٰبِ","dalam Kitab"],["كُلِّهِۦ","semua itu"],["وَإِذَا","Dan apabila"],["لَقُوكُمْ","mereka berjumpa dengan kamu"],["قَالُوٓا۟","mereka berkata"],["ءَامَنَّا","Kami beriman"],["وَإِذَا","Dan apabila"],["خَلَوْا۟","mereka bersendirian"],["عَضُّوا۟","mereka menggigit"],["عَلَيْكُمُ","pada kamu"],["ٱلْأَنَامِلَ","hujung jari"],["مِنَ","(keluar) daripada"],["ٱلْغَيْظِ ۚ","[kemarahan]"],["قُلْ","Katakanlah"],["مُوتُوا۟","mati"],["بِغَيْظِكُمْ ۗ","dalam kemarahan kamu"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","(adalah) Maha Mengetahui"],["بِذَاتِ","tentang apa"],["ٱلصُّدُورِ","(ada dalam) buah dada"]]],"413":["(Jika kamu disentuh) ditimpa (oleh kebaikan) atau nikmat, seperti kemenangan atau harta rampasan (mereka merasa kecewa) atau berdukacita (sebaliknya jika kamu ditimpa bencana) seperti kekalahan dan kekeringan (mereka gembira karenanya) jumlah syarat yang kedua berhubungan dengan syarat yang sebelumnya, sedangkan di antara keduanya interupsi atau kalimat sela. Makna ayat, bahwa mereka mati-matian dalam memusuhi kamu, maka kenapa kamu mempercayai mereka, jauhilah mereka itu! (Jika kamu bersabar) terhadap gangguan mereka (dan bertakwa) kepada Allah hingga tidak mempercayai mereka dan sebagainya (maka tidaklah akan mendatangkan kemudaratan) bacaannya 'laa yadhirkum' atau 'laa yadhurrukum' (tipu daya mereka sedikit pun. Sesungguhnya Allah terhadap apa yang mereka lakukan) dengan 'ya' dan 'ta' (meliputi) mengetahui dan akan memberikan balasan",[["إِن","Jika"],["تَمْسَسْكُمْ","menyentuh kamu"],["حَسَنَةٌۭ","yang baik"],["تَسُؤْهُمْ","ia menyedihkan mereka"],["وَإِن","dan jika"],["تُصِبْكُمْ","menyerang kamu"],["سَيِّئَةٌۭ","musibah"],["يَفْرَحُوا۟","mereka bergembira"],["بِهَا ۖ","padanya"],["وَإِن","Dan jika"],["تَصْبِرُوا۟","kamu sabar"],["وَتَتَّقُوا۟","dan bertakwalah kepada Allah"],["لَا","tidak"],["يَضُرُّكُمْ","akan membahayakan kamu"],["كَيْدُهُمْ","plot mereka"],["شَيْـًٔا ۗ","(dalam) apa-apa"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"],["مُحِيطٌۭ","(adalah) Merangkumi"]]],"414":["(Dan) ingatlah hai Muhammad (ketika kamu berangkat di pagi hari dari keluargamu) yakni dari Madinah (untuk menempatkan orang-orang beriman pada beberapa tempat) atau markas di mana mereka bertahan (untuk berperang. Dan Allah Maha Mendengar) akan ucapanmu (lagi Maha Mengetahui) peri keadaanmu. Peristiwa ini terjadi pada waktu perang Uhud. Nabi saw. keluar dengan membawa 1000 atau 950 orang tentara sedangkan kaum musyrikin berjumlah sebanyak 3000 orang. Nabi saw. menduduki posisinya di lereng bukit Uhud pada hari Sabtu tanggal 7 Syawal tahun ketiga Hijriah. Punggung beliau dan punggung tentaranya menghadap ke arah bukit Uhud lalu mengatur barisan mereka dan menempatkan pasukan panah yang dipimpin oleh Abdullah bin Jubair di puncak bukit seraya bersabda, \"Hujani mereka dengan anak panah dari sini agar mereka tidak menyerang dari belakang dan jangan tinggalkan tempat ini biar sekali pun tidak kalah atau pun menang!\"",[["وَإِذْ","Dan apabila"],["غَدَوْتَ","kamu pergi awal pagi"],["مِنْ","daripada"],["أَهْلِكَ","rumah tangga kamu"],["تُبَوِّئُ","untuk menghantar"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["مَقَـٰعِدَ","(untuk mengambil) jawatan"],["لِلْقِتَالِ ۗ","untuk pertempuran"],["وَٱللَّهُ","Dan Allah"],["سَمِيعٌ","(ialah) Maha Mendengar"],["عَلِيمٌ","Maha Mengetahui"]]],"415":["(Ketika) badal dari idz yang sebelumnya (dua golongan daripadamu bermaksud) yakni Bani Salamah dan Bani Haritsah yang merupakan dua sayap tentara (hendak mundur) karena takut berperang dan mengikuti langkah Abdullah bin Ubai pemimpin golongan munafik yang menarik diri dari peperangan bersama sahabat-sahabatnya, katanya, \"Apa gunanya kita membunuh diri dan anak-anak kita?\" Lalu katanya kepada Abu Jabir As-Salami yang memintanya agar membela Nabi dan diri mereka sendiri, \"Sekiranya kami pandai berperang, tentulah kami akan turut bersama kamu,\" maka Allah pun meneguhkan pendirian kedua golongan tadi hingga mereka tidak jadi menarik diri dari medan pertempuran (sedangkan Allah menjadi penolong bagi kedua golongan itu dan karena itu hendaklah kepada Allah orang-orang beriman bertawakal) hanya percaya kepada-Nya dan tidak kepada selain-Nya. Dan ketika mereka berhasil mengalahkan musuh, maka untuk mengingatkan mereka akan nikmat Allah turunlah ayat:",[["إِذْ","Apabila"],["هَمَّت","cenderung"],["طَّآئِفَتَانِ","dua pihak"],["مِنكُمْ","antara kamu"],["أَن","bahawa"],["تَفْشَلَا","mereka kehilangan hati"],["وَٱللَّهُ","tetapi Allah"],["وَلِيُّهُمَا ۗ","(adalah) pelindung mereka"],["وَعَلَى","Dan seterusnya"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","hendaklah meletakkan amanah (mereka)."],["ٱلْمُؤْمِنُونَ","orang yang beriman"]]],"416":["(Sungguh, Allah telah menolong kamu di Badar) suatu tempat di antara Mekah dan Madinah (padahal kamu orang-orang yang lemah) disebabkan bilangan dan persenjataan yang sedikit (maka bertakwalah kepada Allah, supaya kamu menjadi orang-orang yang bersyukur) akan nikmat karunia-Nya",[["وَلَقَدْ","Dan sungguh"],["نَصَرَكُمُ","membantu kamu"],["ٱللَّهُ","Allah"],["بِبَدْرٍۢ","dalam Badar"],["وَأَنتُمْ","semasa kamu (sedang)"],["أَذِلَّةٌۭ ۖ","lemah"],["فَٱتَّقُوا۟","Jadi takut"],["ٱللَّهَ","Allah"],["لَعَلَّكُمْ","supaya kamu"],["تَشْكُرُونَ","(bersyukur)."]]],"417":["(Ketika) zharfu zaman bagi datangnya pertolongan (kamu mengatakan kepada orang-orang beriman) menjanjikan demi ketenteraman hati mereka (\"Tidakkah cukup bagi kamu jika kamu dibantu Tuhanmu dengan tiga ribu malaikat yang diturunkan.\") ada yang membaca munzaliina dan ada pula munazzaliina.",[["إِذْ","Apabila"],["تَقُولُ","kamu kata"],["لِلْمُؤْمِنِينَ","kepada orang yang beriman"],["أَلَن","Bukankah"],["يَكْفِيَكُمْ","cukup untuk kamu"],["أَن","bahawa"],["يُمِدَّكُمْ","menguatkan kamu"],["رَبُّكُم","Tuhanmu"],["بِثَلَـٰثَةِ","dengan tiga"],["ءَالَـٰفٍۢ","ribu [s]"],["مِّنَ","[daripada]"],["ٱلْمَلَـٰٓئِكَةِ","[para] Malaikat"],["مُنزَلِينَ","[yang] diturunkan"]]],"418":["(Ya) itu cukup bagi kamu. Dalam surah Al-Anfal disebutkan seribu yakni sebagai bantuan pertama kemudian menjadi tiga ribu lalu lima ribu sebagaimana firman Allah swt.: (Jika kamu bersabar) dalam menghadapi musuh (dan bertakwa) kepada Allah dalam menghindari pertikaian (dan mereka datang) yakni orang-orang musyrikin (pada ketika itu juga) buat menyerang kamu (maka Tuhanmu akan membantu kamu dengan lima ribu malaikat yang memakai tanda) ada yang membaca musawwimiina dan ada pula musawwamiina keduanya berarti memakai tanda. Sungguh mereka itu telah menunjukkan kesabaran sehingga Allah pun menepati janji-Nya yaitu dengan ikut sertanya pasukan malaikat di atas kuda-kuda belang dengan memakai serban berwarna kuning atau putih yang mereka lepaskan teruntai di atas bahu.",[["بَلَىٰٓ ۚ","ya"],["إِن","jika"],["تَصْبِرُوا۟","kamu sabar"],["وَتَتَّقُوا۟","dan bertakwalah kepada Allah"],["وَيَأْتُوكُم","dan mereka datang kepada kamu"],["مِّن","[daripada]"],["فَوْرِهِمْ","tiba-tiba"],["هَـٰذَا","[ini]"],["يُمْدِدْكُمْ","akan menguatkan kamu"],["رَبُّكُم","Tuhanmu"],["بِخَمْسَةِ","dengan lima"],["ءَالَـٰفٍۢ","ribu [s]"],["مِّنَ","[daripada]"],["ٱلْمَلَـٰٓئِكَةِ","[para] Malaikat"],["مُسَوِّمِينَ","[yang] mempunyai markah"]]],"419":["(Allah tidaklah menjadikannya) maksudnya pengiriman bala bantuan itu (melainkan sebagai berita gembira bagi kamu) dengan kemenangan (dan agar tenteram hatimu karenanya) jadi janganlah kamu cemas melihat banyaknya musuh dan sedikitnya bilanganmu. (Dan tidaklah kemenangan itu kecuali dari sisi Allah Yang Maha Tangguh lagi Maha Bijaksana) yang memberikannya kepada siapa yang dikehendaki-Nya dan bukan kepada yang banyak jumlah tentaranya.",[["وَمَا","Dan tidak"],["جَعَلَهُ","berjaya"],["ٱللَّهُ","Allah"],["إِلَّا","kecuali"],["بُشْرَىٰ","(sebagai) berita gembira"],["لَكُمْ","bagi kamu"],["وَلِتَطْمَئِنَّ","dan untuk meyakinkan"],["قُلُوبُكُم","hati kamu"],["بِهِۦ ۗ","dengannya"],["وَمَا","Dan (ada) tidak"],["ٱلنَّصْرُ","[the] kemenangan"],["إِلَّا","kecuali"],["مِنْ","daripada"],["عِندِ","[dekat]"],["ٱللَّهِ","Allah"],["ٱلْعَزِيزِ","Yang Maha Perkasa"],["ٱلْحَكِيمِ","Yang Maha Bijaksana"]]],"420":["(Yaitu untuk memotong) berkaitan dengan kemenanganmu itu dan maksudnya ialah membinasakan (segolongan orang-orang yang kafir) dengan terbunuh dan tertawan (atau untuk menjadikan mereka hina dina) disebabkan kekalahan (sehingga mereka kembali dengan tangan hampa) tidak memperoleh apa yang mereka harapkan. Ayat berikut ini turun ketika gigi depan Nabi saw. patah dan wajahnya berlumuran darah di waktu perang Uhud, sampai beliau bersabda, \"Bagaimana suatu kaum akan beroleh keberuntungan, jika mereka berani melumuri wajah Nabi mereka dengan darah!\"",[["لِيَقْطَعَ","Supaya Dia dapat memutuskan"],["طَرَفًۭا","bahagian"],["مِّنَ","daripada"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَوْ","atau"],["يَكْبِتَهُمْ","menindas mereka"],["فَيَنقَلِبُوا۟","supaya mereka berpaling ke belakang"],["خَآئِبِينَ","kecewa"]]],"421":["(Tak ada sedikit pun hakmu untuk campur tangan dalam urusan mereka itu) tetapi semua itu urusan Allah, maka hendaklah kamu bersabar (apakah) artinya hingga (Allah menerima tobat mereka) dengan masuknya mereka ke dalam agama Islam (atau menyiksa mereka, karena sesungguhnya mereka orang-orang yang aniaya) disebabkan kekafiran mereka.",[["لَيْسَ","Tidak"],["لَكَ","bagi kamu"],["مِنَ","daripada"],["ٱلْأَمْرِ","keputusan itu"],["شَىْءٌ","(dari) apa-apa"],["أَوْ","sama ada"],["يَتُوبَ","Dia berpaling"],["عَلَيْهِمْ","kepada mereka"],["أَوْ","atau"],["يُعَذِّبَهُمْ","menghukum mereka"],["فَإِنَّهُمْ","kerana sesungguhnya mereka"],["ظَـٰلِمُونَ","(adalah) orang-orang yang zalim"]]],"422":["(Kepunyaan Allahlah apa yang ada di langit dan apa yang ada di bumi) baik sebagai milik maupun sebagai makhluk atau hamba-Nya (diampuni-Nya siapa yang dikehendaki-Nya) untuk diampuni (dan disiksa-Nya siapa yang dikehendaki) untuk disiksa (dan Allah Maha Pengampun) kekasih-kekasih-Nya (lagi Maha Penyayang) terhadap orang-orang yang taat kepada-Nya.",[["وَلِلَّهِ","Dan kepunyaan Allah"],["مَا","apa"],["فِى","(berada) dalam"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَمَا","dan apa"],["فِى","(berada) dalam"],["ٱلْأَرْضِ ۚ","bumi"],["يَغْفِرُ","Dia memaafkan"],["لِمَن","[untuk] siapa"],["يَشَآءُ","Dia kehendaki"],["وَيُعَذِّبُ","dan menghukum"],["مَن","yang"],["يَشَآءُ ۚ","Dia kehendaki"],["وَٱللَّهُ","Dan Allah"],["غَفُورٌۭ","Maha Pengampun"],["رَّحِيمٌۭ","Maha Mengasihani"]]],"423":["(Hai orang-orang yang beriman, janganlah kamu memakan riba dengan berlipat ganda) bacaannya ada yang memakai alif dan ada pula yang tidak, maksudnya ialah memberikan tambahan pada harta yang diutang yang ditangguhkan pembayarannya dari tempo yang telah ditetapkan (dan bertakwalah kamu kepada Allah) dengan menghindarinya (supaya kamu beroleh keberuntungan) atau hasil yang gemilang.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَأْكُلُوا۟","makan"],["ٱلرِّبَوٰٓا۟","riba itu"],["أَضْعَـٰفًۭا","berganda"],["مُّضَـٰعَفَةًۭ ۖ","berganda-ganda"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","(berjaya)."]]],"424":["(Jagalah dirimu dari api neraka yang disediakan bagi orang-orang yang kafir) janganlah kamu sampai disiksa di dalamnya",[["وَٱتَّقُوا۟","Dan ketakutan"],["ٱلنَّارَ","neraka"],["ٱلَّتِىٓ","yang"],["أُعِدَّتْ","disediakan"],["لِلْكَـٰفِرِينَ","bagi orang-orang kafir"]]],"425":["(Taatilah olehmu Allah dan Rasul, supaya kamu beroleh rahmat).",[["وَأَطِيعُوا۟","Dan taat"],["ٱللَّهَ","Allah"],["وَٱلرَّسُولَ","dan Rasul"],["لَعَلَّكُمْ","supaya kamu"],["تُرْحَمُونَ","mendapat rahmat"]]],"426":["(Dan bersegeralah kamu) dengan atau tanpa wau (kepada keampunan dari Tuhanmu dan kepada surga yang luasnya seluas langit dan bumi) artinya seluas langit dan bumi bila keduanya disambung; sedangkan '`ardh' artinya ialah luas (yang disediakan bagi orang-orang yang bertakwa) kepada Allah dengan mengerjakan taat dan meninggalkan maksiat.",[["۞ وَسَارِعُوٓا۟","Dan bersegera"],["إِلَىٰ","kepada"],["مَغْفِرَةٍۢ","pengampunan"],["مِّن","daripada"],["رَّبِّكُمْ","Tuhanmu"],["وَجَنَّةٍ","dan sebuah Taman"],["عَرْضُهَا","lebarnya"],["ٱلسَّمَـٰوَٰتُ","(seperti) langit"],["وَٱلْأَرْضُ","dan bumi"],["أُعِدَّتْ","disediakan"],["لِلْمُتَّقِينَ","bagi orang yang bertaqwa"]]],"427":["(Yaitu orang yang mengeluarkan nafkah) dalam menaati Allah (baik di waktu lapang maupun di waktu sempit dan yang dapat menahan amarahnya) hingga tidak melampiaskannya walaupun sebenarnya ia sanggup (dan yang memaafkan kesalahan manusia) yang melakukan keaniayaan kepadanya tanpa membalasnya (dan Allah menyukai orang-orang yang berbuat kebaikan) seperti pekerjaan-pekerjaan yang disebutkan itu dan akan memberi mereka balasan.",[["ٱلَّذِينَ","Orang yang"],["يُنفِقُونَ","berbelanja"],["فِى","dalam"],["ٱلسَّرَّآءِ","[the] kemudahan"],["وَٱلضَّرَّآءِ","dan (dalam) kesusahan"],["وَٱلْكَـٰظِمِينَ","dan mereka yang menahan"],["ٱلْغَيْظَ","kemarahan itu"],["وَٱلْعَافِينَ","dan orang-orang yang memaafkan"],["عَنِ","[dari]"],["ٱلنَّاسِ ۗ","rakyat"],["وَٱللَّهُ","dan Allah"],["يُحِبُّ","suka"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"428":["(Dan juga orang-orang yang apabila mereka berbuat kekejian) artinya dosa yang keji seperti perzinahan (atau menganiaya diri mereka sendiri) artinya melakukan dosa yang lebih ringan dari itu misalnya mencium (mereka ingat kepada Allah) maksudnya ingat akan ancaman-Nya (lalu memohon ampun terhadap dosa-dosa mereka dan siapakah) artinya tidak ada (yang dapat mengampuni dosa itu melainkan Allah. Dan mereka tidak meneruskan perbuatan mereka itu) menghentikannya sama sekali (sedangkan mereka mengetahui) bahwa apa yang mereka lakukan itu adalah perbuatan maksiat adanya.",[["وَٱلَّذِينَ","Dan mereka"],["إِذَا","apabila"],["فَعَلُوا۟","mereka lakukan"],["فَـٰحِشَةً","maksiat"],["أَوْ","atau"],["ظَلَمُوٓا۟","dizalimi"],["أَنفُسَهُمْ","diri mereka sendiri"],["ذَكَرُوا۟","mereka ingat"],["ٱللَّهَ","Allah"],["فَٱسْتَغْفَرُوا۟","kemudian minta ampun"],["لِذُنُوبِهِمْ","kerana dosa mereka"],["وَمَن","dan siapa"],["يَغْفِرُ","(boleh) memaafkan"],["ٱلذُّنُوبَ","dosa-dosa"],["إِلَّا","kecuali"],["ٱللَّهُ","Allah"],["وَلَمْ","Dan tidak"],["يُصِرُّوا۟","mereka berterusan"],["عَلَىٰ","pada"],["مَا","apa"],["فَعَلُوا۟","mereka lakukan"],["وَهُمْ","sedangkan mereka"],["يَعْلَمُونَ","mengetahui"]]],"429":["(Mereka itu balasannya ialah ampunan dari Tuhan mereka dan surga yang di bawahnya mengalir anak-anak sungai, kekal mereka di dalamnya) menjadi hal artinya ditakdirkan kekal jika mereka beruntung memasukinya (dan itulah sebaik-baiknya pahala bagi orang yang beramal) artinya pahala bagi orang-orang yang mengerjakan perbuatan terpuji ini.",[["أُو۟لَـٰٓئِكَ","Itu"],["جَزَآؤُهُم","ganjaran mereka"],["مَّغْفِرَةٌۭ","(ialah) pengampunan"],["مِّن","daripada"],["رَّبِّهِمْ","Tuhan mereka"],["وَجَنَّـٰتٌۭ","dan Taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawahnya"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["وَنِعْمَ","Dan cemerlang"],["أَجْرُ","pahala"],["ٱلْعَـٰمِلِينَ","(untuk) pekerja (yang soleh)."]]],"430":["Ayat ini diturunkan berkenaan dengan kekalahan dalam perang Uhud (Sesungguhnya telah berlalu sebelum kamu sunah-sunah) artinya cara-cara Allah menghadapi orang-orang kafir yaitu menangguhkan kebinasaan mereka, lalu menghancurkan mereka secara tiba-tiba (maka berjalanlah kamu) hai orang-orang beriman (di muka bumi, dan lihatlah betapa akibat orang-orang yang mendustakan) para rasul, artinya kesudahan nasib mereka berupa kebinasaan. Maka janganlah kamu bersedih hati atas kemenangan mereka, karena Aku hanyalah menangguhkan kebinasaan mereka itu hingga pada saatnya nanti.",[["قَدْ","Sesungguhnya"],["خَلَتْ","lulus"],["مِن","daripada"],["قَبْلِكُمْ","sebelum kamu"],["سُنَنٌۭ","situasi"],["فَسِيرُوا۟","kemudian mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["فَٱنظُرُوا۟","dan lihat"],["كَيْفَ","bagaimana"],["كَانَ","adalah"],["عَـٰقِبَةُ","(akhirnya)."],["ٱلْمُكَذِّبِينَ","(dari) orang-orang yang mendustakan"]]],"431":["(Ini) maksudnya Alquran ini (menjadi penerang bagi manusia) artinya semuanya (dan petunjuk) dari kesesatan (serta pelajaran bagi orang-orang yang bertakwa) di antara mereka.",[["هَـٰذَا","Ini"],["بَيَانٌۭ","(adalah) pengisytiharan"],["لِّلنَّاسِ","untuk rakyat"],["وَهُدًۭى","dan bimbingan"],["وَمَوْعِظَةٌۭ","dan teguran"],["لِّلْمُتَّقِينَ","bagi yang bertakwa"]]],"432":["(Janganlah kamu merasa lemah) dalam memerangi orang-orang kafir (dan jangan pula bersedih hati) atas sesuatu musibah yang menimpa dirimu (padahal kamu orang-orang yang tertinggi) hingga mampu mengalahkan mereka (jika kamu orang-orang yang beriman) maksudnya benar-benar beriman sedangkan yang menjadi jawab syarat ialah apa yang ditunjukkan oleh makna kalimat-kalimat yang sebelumnya.",[["وَلَا","Dan jangan"],["تَهِنُوا۟","melemahkan"],["وَلَا","dan jangan"],["تَحْزَنُوا۟","bersedih"],["وَأَنتُمُ","dan kamu (akan)"],["ٱلْأَعْلَوْنَ","[yang] atasan"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"433":["(Jika kamu ditimpa) seperti pada perang Uhud (oleh luka-luka) qarh atau qurh, artinya ialah penderitaan disebabkan luka dan sebagainya (maka sesungguhnya kaum kafir itu pun telah ditimpa pula oleh luka yang serupa) di waktu perang Badar. (Dan hari-hari itu Kami pergilirkan) silih berganti (di antara manusia) misalnya sekarang masa kejayaan bagi satu golongan dan esok bagi golongan lainnya agar mereka sama-sama menarik pelajaran (dan supaya Allah mengetahui) secara lahiriah (orang-orang yang beriman) secara ikhlas dari yang tidak (dan supaya sebagian kamu dijadikan-Nya syuhada) artinya dimuliakan-Nya dengan mati syahid. (Dan Allah tidak menyukai orang-orang yang aniaya) yakni orang-orang kafir yang akan menerima hukuman daripada-Nya. Seumpama mereka diberi-Nya nikmat, itu hanyalah untuk mendekatkan mereka kepada siksa.",[["إِن","Jika"],["يَمْسَسْكُمْ","tersentuh kamu"],["قَرْحٌۭ","luka"],["فَقَدْ","jadi pasti"],["مَسَّ","(telah) menyentuh"],["ٱلْقَوْمَ","manusia"],["قَرْحٌۭ","luka"],["مِّثْلُهُۥ ۚ","suka"],["وَتِلْكَ","Dan ini"],["ٱلْأَيَّامُ","[the] hari"],["نُدَاوِلُهَا","Kami menggantikan mereka"],["بَيْنَ","antara"],["ٱلنَّاسِ","manusia"],["وَلِيَعْلَمَ","[dan] supaya jelas"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَيَتَّخِذَ","dan ambil"],["مِنكُمْ","daripada kamu"],["شُهَدَآءَ ۗ","syuhada"],["وَٱللَّهُ","Dan Allah"],["لَا","tidak"],["يُحِبُّ","cinta"],["ٱلظَّـٰلِمِينَ","orang yang zalim"]]],"434":["(Agar Allah menyucikan orang-orang yang beriman) artinya membersihkan mereka dari dosa dengan musibah yang menimpa diri mereka itu (serta membinasakan orang-orang yang kafir).",[["وَلِيُمَحِّصَ","Dan supaya dapat menyucikan"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","orang yang"],["ءَامَنُوا۟","beriman"],["وَيَمْحَقَ","dan memusnahkan"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"435":["(Atau) artinya apakah (kamu mengira bahwa kamu akan masuk surga padahal belumlah diketahui oleh Allah orang-orang yang berjihad di antara kamu) yakni secara lahirnya (dan belum diketahui-Nya orang-orang yang sabar) dalam menghadapi kesusahan.",[["أَمْ","Atau"],["حَسِبْتُمْ","adakah kamu fikir"],["أَن","bahawa"],["تَدْخُلُوا۟","kamu akan masuk"],["ٱلْجَنَّةَ","Syurga"],["وَلَمَّا","sementara belum lagi"],["يَعْلَمِ","terserlah"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","orang yang"],["جَـٰهَدُوا۟","berusaha keras"],["مِنكُمْ","antara kamu"],["وَيَعْلَمَ","dan terbukti"],["ٱلصَّـٰبِرِينَ","yang tabah"]]],"436":["(Sesungguhnya dulu kamu mengharapkan) asalnya tatamannauna lalu salah satu dari ta-nya dibuang (kematian sebelum kamu menemuinya) artinya kamu pernah mengatakan dulu, \"Wahai kiranya kami dapat menemui suatu hari seperti hari perang Badar agar kami menemui mati syahid sebagaimana dialami oleh kawan-kawan kami dulu.\" (Sekarang kamu telah melihatnya) maksudnya yang menjadi sebab dan asal usulnya yaitu peperangan itu sendiri (sedangkan kamu menyaksikannya) dapat merenungkannya bagaimana seharusnya lalu kenapa kamu dapat dikalahkan? Dan mengenai kekalahan itu turun ayat bahwa sebabnya ialah tatkala disebarkan berita bahwa Nabi saw. telah terbunuh sementara orang-orang munafik meneriakkan, \"Karena ia telah terbunuh maka kembalilah kalian kepada agama kalian!\"",[["وَلَقَدْ","Dan sungguh"],["كُنتُمْ","kamu pernah"],["تَمَنَّوْنَ","keinginan"],["ٱلْمَوْتَ","(untuk) kematian"],["مِن","daripada"],["قَبْلِ","sebelum"],["أَن","[bahawa]"],["تَلْقَوْهُ","kamu bertemu dengannya"],["فَقَدْ","maka sesungguhnya"],["رَأَيْتُمُوهُ","kamu telah melihatnya"],["وَأَنتُمْ","semasa kamu (sedang)"],["تَنظُرُونَ","melihat pada"]]],"437":["(Muhammad itu tidak lain hanyalah seorang rasul yang sebelumnya telah berlalu beberapa orang rasul. Apakah jika ia wafat atau terbunuh) seperti lainnya (kamu berbalik ke belakang) maksudnya kembali menjadi kafir. Kalimat akhir merupakan pertanyaan yang berarti sanggahan, artinya bukankah ia bukan sembahan kenapa kamu kembali? (Barang siapa yang berbalik ke belakang, murtad, maka tidaklah ia memberi mudarat kepada Allah sedikit pun) sebaliknya hanya memberi mudarat kepada dirinya sendiri (dan Allah akan memberi balasan kepada orang-orang yang bersyukur) terhadap nikmat-karunia-Nya.",[["وَمَا","Dan tidak"],["مُحَمَّدٌ","(ialah) Muhammad"],["إِلَّا","kecuali"],["رَسُولٌۭ","seorang Rasul"],["قَدْ","sudah tentu"],["خَلَتْ","meninggal dunia"],["مِن","daripada"],["قَبْلِهِ","sebelum dia"],["ٱلرُّسُلُ ۚ","Rasul-rasul (yang lain)."],["أَفَإِي۟ن","Jadi jika"],["مَّاتَ","dia meninggal dunia"],["أَوْ","atau"],["قُتِلَ","dibunuh"],["ٱنقَلَبْتُمْ","adakah kamu akan berpatah balik"],["عَلَىٰٓ","pada"],["أَعْقَـٰبِكُمْ ۚ","tumit kamu"],["وَمَن","Dan sesiapa"],["يَنقَلِبْ","berpatah balik"],["عَلَىٰ","pada"],["عَقِبَيْهِ","tumitnya"],["فَلَن","maka tidak pernah"],["يَضُرَّ","adakah dia akan membahayakan"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا ۗ","(dalam) apa-apa"],["وَسَيَجْزِى","Dan akan memberi ganjaran"],["ٱللَّهُ","Allah"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"438":["(Setiap diri tidaklah akan mati kecuali dengan izin Allah) artinya dengan kada daripada-Nya (sebagai ketentuan) mashdar artinya ketentuan yang telah ditetapkan oleh Allah (yang telah ditetapkan waktunya) hingga tidak dapat dimajukan atau diundurkan. Lalu kenapa kamu menderita kekalahan, padahal kekalahan itu tidak dapat menolak kematian dan ketabahan takkan dapat mengakhiri kehidupan. (Barang siapa yang menghendaki) dengan amalannya (pahala dunia) artinya balasannya (Kami berikan itu kepadanya) artinya bagiannya di dunia tetapi di akhirat ia tidak mendapat apa-apa. (Dan barang siapa menghendaki pahala akhirat Kami berikan pula kepadanya) artinya pahalanya (dan Kami akan memberi balasan kepada orang-orang yang bersyukur).",[["وَمَا","Dan tidak"],["كَانَ","ialah"],["لِنَفْسٍ","untuk jiwa"],["أَن","bahawa"],["تَمُوتَ","dia mati"],["إِلَّا","kecuali"],["بِإِذْنِ","dengan izin (yang)"],["ٱللَّهِ","(milik) Allah"],["كِتَـٰبًۭا","(pada a) dekri"],["مُّؤَجَّلًۭا ۗ","ditentukan"],["وَمَن","Dan sesiapa"],["يُرِدْ","keinginan"],["ثَوَابَ","pahala"],["ٱلدُّنْيَا","(dari) dunia"],["نُؤْتِهِۦ","Kami akan memberinya"],["مِنْهَا","daripadanya"],["وَمَن","dan sesiapa"],["يُرِدْ","keinginan"],["ثَوَابَ","pahala"],["ٱلْـَٔاخِرَةِ","(dari) Akhirat"],["نُؤْتِهِۦ","Kami akan memberinya"],["مِنْهَا ۚ","daripadanya"],["وَسَنَجْزِى","Dan Kami akan membalasnya"],["ٱلشَّـٰكِرِينَ","yang bersyukur"]]],"439":["(Dan berapa banyaknya) 'ka-ayyin' sama artinya dengan 'kam' (nabi-nabi yang berperang) menurut satu qiraat 'qutila' yang berarti 'yang dibunuh'. Pelakunya ialah dhamir yang kembali kepada nabi (bersama mereka) menjadi khabar sedangkan mubtadanya ialah: (pengikut-pengikutnya yang amat banyak) yakni yang bertakwa (maka mereka tidak menjadi lemah) atau merasa takut (karena hal-hal yang menimpa mereka di jalan Allah) seperti mendapat luka dan terbunuhnya nabi-nabi dan para sahabat mereka (dan tidak menjadi lelah) menghadapi perjuangan (dan tidak pula menyerah) atau tunduk kepada musuh-musuh sebagaimana kamu lakukan ketika disiarkan orang berita bahwa Nabimu telah gugur. (Allah menyukai orang-orang yang sabar) dalam menerima bala hingga Allah berkenan memberikan imbalan kepadanya.",[["وَكَأَيِّن","Dan berapa banyak"],["مِّن","daripada"],["نَّبِىٍّۢ","seorang Nabi"],["قَـٰتَلَ","bergaduh"],["مَعَهُۥ","dengan dia"],["رِبِّيُّونَ","(adalah) alim ulama"],["كَثِيرٌۭ","ramai"],["فَمَا","Tetapi tidak"],["وَهَنُوا۟","mereka kehilangan hati"],["لِمَآ","bagi apa"],["أَصَابَهُمْ","menimpa mereka"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["وَمَا","dan bukan"],["ضَعُفُوا۟","mereka lemah"],["وَمَا","dan bukan"],["ٱسْتَكَانُوا۟ ۗ","mereka mengalah"],["وَٱللَّهُ","Dan Allah"],["يُحِبُّ","suka"],["ٱلصَّـٰبِرِينَ","yang sabar"]]],"440":["(Tak ada ucapan mereka) yakni ketika Nabi mereka dibunuh yang mereka terima dengan penuh kesabaran dan ketabahan itu (melainkan dengan berdoa, \"Wahai Tuhan kami! Ampunilah dosa kami dan keterlaluan kami) artinya tindakan kami yang melanggar batas (dalam urusan kami) sebagai pengakuan bahwa musibah yang menimpa mereka itu ialah karena jeleknya perbuatan mereka yang berarti menghancurkan diri mereka sendiri (dan tetapkanlah hati kami) dengan kekuatan menghadapi perjuangan (serta tolonglah kami terhadap kaum yang kafir.\")",[["وَمَا","Dan tidak"],["كَانَ","adalah"],["قَوْلَهُمْ","kata-kata mereka"],["إِلَّآ","kecuali"],["أَن","bahawa"],["قَالُوا۟","mereka berkata"],["رَبَّنَا","Wahai Tuhan kami"],["ٱغْفِرْ","maafkan"],["لَنَا","bagi kami"],["ذُنُوبَنَا","dosa kita"],["وَإِسْرَافَنَا","dan kelebihan kita"],["فِىٓ","dalam"],["أَمْرِنَا","urusan kita"],["وَثَبِّتْ","dan teguhkan"],["أَقْدَامَنَا","kaki kita"],["وَٱنصُرْنَا","dan berikan kami kemenangan"],["عَلَى","atas"],["ٱلْقَوْمِ","[rakyat]"],["ٱلْكَـٰفِرِينَ","orang kafir"]]],"441":["(Maka Allah pun memberi mereka pahala di dunia) berupa kemenangan dan harta rampasan (dan pahala yang baik di akhirat) maksudnya surga. Pahala yang baik ialah anugerah yang melebihi dari selayaknya (dan Allah menyukai orang-orang yang berbuat kebaikan).",[["فَـَٔاتَىٰهُمُ","Jadi memberi mereka"],["ٱللَّهُ","Allah"],["ثَوَابَ","pahala"],["ٱلدُّنْيَا","(dalam) dunia"],["وَحُسْنَ","dan baik"],["ثَوَابِ","pahala"],["ٱلْـَٔاخِرَةِ ۗ","(dalam) akhirat"],["وَٱللَّهُ","Dan Allah"],["يُحِبُّ","suka"],["ٱلْمُحْسِنِينَ","orang yang berbuat baik"]]],"442":["(Hai orang-orang yang beriman, jika kamu menaati orang-orang yang kafir) mengenai apa yang mereka perintahkan kepada kamu (tentulah mereka akan mengembalikan kamu ke belakang) maksudnya kepada kekafiran (hingga jadilah kamu orang-orang yang merugi).",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوٓا۟","beriman"],["إِن","Jika"],["تُطِيعُوا۟","kamu taat"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["يَرُدُّوكُمْ","mereka akan membalikkan kamu"],["عَلَىٰٓ","pada"],["أَعْقَـٰبِكُمْ","tumit kamu"],["فَتَنقَلِبُوا۟","maka kamu akan berpatah balik"],["خَـٰسِرِينَ","(sebagai) orang yang rugi"]]],"443":["(Tetapi Allahlah yang menjadi pelindungmu) pembelamu (dan Dialah sebaik-baik pembela) maka patuhlah kamu kepada-Nya dan bukan kepada selain-Nya.",[["بَلِ","Bahkan"],["ٱللَّهُ","Allah"],["مَوْلَىٰكُمْ ۖ","(ialah) Pelindungmu"],["وَهُوَ","dan Dia"],["خَيْرُ","(adalah) yang terbaik"],["ٱلنَّـٰصِرِينَ","(dari) para Penolong"]]],"444":["(Akan Kami masukkan ke dalam hati orang-orang kafir itu rasa takut) dibaca ru`b atau ru`ub. Setelah berangkat dari Uhud itu sebenarnya mereka bermaksud hendak kembali untuk membasmi kaum Muslimin tetapi tiba-tiba merasa ciut dan tidak jadi kembali (disebabkan mereka mempersekutukan Allah dengan sesuatu yang tidak diberi-Nya wewenang) sebagai alasan dalam penyembahan terhadap berhala (tempat tinggal mereka ialah neraka dan itulah seburuk-buruk tempat tinggal orang-orang yang aniaya) lagi kafir itu.",[["سَنُلْقِى","Kami akan membuang"],["فِى","dalam"],["قُلُوبِ","(the) hati"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["ٱلرُّعْبَ","keganasan"],["بِمَآ","kerana"],["أَشْرَكُوا۟","mereka bersekutu"],["بِٱللَّهِ","dengan Allah"],["مَا","apa"],["لَمْ","tidak"],["يُنَزِّلْ","Dia menurunkan"],["بِهِۦ","mengenainya"],["سُلْطَـٰنًۭا ۖ","mana-mana pihak berkuasa"],["وَمَأْوَىٰهُمُ","dan tempat perlindungan mereka"],["ٱلنَّارُ ۚ","(akan menjadi) Neraka"],["وَبِئْسَ","dan celaka"],["مَثْوَى","(adalah) tempat tinggal"],["ٱلظَّـٰلِمِينَ","[dari] orang-orang yang zalim"]]],"445":["(Dan sesungguhnya Allah telah memenuhi janji-Nya) kepadamu dengan memberikan kemenangan (ketika kamu membunuh mereka dengan izin-Nya) atau dengan kehendak-Nya (hingga saat kamu gagal) atau takut menghadapi peperangan (dan berselisih dalam urusan itu) yakni mengenai perintah Nabi saw. agar tetap bertahan di lereng bukit untuk memanah musuh di mana sebagian kamu mengatakan, \"Mari kita turun bukankah teman-teman kita sudah beroleh kemenangan?\" Sedangkan sebagian lagi berkata, \"Tidak, kita tidak boleh melanggar perintah Nabi saw.\" (dan kamu mendurhakai) perintahnya, lalu kamu tinggalkan markas demi mengharapkan harta rampasan (setelah diperlihatkan-Nya kepadamu) maksudnya oleh Allah (apa yang kamu sukai) yakni kemenangan. Mengenai jawab idzaa ditunjukkan oleh kalimat yang sebelumnya, artinya kamu terhalang beroleh kemenangan dari-Nya. (Di antaramu ada yang menghendaki dunia) lalu ditinggalkannya markas guna merebut harta rampasan (dan di antaramu ada yang menghendaki akhirat) maka ia tetap bertahan di tempat sampai ia gugur seperti Abdullah bin Jubair dan sahabat-sahabatnya. (Kemudian Allah memalingkan kamu) dihubungkan kepada jawaban idzaa yang diperkirakan berbunyi, \"Terpukul mundur karena menderita kekalahan\" (dari mereka) maksudnya orang-orang kafir (untuk mencoba kamu) artinya menguji mana-mana yang ikhlas di antaramu dari yang bukan. (Sesungguhnya Allah telah memaafkan kamu) atas kesalahan yang telah kamu lakukan (dan Allah mempunyai karunia terhadap orang-orang yang beriman) dengan memaafkan dan mengampuni mereka.",[["وَلَقَدْ","Dan sungguh"],["صَدَقَكُمُ","dipenuhi kepada kamu"],["ٱللَّهُ","Allah"],["وَعْدَهُۥٓ","janji dia"],["إِذْ","apabila"],["تَحُسُّونَهُم","kamu telah membunuh mereka"],["بِإِذْنِهِۦ ۖ","dengan izinNya"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["فَشِلْتُمْ","kamu hilang keberanian"],["وَتَنَـٰزَعْتُمْ","dan kamu jatuh ke dalam pertikaian"],["فِى","tentang"],["ٱلْأَمْرِ","perintah itu"],["وَعَصَيْتُم","dan kamu menderhaka"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["مَآ","[apa]"],["أَرَىٰكُم","Dia (telah) menunjukkan kepada kamu"],["مَّا","apa"],["تُحِبُّونَ ۚ","kamu sayang"],["مِنكُم","Di antara kamu"],["مَّن","(adalah beberapa) siapa"],["يُرِيدُ","keinginan"],["ٱلدُّنْيَا","dunia"],["وَمِنكُم","dan di antara kamu"],["مَّن","(adalah beberapa) siapa"],["يُرِيدُ","keinginan"],["ٱلْـَٔاخِرَةَ ۚ","akhirat"],["ثُمَّ","Kemudian"],["صَرَفَكُمْ","Dia melencongkan kamu"],["عَنْهُمْ","daripada mereka"],["لِيَبْتَلِيَكُمْ ۖ","supaya Dia menguji kamu"],["وَلَقَدْ","Dan pastinya"],["عَفَا","Dia memaafkan"],["عَنكُمْ ۗ","kamu"],["وَٱللَّهُ","Dan Allah"],["ذُو","(ialah) Pemilik"],["فَضْلٍ","(dari) Bounty"],["عَلَى","bagi"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"446":["(Ingatlah ketika kamu melarikan diri) dalam peperangan itu (dan tidak menoleh kepada seorang pun, sedang Rasul memanggil kamu dari belakangmu) seraya bersabda, \"Mari ke sini hai hamba-hamba Allah, marilah datang kepadaku!\" (Karena itu Allah menimpakan padamu kesedihan di atas kesedihan) yang kamu timpakan kepada Rasulullah dengan melanggar perintahnya. Ada pula yang mengatakan 'ba' itu berarti '`alaa' hingga maknanya ialah 'berlipat ganda', yaitu kesedihan di balik kesedihan karena luputnya harta rampasan (supaya kamu tidak) berkaitan dengan Allah 'memaafkan' atau menimpakan pada kalian (berduka cita terhadap apa yang luput dari kamu) yakni harta rampasan (begitu pula terhadap apa yang telah menimpamu) berupa pembunuhannya dan kekalahan (Allah Maha Mengetahui apa yang kamu kerjakan.)",[["۞ إِذْ","Apabila"],["تُصْعِدُونَ","kamu berlari naik bukit"],["وَلَا","dan bukan"],["تَلْوُۥنَ","melemparkan pandangan"],["عَلَىٰٓ","pada"],["أَحَدٍۢ","sesiapa sahaja"],["وَٱلرَّسُولُ","manakala Rasul"],["يَدْعُوكُمْ","sedang memanggil kamu"],["فِىٓ","[dalam]"],["أُخْرَىٰكُمْ","(dari) belakang kamu"],["فَأَثَـٰبَكُمْ","Maka (Dia) membalas kamu"],["غَمًّۢا","(dengan) kesusahan"],["بِغَمٍّۢ","pada kesusahan"],["لِّكَيْلَا","supaya tidak"],["تَحْزَنُوا۟","kamu bersedih"],["عَلَىٰ","atas"],["مَا","apa"],["فَاتَكُمْ","melarikan diri kamu"],["وَلَا","dan bukan"],["مَآ","apa"],["أَصَـٰبَكُمْ ۗ","(telah) menimpa kamu"],["وَٱللَّهُ","Dan Allah"],["خَبِيرٌۢ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"]]],"447":["(Kemudian Allah menurunkan kepada kamu setelah kesedihan itu keamanan berupa kantuk) menjadi badal (yang meliputi) ada yang membaca dengan ya dan ada pula dengan ta (segolongan dari kamu) yakni orang-orang beriman; mereka tertidur lelap di balik tameng sehingga pedang-pedang pun tergelincir dan jatuh ke sisi mereka (sedangkan segolongan lagi telah dicemaskan oleh diri mereka sendiri) maksudnya mereka merasa cemas memikirkan nasib mereka hingga mereka tak ada kemauan selain menyelamatkan diri tanpa mempedulikan Nabi saw. dan para sahabatnya. Mereka tidak dapat tidur dan mereka adalah orang-orang munafik. (Mereka menyangka yang tidak benar terhadap Allah) maksudnya seperti sangkaan (jahiliah) yang berkeyakinan bahwa Nabi itu benar-benar telah terbunuh atau kalau tidak, maka ia takkan dapat dikalahkan. (Kata mereka, \"Apakah) maksudnya tak ada (bagi kita terhadap urusan ini) maksudnya mengenai kemenangan yang telah Kami janjikan itu (dari) merupakan tambahan (sesuatu.\"). (Katakanlah) kepada mereka (\"Sesungguhnya urusan ini seluruhnya) manshub sebagai taukid dapat pula marfu` sebagai mubtada sedangkan khabarnya ialah: (bagi Allah.\") maksudnya ketentuan berada di tangan-Nya. Ia berbuat apa yang dikehendaki-Nya (Mereka menyembunyikan dalam hati mereka apa yang tidak mereka terangkan kepadamu, maka mereka mengatakan) ini menjadi keterangan bagi 'apa' yang sebelumnya (\"Sekiranya bagi kami terhadap urusan ini ada sesuatu tidaklah kami terbunuh di sini) maksudnya jika kita mempunyai campur tangan dalam urusan ini kita dapat saja tidak keluar sehingga tidak terbunuh tetapi apa daya kita karena kita ini dipaksa keluar.\" (Katakanlah) kepada mereka (\"Sekiranya kamu berada di rumahmu) sedangkan di antaramu ada orang yang telah ditetapkan Allah akan menemui ajalnya (niscaya orang-orang yang telah ditakdirkan akan terbunuh itu akan keluar juga ke tempat pembunuhan mereka.\") sehingga mereka akan mati terbunuh, dan tidak akan tertolong oleh ikhtiar atau usaha mereka itu karena kada Allah tetap berlaku tanpa sesuatu pun dapat menolaknya. (Dan) hal itu dilakukan-Nya (agar Allah menguji apa yang terdapat dalam dadamu) dalam hatimu berupa keikhlasan atau kemunafikan (dan untuk membersihkan isi hatimu. Dan Allah Maha Mengetahui akan sisi hati) semua itu tak ada yang tersembunyi bagi-Nya tetapi maksud-Nya agar dengan ujian itu tampaklah pula bagi manusia keikhlasan dan kemunafikan di antara kalian.",[["ثُمَّ","Kemudian"],["أَنزَلَ","Dia menurunkan"],["عَلَيْكُم","ke atas kamu"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["ٱلْغَمِّ","kesusahan itu"],["أَمَنَةًۭ","keselamatan"],["نُّعَاسًۭا","mengantuk"],["يَغْشَىٰ","mengatasi"],["طَآئِفَةًۭ","satu kumpulan"],["مِّنكُمْ ۖ","daripada kamu"],["وَطَآئِفَةٌۭ","manakala kumpulan"],["قَدْ","sudah tentu"],["أَهَمَّتْهُمْ","bimbang [mereka]"],["أَنفُسُهُمْ","(tentang) diri mereka sendiri"],["يَظُنُّونَ","berfikir"],["بِٱللَّهِ","tentang Allah"],["غَيْرَ","selain daripada"],["ٱلْحَقِّ","kebenaran"],["ظَنَّ","(yang) pemikiran"],["ٱلْجَـٰهِلِيَّةِ ۖ","(dari) kejahilan"],["يَقُولُونَ","berkata"],["هَل","Adakah (ada)"],["لَّنَا","bagi kami"],["مِنَ","daripada"],["ٱلْأَمْرِ","perkara itu"],["مِن","sebarang"],["شَىْءٍۢ ۗ","perkara"],["قُلْ","Katakanlah"],["إِنَّ","Sesungguhnya"],["ٱلْأَمْرَ","perkara itu"],["كُلَّهُۥ","semua (dari) itu"],["لِلَّهِ ۗ","(adalah) untuk Allah"],["يُخْفُونَ","Mereka bersembunyi"],["فِىٓ","dalam"],["أَنفُسِهِم","diri mereka"],["مَّا","apa"],["لَا","tidak"],["يُبْدُونَ","mereka mendedahkan"],["لَكَ ۖ","kepada kamu"],["يَقُولُونَ","Mereka berkata"],["لَوْ","Jika"],["كَانَ","adalah"],["لَنَا","bagi kami"],["مِنَ","daripada"],["ٱلْأَمْرِ","perkara itu"],["شَىْءٌۭ","sesuatu"],["مَّا","tidak"],["قُتِلْنَا","kita akan dibunuh"],["هَـٰهُنَا ۗ","di sini"],["قُل","Katakanlah"],["لَّوْ","Jika"],["كُنتُمْ","kamu dahulu"],["فِى","dalam"],["بُيُوتِكُمْ","rumah-rumah kamu"],["لَبَرَزَ","nescaya (akan) keluar"],["ٱلَّذِينَ","mereka yang"],["كُتِبَ","telah diputuskan"],["عَلَيْهِمُ","ke atas mereka"],["ٱلْقَتْلُ","[the] kematian"],["إِلَىٰ","ke arah"],["مَضَاجِعِهِمْ ۖ","tempat kematian mereka"],["وَلِيَبْتَلِىَ","Dan itu mungkin menguji"],["ٱللَّهُ","Allah"],["مَا","apa"],["فِى","(berada) dalam"],["صُدُورِكُمْ","buah dada kamu"],["وَلِيُمَحِّصَ","dan supaya Dia membersihkan"],["مَا","apa"],["فِى","(berada) dalam"],["قُلُوبِكُمْ ۗ","hati kamu"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌۢ","(adalah) Maha Mengetahui"],["بِذَاتِ","tentang apa"],["ٱلصُّدُورِ","(ada dalam) buah dada"]]],"448":["(Sesungguhnya orang-orang yang berpaling di antara kamu) dari peperangan (di saat bertemunya dua pasukan) yaitu pasukan kaum Muslimin dan pasukan orang-orang kafir di Uhud. Yang dituju ialah pasukan Muslimin itu kecuali dua belas orang (sesungguhnya mereka digelincirkan oleh setan) dengan waswas atau tipu dayanya (disebabkan sebagian apa yang mereka perbuat) berupa dosa yaitu melanggar perintah Nabi saw. (dan sesungguhnya Allah telah memberi maaf kepada mereka. Sesungguhnya Allah Maha Pengampun) terhadap orang-orang mukmin (lagi Maha Penyantun) sehingga menangguhkan siksa dari orang-orang durhaka.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["تَوَلَّوْا۟","berpatah balik"],["مِنكُمْ","antara kamu"],["يَوْمَ","(pada) hari"],["ٱلْتَقَى","bertemu"],["ٱلْجَمْعَانِ","dua tuan rumah"],["إِنَّمَا","sahaja"],["ٱسْتَزَلَّهُمُ","membuat mereka tergelincir"],["ٱلشَّيْطَـٰنُ","syaitan"],["بِبَعْضِ","bagi sesetengah orang"],["مَا","apa"],["كَسَبُوا۟ ۖ","mereka (telah) memperolehnya"],["وَلَقَدْ","Dan pastinya"],["عَفَا","memaafkan"],["ٱللَّهُ","Allah"],["عَنْهُمْ ۗ","[pada] mereka"],["إِنَّ","sesungguhnya"],["ٱللَّهَ","Allah"],["غَفُورٌ","Maha Pengampun"],["حَلِيمٌۭ","Maha Penyabar"]]],"449":["(Hai orang-orang yang beriman! Janganlah kamu seperti orang-orang kafir) maksudnya orang-orang munafik (yang mengatakan kepada kawan-kawan mereka) mengenai keadaan mereka (apabila mereka bepergian di muka bumi) lalu mati (atau mereka berperang) lalu terbunuh (\"Sekiranya mereka berada bersama kita tidaklah mereka akan mati dan tidak pula terbunuh.\") maksudnya janganlah kamu berkata seperti demikian. (Allah menjadikan demikian itu) sebagai akibat dari ucapan mereka tadi (suatu penyesalan dalam hati mereka. Allah menghidupkan dan mematikan) hingga tinggalnya seseorang di rumahnya sama sekali tidak menghalangi kematiannya (dan terhadap apa yang kamu kerjakan) dengan memakai ta atau ya (Maha Melihat) maka kelak Dia akan membalaskannya kepada kalian.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Jangan"],["تَكُونُوا۟","jadilah"],["كَٱلَّذِينَ","seperti mereka yang"],["كَفَرُوا۟","kufur"],["وَقَالُوا۟","dan mereka berkata"],["لِإِخْوَٰنِهِمْ","tentang saudara mereka"],["إِذَا","apabila"],["ضَرَبُوا۟","mereka mengembara"],["فِى","dalam"],["ٱلْأَرْضِ","bumi"],["أَوْ","atau"],["كَانُوا۟","mereka adalah"],["غُزًّۭى","bergaduh"],["لَّوْ","Jika"],["كَانُوا۟","mereka telah"],["عِندَنَا","dengan kami"],["مَا","tidak"],["مَاتُوا۟","mereka (akan) mati"],["وَمَا","dan bukan"],["قُتِلُوا۟","mereka (akan) dibunuh"],["لِيَجْعَلَ","Jadi membuatkan"],["ٱللَّهُ","Allah"],["ذَٰلِكَ","bahawa"],["حَسْرَةًۭ","satu penyesalan"],["فِى","dalam"],["قُلُوبِهِمْ ۗ","hati mereka"],["وَٱللَّهُ","Dan Allah"],["يُحْىِۦ","memberi kehidupan"],["وَيُمِيتُ ۗ","dan menyebabkan kematian"],["وَٱللَّهُ","dan Allah"],["بِمَا","tentang apa"],["تَعْمَلُونَ","kamu lakukan"],["بَصِيرٌۭ","(ialah) Maha Melihat"]]],"450":["(Sungguh sekiranya) lam menunjukkan sumpah (kamu dibunuh di jalan Allah) maksudnya dalam berjihad (atau meninggal) dibaca muttum atau mittum berasal dari maata-yamuutu; artinya didatangi oleh kematian di dalam berjihad (maka ampunan) yang kamu peroleh (dari Allah) terhadap dosa-dosamu (dan rahmat) daripada-Nya bagi kamu atas demikian itu. Lam serta kalimat yang dimasukinya menjadi jawab qasam di samping menjadi mubtada yang khabarnya ialah: (benar-benar lebih baik dari apa yang mereka kumpulkan) dari harta dunia; memakai ya atau ta.",[["وَلَئِن","Dan jika"],["قُتِلْتُمْ","kamu terbunuh"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["أَوْ","atau"],["مُتُّمْ","mati[d]"],["لَمَغْفِرَةٌۭ","pasti keampunan"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَرَحْمَةٌ","dan Rahmat"],["خَيْرٌۭ","(adalah) lebih baik"],["مِّمَّا","daripada apa"],["يَجْمَعُونَ","mereka terkumpul"]]],"451":["(Sungguh sekiranya) lam berarti sumpah (kamu meninggal) dibaca muttum atau mittum (atau terbunuh) dalam peperangan atau lainnya (maka hanya kepada Allahlah) dan bukan kepada selain-Nya (kamu akan dihimpun) di akhirat di mana amal perbuatanmu akan dibalas-Nya.",[["وَلَئِن","Dan jika"],["مُّتُّمْ","kamu mati"],["أَوْ","atau"],["قُتِلْتُمْ","dibunuh"],["لَإِلَى","pasti ke"],["ٱللَّهِ","Allah"],["تُحْشَرُونَ","kamu akan dikumpulkan"]]],"452":["(Maka berkat) ma merupakan tambahan (rahmat dari Allah kamu menjadi lemah lembut) hai Muhammad (kepada mereka) sehingga kamu hadapi pelanggaran mereka terhadap perintahmu itu dengan sikap lunak (dan sekiranya kamu bersikap keras) artinya akhlakmu jelek tidak terpuji (dan berhati kasar) hingga kamu mengambil tindakan keras terhadap mereka (tentulah mereka akan menjauhkan diri dari sekelilingmu, maka maafkanlah mereka) atas kesalahan yang mereka perbuat (dan mintakanlah ampunan bagi mereka) atas kesalahan-kesalahan itu hingga Kuampuni (serta berundinglah dengan mereka) artinya mintalah pendapat atau buah pikiran mereka (mengenai urusan itu) yakni urusan peperangan dan lain-lain demi mengambil hati mereka, dan agar umat meniru sunah dan jejak langkahmu, maka Rasulullah saw. banyak bermusyawarah dengan mereka. (Kemudian apabila kamu telah berketetapan hati) untuk melaksanakan apa yang kamu kehendaki setelah bermusyawarah itu (maka bertawakallah kepada Allah) artinya percayalah kepada-Nya. (Sesungguhnya Allah menyukai orang-orang yang bertawakal) kepada-Nya.",[["فَبِمَا","Jadi kerana"],["رَحْمَةٍۢ","(dari) Rahmat"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["لِنتَ","kamu layan dengan lembut"],["لَهُمْ ۖ","bersama mereka"],["وَلَوْ","Dan jika"],["كُنتَ","kamu telah"],["فَظًّا","kurang ajar"],["غَلِيظَ","(dan) keras"],["ٱلْقَلْبِ","(di) hati"],["لَٱنفَضُّوا۟","nescaya mereka (akan) bercerai-berai"],["مِنْ","daripada"],["حَوْلِكَ ۖ","sekeliling kamu"],["فَٱعْفُ","Kemudian maafkan"],["عَنْهُمْ","[dari] mereka"],["وَٱسْتَغْفِرْ","dan memohon ampun"],["لَهُمْ","bagi mereka"],["وَشَاوِرْهُمْ","dan berunding dengan mereka"],["فِى","dalam"],["ٱلْأَمْرِ ۖ","perkara itu"],["فَإِذَا","Kemudian apabila"],["عَزَمْتَ","kamu telah membuat keputusan"],["فَتَوَكَّلْ","kemudian meletakkan kepercayaan"],["عَلَى","pada"],["ٱللَّهِ ۚ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["يُحِبُّ","suka"],["ٱلْمُتَوَكِّلِينَ","orang yang bertawakkal (kepada-Nya)"]]],"453":["(Jika Allah menolong kamu) terhadap musuhmu seperti di perang Badar (maka tak ada orang yang akan mengalahkan kamu, sebaliknya jika Dia membiarkan kamu) tanpa memberikan pertolongan seperti waktu perang Uhud (maka siapakah lagi yang dapat menolongmu setelah itu) artinya setelah kekalahan itu, maksudnya tak ada lagi. (Hanya kepada Allahlah) bukan kepada lain-Nya (orang-orang beriman itu harus bertawakal). Ayat berikut ini diturunkan ketika hilangnya sehelai permadani merah di waktu perang Uhud lalu sebagian orang mengatakan barangkali Nabilah yang mengambilnya:",[["إِن","Jika"],["يَنصُرْكُمُ","membantu kamu"],["ٱللَّهُ","Allah"],["فَلَا","maka tidak"],["غَالِبَ","(boleh) mengatasi"],["لَكُمْ ۖ","[untuk] kamu"],["وَإِن","dan jika"],["يَخْذُلْكُمْ","Dia tinggalkan kamu"],["فَمَن","kemudian siapa"],["ذَا","(adalah)"],["ٱلَّذِى","orang yang"],["يَنصُرُكُم","boleh membantu kamu"],["مِّنۢ","daripada"],["بَعْدِهِۦ ۗ","selepas Dia"],["وَعَلَى","Dan seterusnya"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","hendaklah meletakkan amanah (mereka)."],["ٱلْمُؤْمِنُونَ","orang yang beriman"]]],"454":["(Tidaklah mungkin) atau patut (bagi seorang Nabi itu akan berkhianat dalam urusan harta rampasan perang) maka janganlah kamu menyangka hal yang demikian itu! Menurut satu qiraat dibaca 'yughalla' yang berarti dinisbatkan kepada pengkhianatan. (Barang siapa yang berkhianat dalam urusan harta rampasan perang itu, maka ia akan datang pada hari kiamat membawa barang yang dikhianatkannya itu) dengan memikulnya di atas pundaknya (kemudian setiap diri akan diberi balasan) baik yang berkhianat maupun yang tidak berkhianat (atas apa yang dikerjakannya sedangkan mereka tidaklah dianiaya) sedikit pun juga.",[["وَمَا","Dan tidak"],["كَانَ","ialah"],["لِنَبِىٍّ","untuk seorang Nabi"],["أَن","bahawa"],["يَغُلَّ ۚ","dia menipu"],["وَمَن","Dan sesiapa"],["يَغْلُلْ","menipu"],["يَأْتِ","akan membawa"],["بِمَا","apa"],["غَلَّ","dia telah menipu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۚ","(dari) Kebangkitan"],["ثُمَّ","Kemudian"],["تُوَفَّىٰ","dibayar balik sepenuhnya"],["كُلُّ","setiap"],["نَفْسٍۢ","jiwa"],["مَّا","apa"],["كَسَبَتْ","ia diperolehi"],["وَهُمْ","dan mereka"],["لَا","(akan) tidak"],["يُظْلَمُونَ","dizalimi"]]],"455":["(Apakah orang yang mengikuti keridaan Allah) lalu ia taat dan tak berkhianat dalam soal rampasan perang (akan sama dengan orang yang kembali dengan kemurkaan dari Allah) karena perbuatan maksiat dan kecurangannya? (Tempatnya ialah neraka Jahanam dan itulah seburuk-buruk tempat kembali) jawabannya tentu saja tidak sama.",[["أَفَمَنِ","Begitu juga (yang) yang"],["ٱتَّبَعَ","mengejar"],["رِضْوَٰنَ","(the) kesenangan"],["ٱللَّهِ","(milik) Allah"],["كَمَنۢ","seperti (yang) siapa"],["بَآءَ","cabutan"],["بِسَخَطٍۢ","pada (dirinya) murka"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَمَأْوَىٰهُ","dan tempat tinggalnya"],["جَهَنَّمُ ۚ","(adalah) neraka"],["وَبِئْسَ","dan celaka"],["ٱلْمَصِيرُ","(adalah) destinasi"]]],"456":["(Mereka itu bertingkat-tingkat) maksudnya mempunyai tingkat masing-masing (di sisi Allah) artinya mempunyai kedudukan yang berbeda-beda. Maka orang yang mengikuti keridaan-Nya akan beroleh pahala atau surga sedangkan yang membawa amarah murka-Nya akan mendapat siksa atau neraka (dan Allah Maha Melihat apa yang mereka kerjakan) hingga akan mendapat balasan daripada-Nya.",[["هُمْ","mereka"],["دَرَجَـٰتٌ","(ada dalam pelbagai) darjah"],["عِندَ","dekat"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","dan Allah"],["بَصِيرٌۢ","(ialah) Maha Melihat"],["بِمَا","tentang apa"],["يَعْمَلُونَ","mereka lakukan"]]],"457":["(Sesungguhnya Allah telah memberi karunia kepada orang-orang beriman ketika Dia mengirim kepada mereka seorang rasul dari kalangan mereka sendiri) maksudnya seorang Arab seperti mereka untuk mengawasi dan memberi pengertian, jadi bukan dari kalangan malaikat dan tidak pula dari bangsa asing (yang membacakan kepada mereka ayat-ayat-Nya) yakni Alquran (dan menyucikan mereka) membersihkan mereka dari dosa (serta mengajarkan kepada mereka Alkitab) yakni Alquran (dan hikmah) yakni sunah (dan sesungguhnya mereka) ditakhfifkan dari wainnahum (adalah sebelumnya) yakni sebelum kebangkitannya (benar-benar dalam kesesatan yang nyata) atau jelas.",[["لَقَدْ","Sungguh"],["مَنَّ","dikurniakan Nikmat"],["ٱللَّهُ","Allah"],["عَلَى","ke atas"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["إِذْ","seperti"],["بَعَثَ","Dia mengangkat"],["فِيهِمْ","antara mereka"],["رَسُولًۭا","seorang Rasul"],["مِّنْ","daripada"],["أَنفُسِهِمْ","diri mereka"],["يَتْلُوا۟","mengaji"],["عَلَيْهِمْ","kepada mereka"],["ءَايَـٰتِهِۦ","Ayat-ayatNya"],["وَيُزَكِّيهِمْ","dan menyucikan mereka"],["وَيُعَلِّمُهُمُ","dan mengajar mereka"],["ٱلْكِتَـٰبَ","Kitab"],["وَٱلْحِكْمَةَ","dan hikmahnya"],["وَإِن","walaupun"],["كَانُوا۟","mereka adalah"],["مِن","daripada"],["قَبْلُ","sebelum (itu)"],["لَفِى","sudah tentu dalam"],["ضَلَـٰلٍۢ","(kesalahan)."],["مُّبِينٍ","yang nyata"]]],"458":["(Mengapa ketika kamu ditimpa musibah) yaitu di Uhud dengan gugurnya 70 orang di antara kamu (padahal kamu telah menimpakan kekalahan dua kali lipat kepada musuh-musuhmu) yakni di Badar dengan membunuh 70 orang dan menawan 70 di antara mereka (kamu berkata) dengan keheran-heranan (\"Dari mana datangnya ini?\") maksudnya kekalahan ini padahal kita adalah orang-orang muslim dan Rasulullah berada bersama kita. Kalimat terakhir merupakan pertanyaan yang berarti sanggahan. (Katakanlah) kepada mereka (\"Itu dari dirimu sendiri) karena kamu meninggalkan markas sehingga mengalami kegagalan. (Sesungguhnya Allah Maha Kuasa atas segala sesuatu.\") dan daripada-Nyalah datang kemenangan atau terhalangnya kemenangan itu; dan kamu mendapat balasan daripada-Nya disebabkan pelanggaran terhadap perintah Rasul-Nya.",[["أَوَلَمَّآ","Atau apabila"],["أَصَـٰبَتْكُم","memukul kamu"],["مُّصِيبَةٌۭ","bencana"],["قَدْ","pasti"],["أَصَبْتُم","kamu (telah) memukul (mereka)"],["مِّثْلَيْهَا","dua kali daripadanya"],["قُلْتُمْ","kamu kata"],["أَنَّىٰ","Dari mana"],["هَـٰذَا ۖ","(adalah) ini"],["قُلْ","Katakanlah"],["هُوَ","Ia"],["مِنْ","(adalah)"],["عِندِ","daripada"],["أَنفُسِكُمْ ۗ","kamu sendiri"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌۭ","Maha Berkuasa"]]],"459":["(Apa yang menimpa kamu di hari bertemunya dua pasukan) yakni di Uhud (maka adalah dengan izin Allah) atau kehendak-Nya (dan supaya diketahui-Nya) secara nyata (orang-orang yang beriman) yang benar-benar beriman.",[["وَمَآ","Dan apa"],["أَصَـٰبَكُمْ","memukul kamu"],["يَوْمَ","(pada) hari"],["ٱلْتَقَى","(apabila) bertemu"],["ٱلْجَمْعَانِ","dua tuan rumah"],["فَبِإِذْنِ","(adalah) dengan izin"],["ٱللَّهِ","(milik) Allah"],["وَلِيَعْلَمَ","dan supaya Dia menerangkan"],["ٱلْمُؤْمِنِينَ","orang yang beriman"]]],"460":["(Dan supaya diketahui-Nya orang-orang yang munafik dan) orang-orang yang (dikatakan kepada mereka) ketika mereka berpaling dari peperangan, yaitu Abdullah bin Ubai dan anak buahnya (\"Marilah kita berperang di jalan Allah) dengan musuh-musuh-Nya (atau usirlah mereka\") dari kami dengan memperbanyak anggotamu jika kamu tidak hendak berperang! (Jawab mereka, \"Sekiranya kami tahu) maksudnya pandai (berperang, tentulah kami akan mengikuti kamu\") firman Allah mendustakan mereka, (\"Pada hari itu mereka lebih dekat kepada kekafiran daripada keimanan) dengan sikap mereka yang terang-terangan mengkhianati kaum Muslimin sedangkan sebelumnya mereka pada lahirnya lebih dekat kepada keimanan. (Mereka mengatakan dengan mulut mereka apa yang tidak terdapat di dalam hati mereka) karena seandainya mereka pandai berperang, mereka juga tidak akan mengikutimu! (Dan Allah lebih mengetahui apa-apa yang mereka sembunyikan\") berupa kemunafikan.",[["وَلِيَعْلَمَ","Dan supaya Dia menerangkan"],["ٱلَّذِينَ","orang yang"],["نَافَقُوا۟ ۚ","(adalah) orang-orang munafik"],["وَقِيلَ","Dan ia dikatakan"],["لَهُمْ","kepada mereka"],["تَعَالَوْا۟","Datang"],["قَـٰتِلُوا۟","bergaduh"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["أَوِ","atau"],["ٱدْفَعُوا۟ ۖ","mempertahankan"],["قَالُوا۟","Mereka berkata"],["لَوْ","Jika"],["نَعْلَمُ","kami tahu"],["قِتَالًۭا","bergaduh"],["لَّٱتَّبَعْنَـٰكُمْ ۗ","sesungguhnya kami (akan) mengikut kamu"],["هُمْ","mereka"],["لِلْكُفْرِ","kepada ketidakpercayaan"],["يَوْمَئِذٍ","hari itu"],["أَقْرَبُ","(berada) lebih dekat"],["مِنْهُمْ","daripada [mereka]"],["لِلْإِيمَـٰنِ ۚ","kepada iman"],["يَقُولُونَ","berkata"],["بِأَفْوَٰهِهِم","dengan mulut mereka"],["مَّا","apa"],["لَيْسَ","tidak"],["فِى","dalam"],["قُلُوبِهِمْ ۗ","hati mereka"],["وَٱللَّهُ","Dan Allah"],["أَعْلَمُ","(adalah) Maha Mengetahui"],["بِمَا","tentang apa"],["يَكْتُمُونَ","mereka sembunyikan"]]],"461":["(Yakni orang-orang) menjadi badal atau sifat bagi 'orang-orang' yang sebelumnya (yang mengatakan kepada saudara-saudara mereka) seagama (dan) sesungguhnya (mereka tidak ikut) berperang (\"Sekiranya mereka mengikuti kita) maksudnya orang-orang yang gugur di perang Uhud itu (tentulah mereka tidak akan terbunuh!\" Katakanlah) kepada mereka (\"Hindarkanlah) tolaklah (kematian dari dirimu jika kamu orang-orang yang benar.\") bahwa tidak ikut berperang itu dapat menghindarkan kematian. Ayat berikut turun mengenai syuhada atau orang-orang yang mati syahid",[["ٱلَّذِينَ","Orang yang"],["قَالُوا۟","berkata"],["لِإِخْوَٰنِهِمْ","tentang saudara mereka"],["وَقَعَدُوا۟","semasa mereka duduk"],["لَوْ","Jika"],["أَطَاعُونَا","mereka (telah) taat kepada kami"],["مَا","tidak"],["قُتِلُوا۟ ۗ","mereka akan dibunuh"],["قُلْ","Katakanlah"],["فَٱدْرَءُوا۟","Kemudian mengelak"],["عَنْ","daripada"],["أَنفُسِكُمُ","kamu sendiri"],["ٱلْمَوْتَ","[the] kematian"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"462":["(Janganlah kamu kira bahwa orang-orang yang gugur) dengan takhfif atau pakai tasydid (di jalan Allah) maksudnya demi agama-Nya (mati, tetapi) mereka itu (hidup di sisi Tuhan mereka). Roh-roh mereka berada dalam kantong burung-burung hijau yang beterbangan dalam surga ke mana saja mereka kehendaki sebagaimana tersebut dalam sebuah hadis (dengan mendapat rezeki) yaitu dengan memakan buah-buahan surga.",[["وَلَا","Dan jangan"],["تَحْسَبَنَّ","fikir"],["ٱلَّذِينَ","orang yang"],["قُتِلُوا۟","dibunuh"],["فِى","dalam"],["سَبِيلِ","jalan"],["ٱللَّهِ","(milik) Allah"],["أَمْوَٰتًۢا ۚ","(sebagai) mati"],["بَلْ","Bahkan"],["أَحْيَآءٌ","Mereka masih hidup"],["عِندَ","dekat"],["رَبِّهِمْ","Tuhan mereka"],["يُرْزَقُونَ","mereka diberi rezeki"]]],"463":["(Mereka riang gembira) menjadi hal dari kata ganti yang terdapat pada yurzaquuna (dengan karunia yang diberikan Allah kepada mereka, dan) mereka (bersenang hati terhadap orang-orang yang masih belum menyusul di belakang mereka) yakni dari saudara-saudara mereka orang-orang beriman dan yang menjadi badal bagi 'alladziina' (bahwa) artinya disebabkan karena (tak ada kekhawatiran terhadap mereka, dan tidak pula mereka akan berdukacita) di akhirat kelak. Maksudnya mereka bersenang hati pula karena teman-teman mereka yang akan menyusul di belakang tak perlu dikhawatirkan nasib dan keamanan mereka.",[["فَرِحِينَ","Bergembira"],["بِمَآ","pada apa"],["ءَاتَىٰهُمُ","dianugerahkan kepada mereka"],["ٱللَّهُ","Allah"],["مِن","daripada"],["فَضْلِهِۦ","Bounty-Nya"],["وَيَسْتَبْشِرُونَ","dan mereka mendapat khabar gembira"],["بِٱلَّذِينَ","tentang mereka yang"],["لَمْ","(mempunyai) tidak"],["يَلْحَقُوا۟","belum menyertai"],["بِهِم","[dengan] mereka"],["مِّنْ","[dari]"],["خَلْفِهِمْ","(tetapi) ditinggalkan"],["أَلَّا","bahawa (akan ada) tidak"],["خَوْفٌ","bertakwa"],["عَلَيْهِمْ","ke atas mereka"],["وَلَا","dan bukan"],["هُمْ","mereka"],["يَحْزَنُونَ","akan bersedih"]]],"464":["(Mereka bersenang hati dengan nikmat) atau pahala (dari Allah dan karunia) atau tambahan atasnya (dan bahwa) dibaca anna sebagai ma'thuf kepada 'ni'mah' atau 'inna' sebagai isti'naf atau permulaan kalimat (Allah tidak menyia-nyiakan pahala orang-orang yang beriman) tetapi sebaliknya akan memberi mereka ganjaran.",[["۞ يَسْتَبْشِرُونَ","Mereka menerima khabar gembira"],["بِنِعْمَةٍۢ","nikmat"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَفَضْلٍۢ","dan Bounty"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["لَا","tidak"],["يُضِيعُ","biarkan pergi membazir"],["أَجْرَ","(i) ganjaran"],["ٱلْمُؤْمِنِينَ","(dari) orang-orang yang beriman"]]],"465":["(Orang-orang) menjadi subjek atau mubtada (yang memenuhi panggilan Allah dan rasul-Nya) agar keluar untuk berperang, yakni sewaktu Abu Sufyan dan kawan-kawannya hendak mengulangi peperangan dan berjanji dengan Nabi saw. serta para sahabat akan bertemu kembali di pasar Badar setahun setelah perang Uhud (setelah mereka mendapat luka) yakni di Uhud, sedangkan yang menjadi predikat atau khabar mubtadanya ialah: (bagi orang-orang yang berbuat kebaikan di antara mereka) dengan menaati-Nya (dan menjaga diri) dari menyalahi-Nya (tersedia pahala besar) yaitu surga.",[["ٱلَّذِينَ","Orang yang"],["ٱسْتَجَابُوا۟","menjawab"],["لِلَّهِ","kepada Allah"],["وَٱلرَّسُولِ","dan Rasul"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["مَآ","apa"],["أَصَابَهُمُ","menimpa mereka"],["ٱلْقَرْحُ ۚ","kecederaan itu"],["لِلَّذِينَ","bagi mereka yang"],["أَحْسَنُوا۟","berbuat baik"],["مِنْهُمْ","antara mereka"],["وَٱتَّقَوْا۟","dan takut kepada Allah"],["أَجْرٌ","(adalah) ganjaran"],["عَظِيمٌ","yang besar"]]],"466":["(Yakni orang-orang) badal atau sifat dari 'alladziina' yang sebelumnya (kepada mereka ada yang mengatakan) yakni Na'im bin Masud Al-Asyjai (\"Sesungguhnya manusia) yaitu Abu Sofyan dan kawan-kawannya (telah menghimpun pasukan untuk menyerang kamu) atau untuk membasmimu (maka takutlah kepada mereka\") dan jangan hadapi mereka. (Maka ucapan itu menambah keimanan mereka) bertambah kepercayaan dan keyakinan mereka terhadap Allah swt. (dan jawaban mereka, \"Cukuplah bagi kami Allah) sebagai pembela terhadap mereka (dan Dialah sebaik-baik pelindung\") tempat menyerahkan segala urusan. Nabi saw. bersama kaum Muslimin pergi ke pasar Badar tetapi tidak menemui Abu Sofyan dan kawan-kawannya, Allah telah meniupkan rasa cemas dan ketakutan ke dalam hati mereka sehingga mereka tidak muncul. Sebaliknya di kalangan kaum Muslimin dan penduduk berlangsung jual beli sehingga mereka beroleh laba dan keuntungan. Firman Allah swt. selanjutnya.",[["ٱلَّذِينَ","Orang yang"],["قَالَ","berkata"],["لَهُمُ","kepada mereka"],["ٱلنَّاسُ","[rakyat]"],["إِنَّ","Sesungguhnya"],["ٱلنَّاسَ","manusia"],["قَدْ","(mempunyai) sudah pasti"],["جَمَعُوا۟","berkumpul"],["لَكُمْ","terhadap kamu"],["فَٱخْشَوْهُمْ","maka takutilah mereka"],["فَزَادَهُمْ","Tetapi ia meningkatkan mereka"],["إِيمَـٰنًۭا","(dalam) iman"],["وَقَالُوا۟","dan mereka berkata"],["حَسْبُنَا","Cukup untuk kita"],["ٱللَّهُ","(ialah) Allah"],["وَنِعْمَ","dan (Dialah) yang terbaik"],["ٱلْوَكِيلُ","[the] Pelupus urusan"]]],"467":["(Maka kembalilah mereka) dari Badar (dengan nikmat dan karunia dari Allah) yakni keselamatan dan keuntungan (tanpa mendapat bencana) baik luka atau kematian (dan mereka mengikuti keridaan Allah) yakni dengan menaati-Nya dan rasul-Nya supaya keluar berperang. (Dan Allah mempunyai karunia yang besar) terhadap ahli taat dan ibadah.",[["فَٱنقَلَبُوا۟","Jadi mereka kembali"],["بِنِعْمَةٍۢ","dengan nikmat"],["مِّنَ","daripada"],["ٱللَّهِ","Allah"],["وَفَضْلٍۢ","dan Bounty"],["لَّمْ","tidak"],["يَمْسَسْهُمْ","menyentuh mereka"],["سُوٓءٌۭ","sebarang kemudaratan"],["وَٱتَّبَعُوا۟","Dan mereka mengikut"],["رِضْوَٰنَ","(the) kesenangan"],["ٱللَّهِ ۗ","(milik) Allah"],["وَٱللَّهُ","dan Allah"],["ذُو","(ialah) Pemilik"],["فَضْلٍ","(dari) Bounty"],["عَظِيمٍ","yang besar"]]],"468":["(Sesungguhnya mereka itu) yakni yang mengatakan bahwa manusia telah menghimpun pasukan dan seterusnya tadi (hanyalah setan yang menakut-nakuti) kamu dengan (kawan-kawannya) yakni orang-orang kafir (maka janganlah kamu takut kepada mereka hanya takutlah kepada-Ku) jika meninggalkan perintah-Ku (sekiranya kamu benar-benar beriman.)",[["إِنَّمَا","(Ia) sahaja"],["ذَٰلِكُمُ","bahawa"],["ٱلشَّيْطَـٰنُ","syaitan"],["يُخَوِّفُ","menakutkan (kamu)"],["أَوْلِيَآءَهُۥ","(dari) sekutunya"],["فَلَا","Jadi (jangan)"],["تَخَافُوهُمْ","takutkan mereka"],["وَخَافُونِ","tetapi takutlah kepada-Ku"],["إِن","jika"],["كُنتُم","kamu"],["مُّؤْمِنِينَ","orang yang beriman"]]],"469":["(Janganlah kamu menjadi sedih oleh) ada yang membaca 'yuhzinka' dan ada pula 'yahzunka', berasal dari kata 'ahzanahu' (orang-orang yang cepat jatuh dalam kekafiran) yakni orang-orang yang membela kekafiran itu seperti warga Mekah dan orang-orang munafik, maksudnya jangan kamu pedulikan hal itu. (Sesungguhnya mereka tak sekali-kali dapat memberi mudarat kepada Allah sedikit pun) dengan perbuatan mereka itu, dan mereka hanya membawa kerusakan bagi diri mereka sendiri (Allah menghendaki agar tidak memberi mereka sesuatu di akhirat) maksudnya surga, oleh sebab itu mereka dibiarkan-Nya (dan bagi mereka siksa yang besar) dalam neraka.",[["وَلَا","Dan (jangan)"],["يَحْزُنكَ","menyedihkan kamu"],["ٱلَّذِينَ","orang yang"],["يُسَـٰرِعُونَ","cepatkan"],["فِى","dalam (ke)"],["ٱلْكُفْرِ ۚ","[yang] tidak beriman"],["إِنَّهُمْ","Sesungguhnya mereka"],["لَن","tidak pernah"],["يَضُرُّوا۟","akan memudaratkan"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا ۗ","(dalam) apa-apa"],["يُرِيدُ","berniat"],["ٱللَّهُ","Allah"],["أَلَّا","itu tidak"],["يَجْعَلَ","Dia akan menetapkan"],["لَهُمْ","bagi mereka"],["حَظًّۭا","mana-mana bahagian"],["فِى","dalam"],["ٱلْـَٔاخِرَةِ ۖ","akhirat"],["وَلَهُمْ","Dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["عَظِيمٌ","yang besar"]]],"470":["(Sesungguhnya orang-orang yang menukar keimanan dengan kekafiran) artinya mengambil kekafiran sebagai ganti dari keimanan (tidaklah memberi mudarat kepada Allah) dengan kekafiran mereka itu (sedikit pun dan bagi mereka siksa yang pedih) atau menyakitkan.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["ٱشْتَرَوُا۟","(telah) membeli"],["ٱلْكُفْرَ","[yang] tidak beriman"],["بِٱلْإِيمَـٰنِ","dengan iman"],["لَن","tidak pernah"],["يَضُرُّوا۟","adakah mereka akan membahayakan"],["ٱللَّهَ","Allah"],["شَيْـًۭٔا","(dalam) apa-apa"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(ialah) azab"],["أَلِيمٌۭ","yang pedih"]]],"471":["(Janganlah sekali-kali menyangka) ada yang memakai 'ya' dan ada pula 'ta' (orang-orang kafir itu bahwa Kami menangguhkan) artinya penangguhan Kami (bagi mereka) yakni dengan memanjangkan umur dan menangguhkan hukuman (lebih baik bagi diri mereka). 'Anna' bersama kedua ma'mulnya menurut qiraat 'yahsabanna' menempati kedudukan dua maf'ulnya, 'tahsabanna' berkedudukan sebagai maf'ul kedua dari 'tahsabanna' (\"Sesungguhnya Kami menangguhkan mereka itu hanyalah supaya dosa mereka bertambah-tambah) disebabkan banyaknya maksiat (dan bagi mereka siksa yang menghinakan\") di akhirat.",[["وَلَا","Dan (jangan)"],["يَحْسَبَنَّ","fikir"],["ٱلَّذِينَ","orang yang"],["كَفَرُوٓا۟","kufur"],["أَنَّمَا","bahawa"],["نُمْلِى","Kita beri tangguh"],["لَهُمْ","kepada mereka"],["خَيْرٌۭ","(adalah) baik"],["لِّأَنفُسِهِمْ ۚ","untuk diri mereka sendiri"],["إِنَّمَا","Hanya"],["نُمْلِى","Kita beri tangguh"],["لَهُمْ","kepada mereka"],["لِيَزْدَادُوٓا۟","supaya mereka bertambah"],["إِثْمًۭا ۚ","(dalam) dosa"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌۭ","(ialah) azab"],["مُّهِينٌۭ","memalukan"]]],"472":["(Allah sekali-kali tidak akan meninggalkan) membiarkan (orang-orang yang beriman dalam keadaan yang kamu) hai manusia (berada di atasnya) artinya yang kamu alami berupa campur aduknya yang ikhlas dengan yang lainnya (sampai Dia memisahkan) dibaca yamiiza atau yumayyiza artinya menyisihkan (orang-orang yang jelek) yaitu orang munafik (dari yang baik) yaitu orang beriman. Caranya ialah dengan tugas-tugas berat sehingga menyingkapkan yang demikian itu, misalnya seperti yang dilakukan-Nya di waktu perang Uhud. (Dan Allah sekali-kali tidak akan memperlihatkan padamu hal-hal gaib) sehingga kamu dapat mengenal mana yang munafik dan mana yang baik sebelum dipisahkan Allah itu (tetapi Allah memilih di antara rasul-rasul-Nya siapa yang dikehendaki-Nya) untuk diberitahukan-Nya hal-hal gaib itu seperti kepada Nabi saw. yang disingkapkan-Nya perihal orang-orang munafik. (Oleh sebab itu berimanlah kamu kepada Allah dan rasul-rasul-Nya dan jika kamu beriman dan bertakwa) artinya menjaga dirimu dari kemunafikan (maka akan beroleh pahala yang besar.)",[["مَّا","Tidak"],["كَانَ","ialah"],["ٱللَّهُ","Allah"],["لِيَذَرَ","untuk pergi"],["ٱلْمُؤْمِنِينَ","orang yang beriman"],["عَلَىٰ","pada"],["مَآ","apa"],["أَنتُمْ","kamu (adalah)"],["عَلَيْهِ","di dalamnya"],["حَتَّىٰ","sehingga"],["يَمِيزَ","Dia memisahkan"],["ٱلْخَبِيثَ","yang jahat"],["مِنَ","daripada"],["ٱلطَّيِّبِ ۗ","yang baik"],["وَمَا","Dan tidak"],["كَانَ","ialah"],["ٱللَّهُ","Allah"],["لِيُطْلِعَكُمْ","untuk memberitahu kamu"],["عَلَى","tentang"],["ٱلْغَيْبِ","yang ghaib"],["وَلَـٰكِنَّ","[dan] tetapi"],["ٱللَّهَ","Allah"],["يَجْتَبِى","memilih"],["مِن","daripada"],["رُّسُلِهِۦ","Rasul-rasulNya"],["مَن","yang"],["يَشَآءُ ۖ","Dia kehendaki"],["فَـَٔامِنُوا۟","jadi percayalah"],["بِٱللَّهِ","kepada Allah"],["وَرُسُلِهِۦ ۚ","dan Rasul-rasulNya"],["وَإِن","dan jika"],["تُؤْمِنُوا۟","kamu beriman"],["وَتَتَّقُوا۟","dan bertakwalah kepada Allah"],["فَلَكُمْ","kemudian untuk kamu"],["أَجْرٌ","(adalah) ganjaran"],["عَظِيمٌۭ","yang besar"]]],"473":["(Sekali-kali janganlah menyangka) dengan memakai 'ya' atau 'ta' (orang-orang yang bakhil dengan harta yang diberikan Allah dan karunia-Nya) artinya mengeluarkan zakatnya (bahwa itu) maksudnya kebakhilan itu (baik bagi mereka) menjadi maf'ul yang kedua sedangkan dhamir sebagai pemisah. Maf'ul yang pertama ialah 'kebakhilan mereka' yang diperkirakan sebelum isim maushul jika dibaca dengan 'ta' dan sebelum dhamir jika dengan 'ya' (tetapi itu buruk bagi mereka. Mereka akan dikalungi harta yang mereka bakhilkan) tidak dikeluarkan zakatnya (pada hari kiamat) yakni dengan melilitkan ular pada lehernya dan ular itu mematuknya sebagaimana tercantum dalam sebuah hadis. (Milik Allahlah segala warisan langit dan bumi) yang akan diwarisi-Nya setelah lenyap atau musnahnya penghuni langit dan bumi. (Dan Allah Maha Mengetahui apa yang kamu kerjakan) sehingga akan mendapat balasan daripada-Nya. Ada yang membaca 'ta'maluuna' dengan 'ta' ada pula 'ya'maluuna' dengan 'ya.'",[["وَلَا","Dan (jangan)"],["يَحْسَبَنَّ","fikir"],["ٱلَّذِينَ","orang yang"],["يَبْخَلُونَ","menahan"],["بِمَآ","tentang apa"],["ءَاتَىٰهُمُ","(telah) memberi mereka"],["ٱللَّهُ","Allah"],["مِن","daripada"],["فَضْلِهِۦ","Bounty-Nya"],["هُوَ","(itu) itu"],["خَيْرًۭا","(adalah) baik"],["لَّهُم ۖ","bagi mereka"],["بَلْ","Bahkan"],["هُوَ","ia"],["شَرٌّۭ","(adalah) buruk"],["لَّهُمْ ۖ","bagi mereka"],["سَيُطَوَّقُونَ","Leher mereka akan dilingkari"],["مَا","(dengan) apa"],["بَخِلُوا۟","mereka menahan"],["بِهِۦ","[dengannya]"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۗ","(dari) [the] Kebangkitan"],["وَلِلَّهِ","Dan untuk Allah"],["مِيرَٰثُ","(adalah) warisan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۗ","dan bumi"],["وَٱللَّهُ","Dan Allah"],["بِمَا","dengan apa"],["تَعْمَلُونَ","kamu lakukan"],["خَبِيرٌۭ","(adalah) Maha Mengetahui"]]],"474":["(Sungguh Allah telah mendengar ucapan orang-orang yang mengatakan, \"Sesungguhnya Allah itu miskin dan kami kaya.\") Mereka itu ialah orang-orang Yahudi yang mengatakannya tatkala turun ayat \"Siapakah yang bersedia memberi pinjaman kepada Allah suatu pinjaman yang baik?\" Kata mereka, \"Sekiranya Dia kaya tentulah Dia tidak akan meminjam kepada kita!\" (Kami akan mencatat) maksudnya akan menyuruh mencatat (apa yang mereka katakan itu) yakni dalam buku catatan amal perbuatan mereka agar mereka menerima balasannya. Menurut suatu qiraat dibaca 'sayuktabu' bukan 'sanaktubu.' (Dan) Kami catat pula (pembunuhan mereka) memakai baris di atas atau baris di depan (atas nabi-nabi tanpa alasan yang benar dan Kami katakan) ada yang membaca 'naquulu' dan ada pula 'yaquulu' yang berarti bahwa yang mengatakan itu ialah Allah yakni di akhirat kelak, perantaraan lisan para malaikat ('Rasailah olehmu azab neraka) lalu dikatakan pula kepada mereka bila mereka dilemparkan ke dalam neraka.",[["لَّقَدْ","Sungguh"],["سَمِعَ","didengari"],["ٱللَّهُ","Allah"],["قَوْلَ","(yang) berkata"],["ٱلَّذِينَ","orang yang"],["قَالُوٓا۟","berkata"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["فَقِيرٌۭ","(adalah) miskin"],["وَنَحْنُ","sedangkan kita"],["أَغْنِيَآءُ ۘ","(adalah) kaya"],["سَنَكْتُبُ","Kami akan merakam"],["مَا","apa"],["قَالُوا۟","mereka berkata"],["وَقَتْلَهُمُ","dan pembunuhan mereka"],["ٱلْأَنۢبِيَآءَ","para Nabi"],["بِغَيْرِ","tanpa"],["حَقٍّۢ","(mana-mana) betul"],["وَنَقُولُ","dan Kami akan berkata"],["ذُوقُوا۟","rasa"],["عَذَابَ","azab"],["ٱلْحَرِيقِ","(dari) Api yang Menyala"]]],"475":["(Demikian itu) maksudnya azab neraka tadi (disebabkan perbuatan tanganmu sendiri) diibaratkan dengan tangan karena kebanyakan perbuatan manusia dilaksanakan dengannya (dan bahwa Allah sekali-kali tidak menganiaya) artinya tidak berbuat aniaya atau melakukan keaniayaan (terhadap hamba-hamba-Nya) Allah tidak akan menyiksa orang-orang yang tidak bersalah atau berdosa.",[["ذَٰلِكَ","Itu"],["بِمَا","(adalah) kerana"],["قَدَّمَتْ","(dari apa) yang dihantar"],["أَيْدِيكُمْ","tangan kamu"],["وَأَنَّ","dan bahawa"],["ٱللَّهَ","Allah"],["لَيْسَ","bukan"],["بِظَلَّامٍۢ","tidak adil"],["لِّلْعَبِيدِ","kepada hamba-hamba-Nya"]]],"476":["(Yakni orang-orang yang) 'na'at' atau sifat bagi alladziina yang sebelumnya (mengatakan) kepada Muhammad (\"Sesungguhnya Allah telah menitahkan kepada kami) dalam Taurat (supaya kami tidak beriman kepada seorang rasul) artinya tidak membenarkannya (sebelum ia mendatangkan kepada kami suatu kurban yang dimakan api\"). Maka kami tidak akan beriman kepadamu sebelum membawakan kurban, pemberian, yang mendekatkan diri kepada Allah berupa ternak atau lainnya. Jika kurban itu diterima, maka dari langit akan muncul api putih yang akan membakarnya. Dan jika tidak, maka ia akan tetap tinggal di tempatnya tanpa ada yang menyentuhnya. Hal ini diperintahkan kepada Bani Israel tetapi kepada Almasih dan Muhammad tidak demikian halnya, Allah swt. berfirman (Katakanlah) kepada mereka sebagai celaan (\"Bukankah telah datang kepadamu beberapa orang rasul sebelumku dengan membawa keterangan-keterangan nyata) atau mukjizat (dan dengan apa yang kamu sebutkan itu) seperti Zakaria dan Yahya, tetapi mereka kamu bunuh juga. Perkataan ini ditujukan kepada orang-orang Yahudi yang hidup di masa Nabi kita saw. walaupun perbuatan itu dari nenek moyang mereka karena mereka menyetujuinya. (Maka kenapa kamu bunuh mereka jika kamu orang-orang yang benar?\") maksudnya jika kamu benar-benar beriman ketika melakukan pelanggaran itu.",[["ٱلَّذِينَ","Orang yang"],["قَالُوٓا۟","berkata"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["عَهِدَ","(telah) berjanji"],["إِلَيْنَآ","daripada kami"],["أَلَّا","itu tidak"],["نُؤْمِنَ","kita (harus) beriman"],["لِرَسُولٍ","dalam Rasul"],["حَتَّىٰ","sehingga"],["يَأْتِيَنَا","dia bawa kepada kita"],["بِقُرْبَانٍۢ","pengorbanan"],["تَأْكُلُهُ","memakannya"],["ٱلنَّارُ ۗ","api"],["قُلْ","Katakanlah"],["قَدْ","pastinya"],["جَآءَكُمْ","datang kepada kamu"],["رُسُلٌۭ","Utusan"],["مِّن","daripada"],["قَبْلِى","sebelum aku"],["بِٱلْبَيِّنَـٰتِ","dengan tanda-tanda yang jelas"],["وَبِٱلَّذِى","dan dengan apa"],["قُلْتُمْ","kamu bercakap"],["فَلِمَ","Jadi kenapa"],["قَتَلْتُمُوهُمْ","kamu membunuh mereka"],["إِن","jika"],["كُنتُمْ","kamu"],["صَـٰدِقِينَ","jujur"]]],"477":["(Jika mereka mendustakanmu, maka sesungguhnya rasul-rasul yang sebelum kamu pun telah didustakan pula, padahal mereka membawa keterangan-keterangan yang nyata) yakni mukjizat (dan zubur) maksudnya shuhuf-shuhuf seperti shuhuf Nabi Ibrahim (dan Alkitab) menurut satu qiraat dengan memakai 'ba' pada al-kitab dan az-zubur (yang terang) yakni Taurat dan Injil, maka bersabarlah kamu sebagaimana mereka telah bersabar.",[["فَإِن","Kemudian jika"],["كَذَّبُوكَ","mereka menolak kamu"],["فَقَدْ","maka sudah tentu"],["كُذِّبَ","telah ditolak"],["رُسُلٌۭ","Utusan"],["مِّن","daripada"],["قَبْلِكَ","sebelum kamu"],["جَآءُو","(siapa) datang"],["بِٱلْبَيِّنَـٰتِ","dengan tanda-tanda yang jelas"],["وَٱلزُّبُرِ","dan Kitab Suci"],["وَٱلْكِتَـٰبِ","dan Kitab"],["ٱلْمُنِيرِ","[the] Pencerahan"]]],"478":["(Setiap diri akan merasai kematian dan hanya pada hari kiamatlah pahalamu disempurnakan) artinya pada hari kiamatlah ganjaran amal perbuatanmu dipenuhi dengan cukup. (Barang siapa yang dijauhkan) setelah itu (dari neraka dan dimasukkan ke dalam surga, maka sungguh ia beruntung) karena mencapai apa yang dicita-citakannya. (Kehidupan dunia ini tidak lain) maksudnya hidup di dunia ini (hanyalah kesenangan yang memperdayakan semata) artinya yang tidak sebenarnya karena dinikmati hanya sementara lalu ia segera sirna.",[["كُلُّ","Setiap"],["نَفْسٍۢ","jiwa"],["ذَآئِقَةُ","(akan) rasa"],["ٱلْمَوْتِ ۗ","[the] kematian"],["وَإِنَّمَا","dan hanya"],["تُوَفَّوْنَ","kamu akan dibayar penuh"],["أُجُورَكُمْ","ganjaran kamu"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۖ","(dari) [the] Kebangkitan"],["فَمَن","Kemudian sesiapa sahaja"],["زُحْزِحَ","ditarik jauh"],["عَنِ","daripada"],["ٱلنَّارِ","neraka"],["وَأُدْخِلَ","dan mengaku"],["ٱلْجَنَّةَ","(ke) Syurga"],["فَقَدْ","maka pasti"],["فَازَ ۗ","dia berjaya"],["وَمَا","Dan tidak"],["ٱلْحَيَوٰةُ","(ialah) kehidupan"],["ٱلدُّنْيَآ","dunia"],["إِلَّا","kecuali"],["مَتَـٰعُ","kenikmatan"],["ٱلْغُرُورِ","(dari) khayalan"]]],"479":["(Kamu sungguh-sungguh akan diuji) karena berturut-turutnya beberapa 'nun' maka nun tanda rafa'nya dihilangkan, begitu juga 'wau' dhamir jamak karena bertemunya dua wawu sakin, sedangkan artinya ialah kamu sungguh-sungguh akan diuji atau dicoba (mengenai hartamu) dengan beban-beban dan kewajiban yang harus kamu penuhi (dan dirimu) dengan ibadat dan ujian berupa malapetaka (dan sungguh akan kamu dengar dari orang-orang yang diberi Kitab sebelum kamu) yakni dari orang-orang Yahudi dan Nasrani (dan dari orang-orang musyrik) dari kalangan Arab (gangguan menyakitkan yang banyak sekali) berupa makian dan tuduhan serta godaan dan gangguan terhadap wanita-wanitamu. (Jika kamu bersabar) atas tantangan itu (dan bertakwa) kepada Allah (maka demikian itu termasuk di antara pekerjaan-pekerjaan utama) termasuk hal-hal yang harus dipentingkan dan wajib dihadapi dengan keteguhan hati dan kesabaran yang penuh.",[["۞ لَتُبْلَوُنَّ","Kamu pasti akan diuji"],["فِىٓ","dalam"],["أَمْوَٰلِكُمْ","kekayaan kamu"],["وَأَنفُسِكُمْ","dan diri kamu sendiri"],["وَلَتَسْمَعُنَّ","Dan kamu pasti akan mendengar"],["مِنَ","daripada"],["ٱلَّذِينَ","orang yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["مِن","daripada"],["قَبْلِكُمْ","sebelum kamu"],["وَمِنَ","dan daripada"],["ٱلَّذِينَ","orang yang"],["أَشْرَكُوٓا۟","mempersekutukan Allah"],["أَذًۭى","perkara yang menyakitkan hati"],["كَثِيرًۭا ۚ","ramai"],["وَإِن","dan jika"],["تَصْبِرُوا۟","kamu sabar"],["وَتَتَّقُوا۟","dan bertakwalah kepada Allah"],["فَإِنَّ","maka sesungguhnya"],["ذَٰلِكَ","bahawa"],["مِنْ","(adalah) daripada"],["عَزْمِ","perkara-perkara"],["ٱلْأُمُورِ","(dari) keazaman"]]],"480":["(Dan) ingatlah (ketika Allah mengambil ikrar dari orang-orang yang diberi Alkitab) yakni tugas yang diberikan kepada mereka dalam Taurat (\"Hendaklah kamu menerangkannya) maksudnya isi Alkitab itu (kepada manusia dan janganlah kamu menyembunyikannya\") yakni Alkitab itu. Kedua kata kerja pada kalimat ini dengan memakai 'ta' dan 'ya.' (Lalu mereka melemparkannya) maksudnya ikrar tersebut (ke belakang punggung mereka) artinya tidak mereka penuhi dan amalkan (dan mereka menukarnya dengan) mereka ambil sebagai gantinya (harga yang sedikit) berupa harta benda dunia yang mereka pungut dari rakyat bawahan dengan keunggulan mereka dalam ilmu Alkitab. Maka ilmu itu mereka sembunyikan karena takut akan lepas dari tangan. (Maka amat jeleklah tukaran yang mereka terima) atau penukaran yang mereka lakukan itu.",[["وَإِذْ","Dan apabila"],["أَخَذَ","mengambil"],["ٱللَّهُ","Allah"],["مِيثَـٰقَ","sebuah Perjanjian"],["ٱلَّذِينَ","(dari) mereka yang"],["أُوتُوا۟","telah diberikan"],["ٱلْكِتَـٰبَ","Kitab"],["لَتُبَيِّنُنَّهُۥ","Kamu pasti menjelaskannya"],["لِلنَّاسِ","kepada umat manusia"],["وَلَا","dan jangan"],["تَكْتُمُونَهُۥ","menyembunyikannya"],["فَنَبَذُوهُ","Kemudian mereka melemparkannya"],["وَرَآءَ","belakang"],["ظُهُورِهِمْ","belakang mereka"],["وَٱشْتَرَوْا۟","dan mereka bertukar"],["بِهِۦ","[dengan] itu"],["ثَمَنًۭا","(untuk) harga"],["قَلِيلًۭا ۖ","sedikit"],["فَبِئْسَ","Dan celaka"],["مَا","(ialah) apa"],["يَشْتَرُونَ","mereka beli"]]],"481":["(Janganlah sekali-kali kamu kira) dengan memakai 'ta' dan 'ya' (bahwa orang-orang yang merasa gembira dengan apa yang telah mereka lakukan) yakni dengan apa yang telah mereka perbuat yaitu menyesatkan manusia (dan mereka ingin supaya dipuji terhadap perbuatan yang belum mereka kerjakan) yakni berpegang kepada kebenaran padahal mereka dalam kesesatan (janganlah kamu menyangka mereka) merupakan taukid atau pengukuhan dengan kedua versinya, memakai 'ta' dan 'ya' (terlepas) artinya berada di suatu tempat yang bebas (dari siksa) di akhirat tetapi mereka berada di suatu tempat di mana mereka akan menerima siksa yaitu di neraka Jahanam (dan bagi mereka siksa yang pedih) menyakitkan. Kedua maf'ul yahsabu yang pertama terkandung di dalam kedua maf'ul yahsabu yang kedua berdasarkan qiraat yahsabu sedangkan menurut qiraat tahsabu hanya maf'ul kedualah yang dibuang.",[["لَا","Jangan"],["تَحْسَبَنَّ","fikir"],["ٱلَّذِينَ","(bahawa) mereka yang"],["يَفْرَحُونَ","bergembiralah"],["بِمَآ","pada apa"],["أَتَوا۟","(mereka telah) membawa"],["وَّيُحِبُّونَ","dan mereka suka"],["أَن","bahawa"],["يُحْمَدُوا۟","mereka dipuji"],["بِمَا","bagi apa"],["لَمْ","tidak"],["يَفْعَلُوا۟","mereka lakukan"],["فَلَا","jadi (jangan)"],["تَحْسَبَنَّهُم","menyangka (bahawa) mereka"],["بِمَفَازَةٍۢ","(akan) melarikan diri"],["مِّنَ","daripada"],["ٱلْعَذَابِ ۖ","azab"],["وَلَهُمْ","dan untuk mereka"],["عَذَابٌ","(adalah) hukuman"],["أَلِيمٌۭ","yang pedih"]]],"482":["(Milik Allahlah kerajaan langit dan bumi) maksudnya perbendaharaan hujan, rezeki, tumbuh-tumbuhan dan lain-lain (dan Allah Maha Kuasa atas segala sesuatu) di antaranya menyiksa orang-orang kafir dan membebaskan orang-orang beriman.",[["وَلِلَّهِ","Dan untuk Allah"],["مُلْكُ","(ialah) kekuasaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ ۗ","dan bumi"],["وَٱللَّهُ","dan Allah"],["عَلَىٰ","(berada) di atas"],["كُلِّ","setiap"],["شَىْءٍۢ","perkara"],["قَدِيرٌ","Maha Berkuasa"]]],"483":["(Sesungguhnya pada penciptaan langit dan bumi) dan keajaiban-keajaiban yang terdapat pada keduanya (serta pergantian malam dan siang) dengan datang dan pergi serta bertambah dan berkurang (menjadi tanda-tanda) atau bukti-bukti atas kekuasaan Allah swt. (bagi orang-orang yang berakal) artinya yang mempergunakan pikiran mereka.",[["إِنَّ","Sesungguhnya"],["فِى","dalam"],["خَلْقِ","(the) penciptaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["وَٱخْتِلَـٰفِ","dan (dalam) silih berganti"],["ٱلَّيْلِ","(dari) malam"],["وَٱلنَّهَارِ","dan hari"],["لَـَٔايَـٰتٍۢ","(adalah) sesungguhnya tanda-tanda"],["لِّأُو۟لِى","untuk lelaki"],["ٱلْأَلْبَـٰبِ","(dari) pemahaman"]]],"484":["(Yakni orang-orang yang) menjadi 'na`at' atau badal bagi yang sebelumnya (mengingat Allah di waktu berdiri dan duduk dan ketika berbaring) artinya dalam keadaan bagaimana pun juga sedang menurut Ibnu Abbas mengerjakan salat dalam keadaan tersebut sesuai dengan kemampuan (dan mereka memikirkan tentang kejadian langit dan bumi) untuk menyimpulkan dalil melalui keduanya akan kekuasaan Allah, kata mereka: (\"Wahai Tuhan kami! Tidaklah Engkau ciptakan ini) maksudnya makhluk yang kami saksikan ini (dengan sia-sia) menjadi hal sebaliknya semua ini menjadi bukti atas kesempurnaan kekuasaan-Mu (Maha Suci Engkau) artinya tidak mungkin Engkau akan berbuat sia-sia (maka lindungilah kami dari siksa neraka.)",[["ٱلَّذِينَ","Orang yang"],["يَذْكُرُونَ","ingat"],["ٱللَّهَ","Allah"],["قِيَـٰمًۭا","berdiri"],["وَقُعُودًۭا","dan duduk"],["وَعَلَىٰ","dan seterusnya"],["جُنُوبِهِمْ","pihak mereka"],["وَيَتَفَكَّرُونَ","dan mereka merenung"],["فِى","pada"],["خَلْقِ","(the) penciptaan"],["ٱلسَّمَـٰوَٰتِ","langit"],["وَٱلْأَرْضِ","dan bumi"],["رَبَّنَا","Wahai Tuhan kami"],["مَا","tidak"],["خَلَقْتَ","Kamu telah mencipta"],["هَـٰذَا","ini"],["بَـٰطِلًۭا","(dalam) sia-sia"],["سُبْحَـٰنَكَ","Maha Suci Engkau"],["فَقِنَا","jadi selamatkan kami"],["عَذَابَ","(dari) hukuman"],["ٱلنَّارِ","(dari) api"]]],"485":["(Wahai Tuhan kami! Sesungguhnya barang siapa yang Engkau masukkan ke dalam neraka) untuk hidup kekal di sana (maka berarti Engkau telah menghinakannya dan tiadalah bagi orang-orang yang aniaya) maksudnya orang-orang yang kafir; di sini ditempatkan zhahir pada tempat mudhmar untuk mengingatkan dikhususkannya kehinaan itu bagi mereka (dari) merupakan tambahan (seorang penolong pun) yang akan melindungi mereka dari siksa Allah swt.",[["رَبَّنَآ","Wahai Tuhan kami"],["إِنَّكَ","sesungguhnya [Kamu]"],["مَن","yang"],["تُدْخِلِ","kamu mengaku"],["ٱلنَّارَ","(kepada) api"],["فَقَدْ","maka pasti"],["أَخْزَيْتَهُۥ ۖ","Kamu (telah) memalukan dia"],["وَمَا","dan bukan"],["لِلظَّـٰلِمِينَ","bagi orang-orang yang zalim"],["مِنْ","(ada) mana-mana"],["أَنصَارٍۢ","pembantu"]]],"486":["(Wahai Tuhan kami! Sesungguhnya kami telah mendengar seorang penyeru yang menyeru) manusia (untuk beriman) kepadanya, yaitu Muhammad atau Alquran (supaya) maksudnya yakni: ('Berimanlah kepada Tuhanmu!' Maka kami pun berimanlah) kepada-Nya (Wahai Tuhan kami! Ampunilah bagi kami dosa-dosa kami dan hapuskanlah) tutup (dari kami kesalahan-kesalahan kami) artinya janganlah dibukakan kepada umum dengan memberikan hukuman terhadapnya (dan wafatkanlah kami) cabutlah nyawa kami (bersama) golongan (orang-orang yang berbakti) yakni para nabi dan orang-orang saleh.",[["رَّبَّنَآ","Wahai Tuhan kami"],["إِنَّنَا","sesungguhnya kita"],["سَمِعْنَا","[kami] dengar"],["مُنَادِيًۭا","seorang pemanggil"],["يُنَادِى","memanggil"],["لِلْإِيمَـٰنِ","kepada iman"],["أَنْ","bahawa"],["ءَامِنُوا۟","Percayalah"],["بِرَبِّكُمْ","pada Tuhanmu"],["فَـَٔامَنَّا ۚ","maka kami telah beriman"],["رَبَّنَا","Wahai Tuhan kami"],["فَٱغْفِرْ","jadi maafkan"],["لَنَا","bagi kami"],["ذُنُوبَنَا","dosa kita"],["وَكَفِّرْ","dan keluarkan"],["عَنَّا","daripada kami"],["سَيِّـَٔاتِنَا","perbuatan jahat kita"],["وَتَوَفَّنَا","dan menyebabkan kita mati"],["مَعَ","dengan"],["ٱلْأَبْرَارِ","orang yang soleh"]]],"487":["(Wahai Tuhan kami! Berilah kami apa yang telah Engkau janjikan kepada kami) (atas) artinya dengan perantaraan (para rasul-Mu) berupa nikmat dan karunia serta apa-apa yang mereka mohonkan walaupun janji Allah itu tidak bertentangan dengan permohonan orang yang meminta agar ia termasuk dalam golongan orang-orang yang diberi karunia disebabkan ia belum beroleh kepastian bahwa permohonannya itu akan dikabulkan. Mengenai disebutnya 'Wahai Tuhan kami' secara berulang-ulang maka itu menyatakan ketundukan dan kerendahan hati yang sedalam-dalamnya. (Dan janganlah Engkau hinakan kami pada hari kiamat, sesungguhnya Engkau tidak menyalahi janji.\") yaitu janji dengan kebangkitan dan pembalasan.",[["رَبَّنَا","Wahai Tuhan kami"],["وَءَاتِنَا","kurniakan kami"],["مَا","apa"],["وَعَدتَّنَا","Kamu berjanji kepada kami"],["عَلَىٰ","melalui"],["رُسُلِكَ","Rasul-rasulmu"],["وَلَا","dan jangan"],["تُخْزِنَا","memalukan kita"],["يَوْمَ","(pada) hari"],["ٱلْقِيَـٰمَةِ ۗ","(dari) [the] Kebangkitan"],["إِنَّكَ","Sesungguhnya, Engkau"],["لَا","jangan"],["تُخْلِفُ","rehat"],["ٱلْمِيعَادَ","janji itu"]]],"488":["(Maka Tuhan mereka memperkenankan bagi mereka) permohonan mereka (bahwa Aku tidak akan menyia-nyiakan amalan orang-orang yang beramal di antara kamu baik laki-laki maupun perempuan, sebagian kamu) adalah (dari sebagian yang lain) artinya laki-laki adalah turunan wanita sebaliknya wanita adalah keturunan laki-laki. Kalimat ini memperkuat kalimat yang sebelumnya yakni bahwa mereka akan sama-sama menerima balasan dari amal perbuatan masing-masing dan bahwa mereka sama-sama tidak akan disepelekan. Lanjutan ayat berikut turun ketika Ummu Salamah mengatakan kepada Rasulullah, \"Wahai Rasulullah! Tidak pernah saya dengar wanita disebut-sebut dalam soal hijrah.\" (Maka orang-orang yang berhijrah) dari Mekah ke Madinah (yang diusir dari kampung halamannya serta disakiti pada jalan-Ku) maksudnya karena agama-Ku (dan yang berperang) melawan orang-orang kafir (dan orang-orang yang gugur) di jalan-Ku baik memakai tasydid atau tidak dan menurut satu qiraat dengan mendahulukannya (niscaya Aku hapuskan kesalahan-kesalahan mereka) Aku tutupi dosa-dosa mereka dengan ampunan-Ku (dan Kumasukkan mereka ke dalam surga yang mengalir di bawahnya sungai-sungai sebagai pahala) mashdar dari pengertian 'Kuhapus' dan memperkokoh maknanya (dari sisi Allah) terdapat perpalingan kedudukan-Nya sebagai pembicara (dan Allah di sisi-Nya terdapat pahala yang baik.) sebagai balasan. Ayat berikut turun pula tatkala kaum Muslimin mengatakan bahwa musuh Allah kelihatan berbahagia sedangkan mereka dalam keadaan susah dan menderita:",[["فَٱسْتَجَابَ","Kemudian membalas"],["لَهُمْ","kepada mereka"],["رَبُّهُمْ","Tuhan mereka"],["أَنِّى","Sesungguhnya aku"],["لَآ","(akan) tidak"],["أُضِيعُ","(lepaskan) membazir"],["عَمَلَ","perbuatan"],["عَـٰمِلٍۢ","(dari) pelaku"],["مِّنكُم","antara kamu"],["مِّن","[dari]"],["ذَكَرٍ","(sama ada) lelaki"],["أَوْ","atau"],["أُنثَىٰ ۖ","perempuan"],["بَعْضُكُم","setiap daripada kamu"],["مِّنۢ","daripada"],["بَعْضٍۢ ۖ","(yang) lain"],["فَٱلَّذِينَ","Jadi mereka yang"],["هَاجَرُوا۟","berhijrah"],["وَأُخْرِجُوا۟","dan dihalau keluar"],["مِن","daripada"],["دِيَـٰرِهِمْ","rumah mereka"],["وَأُوذُوا۟","dan telah dicederakan"],["فِى","dalam"],["سَبِيلِى","cara aku"],["وَقَـٰتَلُوا۟","dan berperang"],["وَقُتِلُوا۟","dan dibunuh"],["لَأُكَفِّرَنَّ","nescaya Aku (akan) hapuskan"],["عَنْهُمْ","daripada mereka"],["سَيِّـَٔاتِهِمْ","perbuatan jahat mereka"],["وَلَأُدْخِلَنَّهُمْ","dan sesungguhnya Aku akan mengakui mereka"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["ثَوَابًۭا","ganjaran"],["مِّنْ","daripada"],["عِندِ","[dekat]"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","Dan Allah"],["عِندَهُۥ","dengan Dia"],["حُسْنُ","(adalah) yang terbaik"],["ٱلثَّوَابِ","pahala"]]],"489":["(Janganlah sekali-kali kamu terpedaya oleh keleluasaan orang-orang kafir bepergian) artinya bergerak ke mana mereka sukai (di dalam negeri) untuk berniaga dan berusaha.",[["لَا","(Biar) jangan"],["يَغُرَّنَّكَ","menipu kamu"],["تَقَلُّبُ","(the) pergerakan"],["ٱلَّذِينَ","orang yang"],["كَفَرُوا۟","kufur"],["فِى","dalam"],["ٱلْبِلَـٰدِ","bumi"]]],"490":["(Itu hanyalah kesenangan sementara) yang mereka nikmati di dunia dalam waktu singkat kemudian akan lenyap (kemudian tempat tinggal mereka ialah neraka Jahanam dan itulah tempat yang seburuk-buruknya.)",[["مَتَـٰعٌۭ","Satu kenikmatan"],["قَلِيلٌۭ","sedikit"],["ثُمَّ","kemudian"],["مَأْوَىٰهُمْ","tempat tinggal mereka"],["جَهَنَّمُ ۚ","(adalah) neraka"],["وَبِئْسَ","[dan] seorang yang celaka"],["ٱلْمِهَادُ","[tempat] berehat"]]],"491":["(Akan tetapi orang-orang yang bertakwa kepada Tuhannya bagi mereka surga-surga yang di bawahnya mengalir sungai, mereka kekal) maksudnya ditakdirkan kekal (padanya sebagai tempat tinggal) yang biasanya disediakan buat tamu-tamu; dijadikan manshub karena kedudukannya sebagai hal dari jannaat sedangkan sebagai amilnya ialah pengertian zharf (dari sisi Allah dan apa yang dari sisi Allah) berupa pahala (lebih baik bagi orang-orang yang berbakti) daripada kesenangan dunia.",[["لَـٰكِنِ","Tetapi"],["ٱلَّذِينَ","orang yang"],["ٱتَّقَوْا۟","bertakwa"],["رَبَّهُمْ","Tuhan mereka"],["لَهُمْ","bagi mereka"],["جَنَّـٰتٌۭ","(akan menjadi) taman-taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","akan kekal selama-lamanya"],["فِيهَا","di dalamnya"],["نُزُلًۭا","sebuah keramahan"],["مِّنْ","daripada"],["عِندِ","[dekat]"],["ٱللَّهِ ۗ","Allah"],["وَمَا","Dan apa"],["عِندَ","(adalah) dengan"],["ٱللَّهِ","Allah"],["خَيْرٌۭ","(adalah) terbaik"],["لِّلْأَبْرَارِ","untuk orang yang soleh"]]],"492":["(Sesungguhnya di antara Ahli Kitab ada orang yang beriman kepada Allah) seperti Abdullah bin Salam dan sahabat-sahabatnya serta Najasyi (dan kepada apa yang diturunkan kepadamu) yakni Alquran (dan kepada apa yang telah diturunkan kepada mereka) yakni Taurat dan Injil (dalam keadaan merendahkan diri) hal dari dhamir pada 'yu`minu' dengan menekankan makna 'man' dengan arti 'tawadhu`' (kepada Allah tanpa menukarkan ayat-ayat Allah) yang terdapat pada mereka dalam Taurat dan Injil berupa kebangkitan Nabi saw. (dengan harga yang sedikit) dari harta dunia, misalnya dengan menyembunyikannya karena takut kehilangan pengaruh seperti dilakukan oleh orang-orang Yahudi lainnya. (Mereka beroleh pahala) sebagai balasan atas amal perbuatan mereka (di sisi Tuhan mereka) yang diberikan kepada mereka dua kali sebagaimana terdapat dalam surah Al-Qashash (sesungguhnya Allah amat cepat perhitungan-Nya) dapat melakukan perhitungan terhadap seluruh makhluk dalam hanya setengah hari saja dari hari-hari dunia.",[["وَإِنَّ","Dan sesungguhnya"],["مِنْ","antara"],["أَهْلِ","(the) Rakyat"],["ٱلْكِتَـٰبِ","Kitab"],["لَمَن","(adalah) siapa"],["يُؤْمِنُ","beriman"],["بِٱللَّهِ","kepada Allah"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْكُمْ","kepada kamu"],["وَمَآ","dan apa"],["أُنزِلَ","telah didedahkan"],["إِلَيْهِمْ","kepada mereka"],["خَـٰشِعِينَ","tunduk dengan rendah hati"],["لِلَّهِ","kepada Allah"],["لَا","Tidak"],["يَشْتَرُونَ","(adakah) mereka bertukar"],["بِـَٔايَـٰتِ","[dengan] (the) Ayat"],["ٱللَّهِ","(milik) Allah"],["ثَمَنًۭا","(untuk) harga"],["قَلِيلًا ۗ","sedikit"],["أُو۟لَـٰٓئِكَ","Mereka itu"],["لَهُمْ","bagi mereka"],["أَجْرُهُمْ","ganjaran mereka"],["عِندَ","(adalah) dengan"],["رَبِّهِمْ ۗ","Tuhan mereka"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["سَرِيعُ","(adalah) pantas"],["ٱلْحِسَابِ","(dalam mengambil) akaun"]]],"493":["(Hai orang-orang yang beriman, bersabarlah) melakukan taat dan menghadapi musibah serta menghindari maksiat (dan teguhkanlah kesabaranmu) menghadapi orang-orang kafir hingga mereka tidak lebih sabar daripada kamu (dan tetaplah waspada serta siap siaga) dalam perjuangan (serta bertakwalah kepada Allah) dalam setiap keadaan (supaya kamu beruntung) merebut surga dan bebas dari neraka.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["ٱصْبِرُوا۟","Bersabarlah"],["وَصَابِرُوا۟","dan bersabarlah"],["وَرَابِطُوا۟","dan tetap"],["وَٱتَّقُوا۟","dan ketakutan"],["ٱللَّهَ","Allah"],["لَعَلَّكُمْ","supaya kamu"],["تُفْلِحُونَ","(berjaya)."]]],"494":["(Hai manusia) penduduk Mekah (bertakwalah kamu kepada Tuhanmu) artinya takutlah akan siksa-Nya dengan jalan menaati-Nya (yang telah menciptakan kamu dari satu diri) yakni Adam (dan menciptakan daripadanya istrinya) yaitu Hawa; dibaca panjang; dari salah satu tulang rusuknya yang kiri (lalu mengembangbiakkan) menyebarluaskan (dari kedua mereka itu) dari Adam dan Hawa (laki-laki yang banyak dan wanita) yang tidak sedikit jumlahnya. (Dan bertakwalah kepada Allah yang kamu saling meminta) terdapat idgam ta pada sin sedangkan menurut satu qiraat dengan takhfif yaitu membuangnya sehingga menjadi tas-aluuna (dengan nama-Nya) yang sebagian kamu mengatakan kepada sebagian lainnya, \"Saya meminta kepadamu dengan nama Allah,\" (dan) jagalah pula (hubungan silaturahmi) jangan sampai terputus. Menurut satu qiraat dibaca dengan kasrah diathafkan kepada dhamir yang terdapat pada bihi. Mereka juga biasa saling bersumpah dengan hubungan rahim. (Sesungguhnya Allah selalu mengawasi kamu) menjaga perbuatanmu dan memberi balasan terhadapnya. Maka sifat mengawasi selalu melekat dan terdapat pada Allah swt. Ayat berikut diturunkan mengenai seorang anak yatim yang meminta hartanya kepada walinya tetapi ia tidak mau memberikannya.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلنَّاسُ","manusia"],["ٱتَّقُوا۟","Takut"],["رَبَّكُمُ","Tuhanmu"],["ٱلَّذِى","yang Esa"],["خَلَقَكُم","mencipta kamu"],["مِّن","daripada"],["نَّفْسٍۢ","sebuah jiwa"],["وَٰحِدَةٍۢ","bujang"],["وَخَلَقَ","dan dicipta"],["مِنْهَا","daripadanya"],["زَوْجَهَا","jodohnya"],["وَبَثَّ","dan tersebar"],["مِنْهُمَا","daripada mereka berdua"],["رِجَالًۭا","lelaki"],["كَثِيرًۭا","ramai"],["وَنِسَآءًۭ ۚ","dan wanita"],["وَٱتَّقُوا۟","Dan ketakutan"],["ٱللَّهَ","Allah"],["ٱلَّذِى","(melalui) Siapa"],["تَسَآءَلُونَ","kamu tanya"],["بِهِۦ","[dengannya]"],["وَٱلْأَرْحَامَ ۚ","dan rahim"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["عَلَيْكُمْ","atas kamu"],["رَقِيبًۭا","Sentiasa Berjaga-jaga"]]],"495":["(Dan berikanlah kepada anak-anak yatim) yaitu anak-anak yang tidak berbapak (harta mereka) jika sudah balig (dan janganlah kamu tukar yang baik dengan yang buruk) artinya yang halal dengan yang haram dan janganlah kamu ambil harta yang baik dari anak yatim itu lalu kamu ganti dengan hartamu yang jelek (dan jangan kamu makan harta mereka) yang telah dicampur aduk (dengan hartamu. Sesungguhnya itu) maksudnya memakan yang demikian itu (adalah dosa) atau kesalahan (besar). Tatkala ayat ini turun mereka berkeberatan untuk menjadi wali anak yatim. Kemudian di antara mereka ada orang yang memiliki sepuluh atau delapan orang istri sehingga ia tak sanggup untuk berlaku adil di antara mereka, maka turunlah ayat:",[["وَءَاتُوا۟","Dan berikan"],["ٱلْيَتَـٰمَىٰٓ","(kepada) anak-anak yatim"],["أَمْوَٰلَهُمْ ۖ","kekayaan mereka"],["وَلَا","dan jangan"],["تَتَبَدَّلُوا۟","pertukaran"],["ٱلْخَبِيثَ","yang buruk"],["بِٱلطَّيِّبِ ۖ","dengan kebaikan"],["وَلَا","dan jangan"],["تَأْكُلُوٓا۟","memakan"],["أَمْوَٰلَهُمْ","kekayaan mereka"],["إِلَىٰٓ","dengan"],["أَمْوَٰلِكُمْ ۚ","kekayaan kamu"],["إِنَّهُۥ","Sesungguhnya, ia"],["كَانَ","ialah"],["حُوبًۭا","satu dosa"],["كَبِيرًۭا","yang besar"]]],"496":["(Dan jika kamu takut tidak akan dapat berlaku adil terhadap anak-anak yatim) sehingga sulit bagi kamu untuk menghadapi mereka lalu kamu takut pula tidak akan dapat berlaku adil di antara wanita-wanita yang kamu kawini (maka kawinilah) (apa) dengan arti siapa (yang baik di antara wanita-wanita itu bagi kamu dua, tiga atau empat orang) boleh dua, tiga atau empat tetapi tidak boleh lebih dari itu. (kemudian jika kamu tidak akan dapat berlaku adil) di antara mereka dalam giliran dan pembagian nafkah (maka hendaklah seorang saja) yang kamu kawini (atau) hendaklah kamu batasi pada (hamba sahaya yang menjadi milikmu) karena mereka tidak mempunyai hak-hak sebagaimana istri-istri lainnya. (Yang demikian itu) maksudnya mengawini empat orang istri atau seorang istri saja, atau mengambil hamba sahaya (lebih dekat) kepada (tidak berbuat aniaya) atau berlaku lalim.",[["وَإِنْ","Dan jika"],["خِفْتُمْ","kamu takut"],["أَلَّا","itu tidak"],["تُقْسِطُوا۟","kamu akan dapat melakukan keadilan"],["فِى","dengan"],["ٱلْيَتَـٰمَىٰ","anak-anak yatim"],["فَٱنكِحُوا۟","kemudian berkahwin"],["مَا","apa"],["طَابَ","nampak sesuai"],["لَكُم","kepada kamu"],["مِّنَ","daripada"],["ٱلنِّسَآءِ","kaum wanita"],["مَثْنَىٰ","dua"],["وَثُلَـٰثَ","atau tiga"],["وَرُبَـٰعَ ۖ","atau empat"],["فَإِنْ","Tetapi jika"],["خِفْتُمْ","kamu takut"],["أَلَّا","itu tidak"],["تَعْدِلُوا۟","kamu boleh melakukan keadilan"],["فَوَٰحِدَةً","kemudian (berkahwin) seorang"],["أَوْ","atau"],["مَا","apa"],["مَلَكَتْ","memiliki"],["أَيْمَـٰنُكُمْ ۚ","tangan kanan kamu"],["ذَٰلِكَ","Itu"],["أَدْنَىٰٓ","(adalah) lebih sesuai"],["أَلَّا","itu (boleh) tidak"],["تَعُولُوا۟","kamu menindas"]]],"497":["(Berikanlah kepada wanita-wanita itu maskawin mereka) jamak dari shadaqah (sebagai pemberian) karena ketulusan dan kesucian hati (Kemudian jika mereka menyerahkan kepadamu sebagian dari maskawin itu dengan senang hati) nafsan merupakan tamyiz yang asalnya menjadi fa'il; artinya hati mereka senang untuk menyerahkan sebagian dari maskawin itu kepadamu lalu mereka berikan (maka makanlah dengan enak) atau sedap (lagi baik) akibatnya sehingga tidak membawa bencana di akhirat kelak. Ayat ini diturunkan terhadap orang yang tidak menyukainya.",[["وَءَاتُوا۟","Dan berikan"],["ٱلنِّسَآءَ","kaum wanita"],["صَدُقَـٰتِهِنَّ","mas kahwin mereka"],["نِحْلَةًۭ ۚ","dengan penuh kasih sayang"],["فَإِن","Tetapi jika"],["طِبْنَ","mereka hantar"],["لَكُمْ","kepada kamu"],["عَن","daripada"],["شَىْءٍۢ","sesuatu"],["مِّنْهُ","daripadanya"],["نَفْسًۭا","(sendiri)."],["فَكُلُوهُ","kemudian makan"],["هَنِيٓـًۭٔا","(dalam) kepuasan"],["مَّرِيٓـًۭٔا","(dan) kemudahan"]]],"498":["(Dan janganlah kamu serahkan) hai para wali (kepada orang-orang yang bebal) artinya orang-orang yang boros dari kalangan laki-laki, wanita dan anak-anak (harta kamu) maksudnya harta mereka yang berada dalam tanganmu (yang dijadikan Allah sebagai penunjang hidupmu) qiyaaman mashdar dari qaama; artinya penopang hidup dan pembela kepentinganmu karena akan mereka habiskan bukan pada tempatnya. Menurut suatu qiraat dibaca qayyima jamak dari qiimah; artinya alat untuk menilai harga benda-benda (hanya berilah mereka belanja daripadanya) maksudnya beri makanlah mereka daripadanya (dan pakaian dan ucapkanlah kepada mereka kata-kata yang baik) misalnya janjikan jika mereka telah dewasa, maka harta mereka itu akan diberikan semuanya kepada mereka.",[["وَلَا","Dan jangan"],["تُؤْتُوا۟","memberi"],["ٱلسُّفَهَآءَ","yang bodoh"],["أَمْوَٰلَكُمُ","kekayaan kamu"],["ٱلَّتِى","yang"],["جَعَلَ","(telah) dibuat"],["ٱللَّهُ","(oleh) Allah"],["لَكُمْ","bagi kamu"],["قِيَـٰمًۭا","satu cara sokongan"],["وَٱرْزُقُوهُمْ","(tetapi) menyediakan (untuk) mereka"],["فِيهَا","dengannya"],["وَٱكْسُوهُمْ","dan pakaian mereka"],["وَقُولُوا۟","dan bercakap"],["لَهُمْ","kepada mereka"],["قَوْلًۭا","perkataan"],["مَّعْرُوفًۭا","(dari) kebaikan"]]],"499":["(Dan hendaklah kamu uji anak-anak yatim itu) sebelum mereka balig yakni mengenai keagamaan dan tingkah laku mereka (hingga setelah mereka sampai umur untuk kawin) artinya telah mampu untuk itu dengan melihat keadaan dan usia; menurut Imam Syafii 15 tahun penuh (maka jika menurut pendapatmu) atau penglihatanmu (mereka telah cerdas) artinya pandai menjaga agama dan harta mereka (maka serahkanlah kepada mereka itu harta-harta mereka dan janganlah kamu memakannya) hai para wali (secara berlebih-lebihan) tanpa hak; ini menjadi hal (dan dengan tergesa-gesa) untuk membelanjakannya karena khawatir (mereka dewasa) hingga harta itu harus diserahkan kepada yang berhak. (Dan barang siapa) di antara para wali (yang mampu, maka hendaklah ia menahan diri) dari mengambil dan memakan harta anak yatim itu (sedangkan siapa yang miskin, maka bolehlah ia memakan) harta itu (secara sepatutnya) artinya sekadar upah jerih payahnya. (Kemudian apabila kamu menyerahkan kepada mereka) maksudnya kepada anak-anak yatim (harta mereka, maka hendaklah kamu persaksikan terhadap mereka) yakni bahwa mereka telah menerimanya dan tanggung jawabmu telah selesai. Maksudnya ialah siapa tahu kalau-kalau terjadi persengketaan nanti, maka kamu dapat mempergunakan para saksi itu. Maka perintah ini tujuannya ialah untuk memberi petunjuk (Dan cukuplah Allah) ba merupakan tambahan (sebagai pengawas) yang mengawasi perbuatan-perbuatan hamba-Nya dan memberi mereka ganjaran. Ayat berikut ini diturunkan untuk menolak kebiasaan orang-orang jahiliah yang tidak mau memberi harta warisan kepada golongan wanita dan anak-anak.",[["وَٱبْتَلُوا۟","Dan ujian"],["ٱلْيَتَـٰمَىٰ","anak-anak yatim"],["حَتَّىٰٓ","sehingga"],["إِذَا","[apabila]"],["بَلَغُوا۟","mereka sampai[ed]"],["ٱلنِّكَاحَ","(umur) perkahwinan"],["فَإِنْ","maka jika"],["ءَانَسْتُم","kamu rasa"],["مِّنْهُمْ","dalam diri mereka"],["رُشْدًۭا","pertimbangan yang wajar"],["فَٱدْفَعُوٓا۟","kemudian menyampaikan"],["إِلَيْهِمْ","kepada mereka"],["أَمْوَٰلَهُمْ ۖ","kekayaan mereka"],["وَلَا","Dan jangan"],["تَأْكُلُوهَآ","makan la"],["إِسْرَافًۭا","secara boros"],["وَبِدَارًا","dan tergesa-gesa"],["أَن","(takut) itu"],["يَكْبَرُوا۟ ۚ","mereka akan membesar"],["وَمَن","Dan sesiapa"],["كَانَ","ialah"],["غَنِيًّۭا","kaya raya"],["فَلْيَسْتَعْفِفْ ۖ","maka hendaklah dia menahan diri"],["وَمَن","dan sesiapa"],["كَانَ","ialah"],["فَقِيرًۭا","miskin"],["فَلْيَأْكُلْ","maka hendaklah dia makan (daripadanya)"],["بِٱلْمَعْرُوفِ ۚ","secara adil"],["فَإِذَا","Kemudian apabila"],["دَفَعْتُمْ","kamu hantarkan"],["إِلَيْهِمْ","kepada mereka"],["أَمْوَٰلَهُمْ","kekayaan mereka"],["فَأَشْهِدُوا۟","kemudian ambil saksi"],["عَلَيْهِمْ ۚ","ke atas mereka"],["وَكَفَىٰ","Dan sudah memadai"],["بِٱللَّهِ","Allah"],["حَسِيبًۭا","(sebagai) seorang yang membuat perhitungan"]]],"500":["(Bagi laki-laki) baik anak-anak maupun karib kerabat (ada bagian) atau hak (dari harta peninggalan ibu bapak dan karib kerabat) yang meninggal dunia (dan bagi wanita ada bagian pula dari harta peninggalan ibu bapak dan karib kerabat, baik sedikit daripadanya) maksudnya dari harta itu (atau banyak) yang dijadikan Allah (sebagai hak yang telah ditetapkan) artinya hak yang pasti yang harus diserahkan kepada mereka.",[["لِّلرِّجَالِ","Untuk lelaki"],["نَصِيبٌۭ","sebahagian"],["مِّمَّا","tentang apa"],["تَرَكَ","(ada) ditinggalkan"],["ٱلْوَٰلِدَانِ","(oleh) ibu bapa"],["وَٱلْأَقْرَبُونَ","dan saudara mara terdekat"],["وَلِلنِّسَآءِ","dan untuk wanita"],["نَصِيبٌۭ","sebahagian"],["مِّمَّا","tentang apa"],["تَرَكَ","(ada) ditinggalkan"],["ٱلْوَٰلِدَانِ","(oleh) ibu bapa"],["وَٱلْأَقْرَبُونَ","dan saudara mara terdekat"],["مِمَّا","tentang apa"],["قَلَّ","(adalah) sedikit"],["مِنْهُ","daripadanya"],["أَوْ","atau"],["كَثُرَ ۚ","banyak"],["نَصِيبًۭا","sebahagian"],["مَّفْرُوضًۭا","wajib"]]],"501":["(Dan apabila pembagian harta warisan dihadiri oleh karib kerabat) yakni dari golongan yang tidak beroleh warisan (dan anak-anak yatim serta orang-orang miskin, maka berilah mereka daripadanya sekadarnya) sebelum dilakukan pembagian (dan ucapkanlah) hai para wali (kepada mereka) yakni jika mereka masih kecil-kecil (kata-kata yang baik) atau lemah-lembut, seraya meminta maaf kepada kaum kerabat yang tidak mewarisi itu, bahwa harta peninggalan ini bukan milik kalian tetapi milik ahli waris yang masih kecil-kecil. Ada yang mengatakan bahwa hukum ini yakni pemberian kepada kaum kerabat yang tidak mewarisi telah dinasakhkan/dihapus. Tetapi ada pula yang mengatakan tidak, hanya manusialah yang mempermudah dan tidak melakukannya. Berdasarkan itu maka hukumnya sunah, tetapi Ibnu Abbas mengatakannya wajib.",[["وَإِذَا","Dan apabila"],["حَضَرَ","hadir"],["ٱلْقِسْمَةَ","(pada) (masa) pembahagian"],["أُو۟لُوا۟","(daripada)"],["ٱلْقُرْبَىٰ","kaum kerabat"],["وَٱلْيَتَـٰمَىٰ","dan anak-anak yatim"],["وَٱلْمَسَـٰكِينُ","dan orang miskin"],["فَٱرْزُقُوهُم","kemudian menyediakan mereka"],["مِّنْهُ","daripadanya"],["وَقُولُوا۟","dan bercakap"],["لَهُمْ","kepada mereka"],["قَوْلًۭا","perkataan"],["مَّعْرُوفًۭا","(dari) kebaikan"]]],"502":["(Dan hendaklah bersikap waspada) maksudnya terhadap nasib anak-anak yatim (orang-orang yang seandainya meninggalkan) artinya hampir meninggalkan (di belakang mereka) sepeninggal mereka (keturunan yang lemah) maksudnya anak-anak yang masih kecil-kecil (mereka khawatir terhadap nasib mereka) akan terlantar (maka hendaklah mereka bertakwa kepada Allah) mengenai urusan anak-anak yatim itu dan hendaklah mereka lakukan terhadap anak-anak yatim itu apa yang mereka ingini dilakukan orang terhadap anak-anak mereka sepeninggal mereka nanti (dan hendaklah mereka ucapkan) kepada orang yang hendak meninggal (perkataan yang benar) misalnya menyuruhnya bersedekah kurang dari sepertiga dan memberikan selebihnya untuk para ahli waris hingga tidak membiarkan mereka dalam keadaan sengsara dan menderita.",[["وَلْيَخْشَ","Dan biarkan ketakutan"],["ٱلَّذِينَ","orang yang"],["لَوْ","jika"],["تَرَكُوا۟","mereka pergi"],["مِنْ","daripada"],["خَلْفِهِمْ","belakang"],["ذُرِّيَّةًۭ","zuriat"],["ضِعَـٰفًا","lemah"],["خَافُوا۟","(dan) tentulah mereka takut"],["عَلَيْهِمْ","tentang mereka"],["فَلْيَتَّقُوا۟","Jadi biarkan mereka takut"],["ٱللَّهَ","Allah"],["وَلْيَقُولُوا۟","dan biarkan mereka bercakap"],["قَوْلًۭا","perkataan"],["سَدِيدًا","sesuai"]]],"503":["(Sesungguhnya orang-orang yang memakan harta anak-anak yatim secara aniaya) maksudnya tanpa hak (bahwasanya mereka menelan api sepenuh perut mereka) karena harta itu akan berubah di akhirat nanti menjadi api (dan mereka akan masuk) dalam bentuk kalimat aktif atau pun pasif (api yang bernyala-nyala) yakni api neraka yang menyebabkan mereka terbakar hangus.",[["إِنَّ","Sesungguhnya"],["ٱلَّذِينَ","orang yang"],["يَأْكُلُونَ","memakan"],["أَمْوَٰلَ","kekayaan"],["ٱلْيَتَـٰمَىٰ","(dari) anak-anak yatim"],["ظُلْمًا","secara salah"],["إِنَّمَا","sahaja"],["يَأْكُلُونَ","mereka makan"],["فِى","dalam"],["بُطُونِهِمْ","perut mereka"],["نَارًۭا ۖ","kebakaran"],["وَسَيَصْلَوْنَ","dan mereka akan dibakar"],["سَعِيرًۭا","(dalam) Api yang menyala-nyala"]]],"504":["(Allah mewasiatkan atau menitahkan padamu mengenai anak-anakmu) dengan apa yang akan disebutkan ini: (yaitu bagian seorang anak lelaki sama dengan bagian dua orang anak perempuan) di antara mereka. Jika ketiga mereka itu berkumpul, maka bagi yang lelaki seperdua harta dan bagi kedua anak perempuan seperdua pula. Sedangkan jika yang ditemui itu hanya seorang anak lelaki dan seorang perempuan, maka bagi yang perempuan itu hanya sepertiga sementara bagi yang laki-laki dua pertiga. Dan sekiranya yang laki-laki itu tunggal, maka ia menghabisi semua harta (jika mereka) maksudnya anak-anak itu (hanya perempuan) saja (lebih dari dua orang maka bagi mereka dua pertiga harta yang ditinggalkan) mayat; demikian pula jika jumlah mereka dua orang karena mereka itu dua bersaudara yang tercakup dalam firman Allah swt., \"... maka bagi mereka dua pertiga dari harta peninggalan,\" mereka lebih utama apalagi mengingat bahwa seorang anak perempuan berhak sepertiga harta jika bersama seorang anak laki-laki sehingga dengan demikian jika dia bersama seorang anak perempuan lebih utama lagi dan lebih didahulukan dari hubungan apa pun. Ada pula yang mengatakan bahwa demikian itu ialah untuk menghilangkan dugaan bertambahnya bagian dengan bertambahnya bilangan, yakni tatkala timbul pengertian bahwa dengan diberikannya sepertiga bagian untuk seorang anak perempuan jika ia bersama seorang anak laki-laki, maka dua orang anak perempuan beroleh dua pertiga bagian. (Jika dia) maksudnya anak perempuan itu (seorang saja) menurut qiraat dengan baris di depan sehingga kaana dianggap sebagai tam dan bukan naqish. (maka ia memperoleh seperdua harta sedangkan untuk kedua orang tuanya) maksudnya orang tua mayat yang di sini diberi badal dengan (bagi masing-masing mereka seperenam dari harta pusaka; yakni jika si mayat itu mempunyai anak) baik laki-laki maupun wanita. Ditekankannya badal ialah untuk menyatakan bahwa kedua orang tua itu tidaklah berserikat padanya. Dan terhadap adanya anak dianggap adanya cucu, begitu pula terhadap adanya bapak adanya kakek. (Jika si mayat tidak mempunyai anak dan dia diwarisi oleh kedua orang tuanya) saja atau bersama istrinya (maka bagi ibunya) dapat dibaca li-ummihi dengan hamzah baris di depan dan boleh pula limmihi dengan hamzah baris di bawah untuk meringankan bertemunya dhammah dan kasrah pada dua tempat yang berdekatan (sepertiga) maksudnya sepertiga dari harta yang telah dibagikan kepada pihak istri, sedangkan sisanya buat bapak. (Jika yang meninggal itu mempunyai beberapa orang saudara) maksudnya dua orang atau lebih, baik laki-laki atau perempuan (maka bagi ibunya seperenam) sedangkan sisanya untuk bapaknya, sementara saudara-saudaranya itu tidak beroleh bagian apa-apa. Dan pembagian warisan seperti tersebut di atas itu ialah (setelah) dilaksanakannya (wasiat yang dibuatnya) dibaca yuushii atau yuushaa dalam bentuk aktif atau pun pasif (atau) dibayarnya (utangnya). Dan disebutkannya lebih dulu pemenuhan wasiat daripada pembayaran utang, walaupun pelaksanaannya dibelakangkan ialah dengan maksud untuk tidak mengabaikannya. (Mengenai orang tuamu dan anak-anakmu) menjadi mubtada sedangkan khabarnya ialah: (tidaklah kamu ketahui manakah yang lebih dekat kepadamu manfaatnya) di dunia dan di akhirat. Ada orang yang mengira bahwa putranyalah yang lebih banyak kegunaannya kepadanya, lalu diberinya harta warisan sehingga dengan demikian ternyatalah bahwa bapaklah yang lebih bermanfaat bagi manusia, demikian sebaliknya. Maka yang mengetahui soal itu hanyalah Allah swt. dan itulah sebabnya diwajibkan-Nya pembagian pusaka. (Ini adalah ketetapan dari Allah; sesungguhnya Allah Maha Mengetahui) terhadap makhluk-Nya (lagi Maha Bijaksana) tentang peraturan-peraturan yang diberikan-Nya kepada mereka; artinya Dia tetap bersifat bijaksana dalam semuanya itu.",[["يُوصِيكُمُ","Mengarahkan kamu"],["ٱللَّهُ","Allah"],["فِىٓ","tentang"],["أَوْلَـٰدِكُمْ ۖ","anak-anak kamu"],["لِلذَّكَرِ","untuk lelaki"],["مِثْلُ","suka"],["حَظِّ","(bahagian)."],["ٱلْأُنثَيَيْنِ ۚ","(dari) dua perempuan"],["فَإِن","Tetapi jika"],["كُنَّ","ada"],["نِسَآءًۭ","(hanya) perempuan"],["فَوْقَ","lebih (daripada)"],["ٱثْنَتَيْنِ","dua"],["فَلَهُنَّ","kemudian untuk mereka"],["ثُلُثَا","dua pertiga"],["مَا","apa"],["تَرَكَ ۖ","dia pergi"],["وَإِن","Dan jika"],["كَانَتْ","(ada) ada"],["وَٰحِدَةًۭ","(hanya) satu"],["فَلَهَا","kemudian untuk dia"],["ٱلنِّصْفُ ۚ","(adalah) separuh"],["وَلِأَبَوَيْهِ","Dan untuk ibu bapanya"],["لِكُلِّ","untuk setiap"],["وَٰحِدٍۢ","satu"],["مِّنْهُمَا","daripada mereka"],["ٱلسُّدُسُ","yang keenam"],["مِمَّا","tentang apa"],["تَرَكَ","(ada) ditinggalkan"],["إِن","jika"],["كَانَ","ialah"],["لَهُۥ","baginya"],["وَلَدٌۭ ۚ","seorang kanak-kanak"],["فَإِن","Tetapi jika"],["لَّمْ","tidak"],["يَكُن","ialah"],["لَّهُۥ","baginya"],["وَلَدٌۭ","mana-mana kanak-kanak"],["وَوَرِثَهُۥٓ","dan mewarisinya"],["أَبَوَاهُ","ibu bapanya"],["فَلِأُمِّهِ","kemudian untuk ibunya"],["ٱلثُّلُثُ ۚ","(adalah) satu pertiga"],["فَإِن","Dan jika"],["كَانَ","adalah"],["لَهُۥٓ","baginya"],["إِخْوَةٌۭ","adik beradik"],["فَلِأُمِّهِ","kemudian untuk ibunya"],["ٱلسُّدُسُ ۚ","(ialah) yang keenam"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["وَصِيَّةٍۢ","sebarang kehendak"],["يُوصِى","dia telah buat"],["بِهَآ","[yang mana]"],["أَوْ","atau"],["دَيْنٍ ۗ","sebarang hutang"],["ءَابَآؤُكُمْ","ibu bapa kamu"],["وَأَبْنَآؤُكُمْ","dan anak-anak kamu"],["لَا","tidak"],["تَدْرُونَ","kamu tahu"],["أَيُّهُمْ","yang mana antara mereka"],["أَقْرَبُ","(adalah) lebih dekat"],["لَكُمْ","kepada kamu"],["نَفْعًۭا ۚ","(dalam) faedah"],["فَرِيضَةًۭ","Satu kewajipan"],["مِّنَ","daripada"],["ٱللَّهِ ۗ","Allah"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["عَلِيمًا","Maha Mengetahui"],["حَكِيمًۭا","Maha Bijaksana"]]],"505":["(Dan bagi kamu, suami-suami, seperdua dari harta peninggalan istri-istrimu jika mereka tidak mempunyai anak) baik dari kamu maupun dari bekas suaminya dulu. (Tetapi jika mereka mempunyai anak, maka kamu mendapat seperempat dari harta peninggalan, yakni setelah dipenuhinya wasiat yang mereka buat atau dibayarnya utang mereka.) Dalam hal ini cucu dianggap sama dengan anak menurut ijmak. (Dan bagi mereka) artinya para istri itu baik mereka berbilang atau tidak (seperempat dari harta yang kamu tinggalkan jika kamu tidak mempunyai anak; dan jika kamu mempunyai anak) baik dari istrimu itu maupun dari bekas istrimu (maka bagi mereka seperdelapan dari harta peninggalanmu, yakni setelah dipenuhinya wasiat yang kamu buat atau dibayarnya utangmu). Dalam hal ini cucu dianggap sama dengan anak menurut ijmak. (Jika seorang laki-laki yang diwarisi itu) menjadi sifat, sedangkan khabarnya: (kalalah) artinya tidak meninggalkan bapak dan tidak pula anak (atau perempuan) yang mewaris secara kalalah (tetapi ia mempunyai) maksudnya yang diwarisi itu (seorang saudara laki-laki atau seorang saudara perempuan) maksudnya yang seibu, dan jelas-jelas dibaca oleh Ibnu Masud dan lain-lain (maka masing-masing jenis saudara itu memperoleh seperenam) harta peninggalan. (Tetapi jika mereka itu) maksudnya saudara-saudara yang seibu itu, baik laki-laki maupun perempuan (lebih daripada itu) maksudnya lebih dari seorang (maka mereka berserikat dalam sepertiga harta) dengan bagian yang sama antara laki-laki dan perempuan (sesudah dipenuhinya wasiat yang dibuatnya atau dibayarnya utangnya tanpa memberi mudarat) menjadi hal dari dhamir yang terdapat pada yuushaa; artinya tidak menyebabkan adanya kesusahan bagi para ahli waris, misalnya dengan berwasiat lebih dari sepertiga harta (sebagai amanat) atau pesan, dan merupakan mashdar yang mengukuhkan dari yuushiikum (dari Allah, dan Allah Maha Mengetahui) faraid atau tata cara pembagian pusaka yang diatur-Nya buat makhluk-Nya (lagi Maha Penyantun) dengan menangguhkan hukuman terhadap orang-orang yang melanggarnya. Kemudian mengenai pembagian pusaka terhadap ahli-ahli waris tersebut yang mengandung keraguan dengan adanya halangan seperti pembunuhan atau perbedaan agama dan menjadi murtad, maka penjelasannya diserahkan pada sunah.",[["۞ وَلَكُمْ","Dan untuk kamu"],["نِصْفُ","(adalah) separuh"],["مَا","apa"],["تَرَكَ","(ada) ditinggalkan"],["أَزْوَٰجُكُمْ","oleh isteri-isteri kamu"],["إِن","jika"],["لَّمْ","tidak"],["يَكُن","ialah"],["لَّهُنَّ","bagi mereka"],["وَلَدٌۭ ۚ","seorang kanak-kanak"],["فَإِن","Tetapi jika"],["كَانَ","ialah"],["لَهُنَّ","bagi mereka"],["وَلَدٌۭ","seorang kanak-kanak"],["فَلَكُمُ","kemudian untuk kamu"],["ٱلرُّبُعُ","(ialah) yang keempat"],["مِمَّا","tentang apa"],["تَرَكْنَ ۚ","mereka pergi"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["وَصِيَّةٍۢ","sebarang kehendak"],["يُوصِينَ","mereka telah buat"],["بِهَآ","[untuk yang mana]"],["أَوْ","atau"],["دَيْنٍۢ ۚ","sebarang hutang"],["وَلَهُنَّ","Dan untuk mereka"],["ٱلرُّبُعُ","(ialah) yang keempat"],["مِمَّا","tentang apa"],["تَرَكْتُمْ","kamu pergi"],["إِن","jika"],["لَّمْ","tidak"],["يَكُن","ialah"],["لَّكُمْ","bagi kamu"],["وَلَدٌۭ ۚ","seorang kanak-kanak"],["فَإِن","Tetapi jika"],["كَانَ","ialah"],["لَكُمْ","bagi kamu"],["وَلَدٌۭ","seorang kanak-kanak"],["فَلَهُنَّ","kemudian untuk mereka"],["ٱلثُّمُنُ","(ialah) yang kelapan"],["مِمَّا","tentang apa"],["تَرَكْتُم ۚ","kamu pergi"],["مِّنۢ","daripada"],["بَعْدِ","selepas"],["وَصِيَّةٍۢ","sebarang kehendak"],["تُوصُونَ","kamu telah buat"],["بِهَآ","[untuk yang mana]"],["أَوْ","atau"],["دَيْنٍۢ ۗ","sebarang hutang"],["وَإِن","Dan jika"],["كَانَ","[adalah]"],["رَجُلٌۭ","seorang lelaki"],["يُورَثُ","(yang hartanya) akan diwarisi"],["كَلَـٰلَةً","(tidak mempunyai) ibu bapa atau anak"],["أَوِ","atau"],["ٱمْرَأَةٌۭ","seorang perempuan"],["وَلَهُۥٓ","dan untuk dia"],["أَخٌ","(adalah) abang"],["أَوْ","atau"],["أُخْتٌۭ","seorang kakak"],["فَلِكُلِّ","kemudian untuk setiap"],["وَٰحِدٍۢ","satu"],["مِّنْهُمَا","daripada (yang) dua"],["ٱلسُّدُسُ ۚ","(ialah) yang keenam"],["فَإِن","Tetapi jika"],["كَانُوٓا۟","mereka adalah"],["أَكْثَرَ","lebih"],["مِن","daripada"],["ذَٰلِكَ","bahawa"],["فَهُمْ","kemudian mereka"],["شُرَكَآءُ","(adalah) rakan kongsi"],["فِى","dalam"],["ٱلثُّلُثِ ۚ","yang ketiga"],["مِنۢ","daripada"],["بَعْدِ","selepas"],["وَصِيَّةٍۢ","sebarang kehendak"],["يُوصَىٰ","telah dibuat"],["بِهَآ","[untuk yang mana]"],["أَوْ","atau"],["دَيْنٍ","sebarang hutang"],["غَيْرَ","tanpa"],["مُضَآرٍّۢ ۚ","(menjadi) berbahaya"],["وَصِيَّةًۭ","Satu ordinan"],["مِّنَ","daripada"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","Dan Allah"],["عَلِيمٌ","(adalah) Maha Mengetahui"],["حَلِيمٌۭ","Maha Penyabar"]]],"506":["(Itulah) maksudnya hukum-hukum tersebut semenjak urusan anak yatim hingga berikutnya (ketentuan-ketentuan Allah) syariat-syariat yang ditetapkan-Nya buat hamba-hamba-Nya agar mereka patuhi dan tidak dikhianati. (Barang siapa yang taat kepada Allah dan Rasul-Nya) mengenai hukum-hukum yang ditetapkan-Nya itu (maka akan dimasukkan-Nya) ada yang membaca nudkhiluhu; artinya Kami masukkan ia, dengan maksud merubah pembicaraan kepada orang pertama (ke dalam surga yang mengalir di bawahnya sungai-sungai, kekal mereka di dalamnya, dan itulah kemenangan yang besar).",[["تِلْكَ","Ini"],["حُدُودُ","(adalah) had"],["ٱللَّهِ ۚ","(milik) Allah"],["وَمَن","dan sesiapa"],["يُطِعِ","patuh"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["يُدْخِلْهُ","Dia akan mengakuinya"],["جَنَّـٰتٍۢ","(ke) Taman"],["تَجْرِى","mengalir"],["مِن","daripada"],["تَحْتِهَا","di bawah mereka"],["ٱلْأَنْهَـٰرُ","sungai-sungai"],["خَـٰلِدِينَ","(akan) kekal selama-lamanya"],["فِيهَا ۚ","di dalamnya"],["وَذَٰلِكَ","Dan bahawa"],["ٱلْفَوْزُ","(ialah) kejayaan"],["ٱلْعَظِيمُ","[yang] hebat"]]],"507":["(Dan siapa yang mendurhakai Allah dan Rasul-Nya serta melanggar aturan-aturan-Nya, maka akan dimasukkan-Nya) ada dua versi dengan memakai ya dan ada pula dengan memakai nun (ke dalam api neraka, kekal ia di dalamnya dan baginya) di dalamnya (siksa yang menghinakan) di samping menciutkan hati. Pada kedua ayat terdapat lafal man sedangkan pada khaalidiina makna atau artinya.",[["وَمَن","Dan sesiapa"],["يَعْصِ","ingkar"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","dan Rasul-Nya"],["وَيَتَعَدَّ","dan melampaui batas"],["حُدُودَهُۥ","had dia"],["يُدْخِلْهُ","Dia akan mengakuinya"],["نَارًا","(kepada) Api"],["خَـٰلِدًۭا","(akan) kekal selama-lamanya"],["فِيهَا","di dalamnya"],["وَلَهُۥ","Dan untuk dia"],["عَذَابٌۭ","(ialah) azab"],["مُّهِينٌۭ","memalukan"]]],"508":["(Dan wanita-wanita yang melakukan perbuatan keji) maksudnya berzina di antara wanita-wanitamu (maka persaksikanlah mereka itu kepada empat orang saksi di antaramu) maksudnya di antara laki-lakimu yang beragama Islam. (Maka jika mereka memberikan kesaksian) terhadap perbuatan mereka itu (maka tahanlah mereka itu) atau kurunglah (dalam rumah) dan laranglah mereka bergaul dengan manusia (sampai mereka diwafatkan oleh maut) maksudnya oleh malaikat maut (atau) hingga (Allah memberi bagi mereka jalan lain) yakni jalan untuk membebaskan mereka dari hukuman semacam itu. Demikianlah hukuman mereka pada awal Islam lalu mereka diberi jalan lain yaitu digantinya dengan hukum dera sebanyak seratus kali serta membuangnya dari kampung halamannya selama setahun yakni bagi yang belum kawin dan dengan merajam wanita-wanita yang sudah kawin. Dalam hadis tersebut bahwa tatkala hukuman itu diumumkan, bersabdalah Nabi saw., \"Terimalah daripadaku, contohlah kepadaku karena Allah telah memberikan bagi mereka jalan lepas!\" Riwayat Muslim.",[["وَٱلَّـٰتِى","Dan orang yang"],["يَأْتِينَ","komited"],["ٱلْفَـٰحِشَةَ","maksiat"],["مِن","daripada"],["نِّسَآئِكُمْ","wanita kamu"],["فَٱسْتَشْهِدُوا۟","maka panggil saksi"],["عَلَيْهِنَّ","terhadap mereka"],["أَرْبَعَةًۭ","empat"],["مِّنكُمْ ۖ","antara kamu"],["فَإِن","Dan jika"],["شَهِدُوا۟","mereka bersaksi"],["فَأَمْسِكُوهُنَّ","kemudian kurung mereka"],["فِى","dalam"],["ٱلْبُيُوتِ","rumah mereka"],["حَتَّىٰ","sehingga"],["يَتَوَفَّىٰهُنَّ","datang kepada mereka"],["ٱلْمَوْتُ","[the] kematian"],["أَوْ","atau"],["يَجْعَلَ","membuat"],["ٱللَّهُ","Allah"],["لَهُنَّ","bagi mereka"],["سَبِيلًۭا","satu cara"]]],"509":["(Dan mengenai dua orang) dengan nun yang memakai atau tanpa tasydid (yang melakukannya) maksudnya perbuatan keji, yaitu berzina atau homoseksual (di antara kamu) maksudnya kaum lelaki (maka berilah mereka hukuman) dengan mencela dan memukul mereka dengan terompah. (Kemudian jika mereka bertobat) daripadanya (dan memperbaiki perbuatan mereka) (maka tinggalkanlah mereka) dan jangan disakiti lagi. (Sesungguhnya Allah Maha Penerima tobat) terhadap orang yang sadar (lagi Maha Penyayang) kepadanya. Ayat ini telah dihapus/dimansukh hukumnya dengan ayat had, jika yang dimaksud karena berzina. Demikian pula menurut Syafii jika yang dimaksud karena homoseksual. Hanya menurutnya pula, orang yang \"dikerjai\" tidaklah dirajam walaupun telah beristri, hanya dipukul dan diasingkan. Bahwa yang dimaksud itu homoseksual lebih kuat dengan alasan adanya dhamir tatsniah huma dan lain-lain. Menurut golongan yang pertama yang dimaksud dengan kedua mereka itu ialah pezina yang laki-laki dan yang perempuan. Tetapi pendapat ini ditolak oleh golongan Syafii dengan penjelasan yang diberikan kemudian dengan hubungannya yang berkaitan dengan dhamir laki-laki dan berserikatnya kedua mereka dalam menerima hukuman, bertobat dan diisolir. Dan ini khusus bagi pihak laki-laki, karena sebagaimana kita ketahui bagi pihak wanita ialah tahanan rumah.",[["وَٱلَّذَانِ","Dan dua yang"],["يَأْتِيَـٰنِهَا","laksanakannya"],["مِنكُمْ","antara kamu"],["فَـَٔاذُوهُمَا ۖ","maka hukumlah mereka berdua"],["فَإِن","Tetapi jika"],["تَابَا","mereka bertaubat"],["وَأَصْلَحَا","dan membetulkan diri mereka"],["فَأَعْرِضُوا۟","kemudian berpaling"],["عَنْهُمَآ ۗ","daripada mereka berdua"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["تَوَّابًۭا","Selalu Memaafkan"],["رَّحِيمًا","Maha Penyayang"]]],"510":["(Sesungguhnya tobat di isi Allah) yakni yang pasti diterima di sisi-Nya berkat kemurahan-Nya (ialah bagi orang-orang yang mengerjakan kejahatan) atau maksiat (disebabkan kejahilan) menjadi hal artinya tidak tahu bahwa dengan itu berarti mendurhakai Allah (kemudian mereka bertobat dalam) waktu (dekat) yakni sebelum mengalami sekarat (maka mereka itulah yang diterima tobatnya oleh Allah) artinya diterima-Nya tobat mereka (dan Allah Maha Mengetahui) akan makhluk-Nya (lagi Maha Bijaksana) mengenai tindakan-Nya terhadap mereka.",[["إِنَّمَا","Hanya"],["ٱلتَّوْبَةُ","penerimaan taubat"],["عَلَى","oleh"],["ٱللَّهِ","Allah"],["لِلَّذِينَ","(adalah) bagi mereka yang"],["يَعْمَلُونَ","lakukan"],["ٱلسُّوٓءَ","yang jahat"],["بِجَهَـٰلَةٍۢ","dalam kejahilan"],["ثُمَّ","kemudian"],["يَتُوبُونَ","mereka bertaubat"],["مِن","daripada"],["قَرِيبٍۢ","tidak lama kemudian"],["فَأُو۟لَـٰٓئِكَ","Kemudian mereka"],["يَتُوبُ","akan mendapat pengampunan"],["ٱللَّهُ","(dari) Allah"],["عَلَيْهِمْ ۗ","ke atas mereka"],["وَكَانَ","dan adalah"],["ٱللَّهُ","Allah"],["عَلِيمًا","Maha Mengetahui"],["حَكِيمًۭا","Maha Bijaksana"]]],"511":["(Dan tidaklah dikatakan tobat bagi orang-orang yang mengerjakan kejahatan) atau dosa (hingga ketika ajal datang kepada salah seorang mereka) dan nyawanya hendak lepas (lalu dikatakannya) ketika menyaksikan apa yang sedang dialaminya (\"Sesungguhnya saya bertobat sekarang.\") karena itu tidaklah bermanfaat dan tidak akan diterima oleh Allah tobatnya. (Dan tidak pula orang-orang yang mati sedangkan mereka berada dalam kekafiran) yakni jika mereka bertobat di akhirat sewaktu menyaksikan azab, maka tidak pula akan diterima. (Mereka itu Kami siapkan) sediakan (bagi mereka siksa yang pedih) yang menyakitkan.",[["وَلَيْسَتِ","Dan tidak"],["ٱلتَّوْبَةُ","(ialah) penerimaan taubat"],["لِلَّذِينَ","bagi mereka yang"],["يَعْمَلُونَ","lakukan"],["ٱلسَّيِّـَٔاتِ","perbuatan jahat itu"],["حَتَّىٰٓ","sehingga"],["إِذَا","apabila"],["حَضَرَ","pendekatan"],["أَحَدَهُمُ","salah seorang daripada mereka"],["ٱلْمَوْتُ","[the] kematian"],["قَالَ","katanya"],["إِنِّى","Sesungguhnya aku"],["تُبْتُ","bertaubat"],["ٱلْـَٔـٰنَ","sekarang"],["وَلَا","dan bukan"],["ٱلَّذِينَ","orang yang"],["يَمُوتُونَ","mati"],["وَهُمْ","sedangkan mereka"],["كُفَّارٌ ۚ","(adalah) orang-orang kafir"],["أُو۟لَـٰٓئِكَ","Itu"],["أَعْتَدْنَا","Kami telah sediakan"],["لَهُمْ","bagi mereka"],["عَذَابًا","azab"],["أَلِيمًۭا","yang pedih"]]],"512":["(Hai orang-orang yang beriman, tidak halal bagi kamu mewarisi wanita) maksudnya diri mereka (dengan paksa) dibaca karhan atau kurhan; artinya tanpa kemauan dan kerelaan mereka. Di zaman jahiliah mereka biasa mewarisi wanita-wanita, istri karib kerabat mereka. Jika mereka kehendaki mereka dapat mengawininya tanpa maskawin, atau mereka kawinkan lalu diambil maskawinnya, atau mereka halangi kawin sampai wanita itu menebus dirinya dengan harta warisan yang diperolehnya atau mereka tunggu sampai meninggal lalu mereka warisi hartanya; maka mereka dilarang demikian itu. (Dan tidak pula) bahwa (kamu menyusahkan mereka) artinya kamu halangi istri-istrimu buat mengawini laki-laki lain dengan menahan mereka padahal tak ada keinginanmu lagi terhadap mereka selain dari menyusahkan belaka (karena hendak mengambil kembali sebagian dari apa yang telah kamu berikan kepada mereka) berupa mahar (kecuali jika mereka melakukan pekerjaan keji yang nyata) dengan ya baris di atas dan baris di bawah, yang nyata atau yang dinyatakan, artinya zina atau nusyuz; maka ketika itu bolehlah kamu menyusahkan mereka hingga mereka melakukan khuluk atau menebus diri mereka (dan pergaulilah mereka secara patut) artinya secara baik-baik, biar dalam perkataan maupun dalam memberi nafkah lahir atau batin. (Maka jika kamu tidak menyukai mereka) hendaklah bersabar (karena mungkin kamu tidak menyukai sesuatu tetapi Allah menjadikan padanya kebaikan yang banyak). Siapa tahu hal itu dilakukan-Nya misalnya dengan menganugerahimu anak yang saleh.",[["يَـٰٓأَيُّهَا","Wahai"],["ٱلَّذِينَ","yang"],["ءَامَنُوا۟","beriman"],["لَا","Tidak"],["يَحِلُّ","(adalah) halal"],["لَكُمْ","bagi kamu"],["أَن","bahawa"],["تَرِثُوا۟","kamu mewarisi"],["ٱلنِّسَآءَ","kaum wanita"],["كَرْهًۭا ۖ","(dengan) kekerasan"],["وَلَا","Dan tidak"],["تَعْضُلُوهُنَّ","kamu mengekang mereka"],["لِتَذْهَبُوا۟","supaya kamu boleh mengambil"],["بِبَعْضِ","bahagian"],["مَآ","apa"],["ءَاتَيْتُمُوهُنَّ","kamu telah memberi mereka"],["إِلَّآ","kecuali"],["أَن","bahawa"],["يَأْتِينَ","mereka komited"],["بِفَـٰحِشَةٍۢ","maksiat"],["مُّبَيِّنَةٍۢ ۚ","terbuka"],["وَعَاشِرُوهُنَّ","Dan hidup bersama mereka"],["بِٱلْمَعْرُوفِ ۚ","dalam kebaikan"],["فَإِن","Tetapi jika"],["كَرِهْتُمُوهُنَّ","kamu tidak menyukai mereka"],["فَعَسَىٰٓ","maka mungkin"],["أَن","bahawa"],["تَكْرَهُوا۟","kamu tidak suka"],["شَيْـًۭٔا","sesuatu perkara"],["وَيَجْعَلَ","dan telah meletakkan"],["ٱللَّهُ","Allah"],["فِيهِ","di dalamnya"],["خَيْرًۭا","kebaikan"],["كَثِيرًۭا","banyak"]]],"513":["(Dan jika kamu bermaksud hendak mengganti istrimu dengan istri yang lain) artinya kamu ambil dia sebagai penggantinya setelah kamu ceraikan istrimu yang pertama itu (dan) sungguh (kamu telah memberikan kepada salah seorang di antara mereka) maksudnya istri-istri itu (harta yang banyak) sebagai maskawinnya (maka janganlah kamu mengambil kembali daripadanya barang sedikit pun. Apakah kamu akan mengambilnya kembali secara aniaya) dengan zalim (dan dengan -memikul- dosa yang nyata?) Dinashabkan keduanya karena kedudukan mereka sebagai hal sedangkan pertanyaan berikut maksudnya sebagai celaan dan penolakan:",[["وَإِنْ","Dan jika"],["أَرَدتُّمُ","kamu berniat"],["ٱسْتِبْدَالَ","menggantikan"],["زَوْجٍۢ","seorang isteri"],["مَّكَانَ","(di) tempat"],["زَوْجٍۢ","(dari) seorang isteri"],["وَءَاتَيْتُمْ","dan kamu telah memberi"],["إِحْدَىٰهُنَّ","salah seorang daripada mereka"],["قِنطَارًۭا","timbunan (emas)"],["فَلَا","maka (buat) jangan"],["تَأْخُذُوا۟","bawa pergi"],["مِنْهُ","daripadanya"],["شَيْـًٔا ۚ","sesuatu"],["أَتَأْخُذُونَهُۥ","Adakah kamu akan mengambilnya"],["بُهْتَـٰنًۭا","(oleh) fitnah"],["وَإِثْمًۭا","dan dosa"],["مُّبِينًۭا","terbuka"]]],"514":["(Bagaimana kamu akan mengambilnya kembali) artinya dengan alasan apa (padahal sebagian kamu telah bergaul dengan yang lain) atau telah berhubungan sebagai suami istri dengan bercampur yang telah mensahkan maskawin (dan mereka telah mengambil daripadamu perjanjian) atau pengakuan (yang erat) atau berat, yakni berupa perintah Ilahi agar memegang mereka secara baik-baik atau melepas mereka secara baik-baik pula.",[["وَكَيْفَ","Dan bagaimana"],["تَأْخُذُونَهُۥ","boleh kamu ambil"],["وَقَدْ","apabila pasti"],["أَفْضَىٰ","telah pergi"],["بَعْضُكُمْ","salah seorang daripada kamu"],["إِلَىٰ","kepada"],["بَعْضٍۢ","yang lain"],["وَأَخَذْنَ","dan mereka telah mengambil"],["مِنكُم","daripada kamu"],["مِّيثَـٰقًا","perjanjian"],["غَلِيظًۭا","kuat"]]],"515":["(Dan janganlah kamu kawini apa) maksudnya siapa (Di antara wanita-wanita yang telah dikawini oleh bapakmu kecuali) artinya selain dari (yang telah berlalu) dari perbuatanmu itu, maka dimaafkan. (Sesungguhnya hal itu) maksudnya mengawini mereka itu (adalah perbuatan keji) atau busuk (suatu kutukan) maksudnya sesuatu yang menyebabkan timbulnya kutukan dari Allah, yang berarti kemurkaan-Nya yang amat sangat (dan sejahat-jahat) seburuk-buruk (jalan) yang ditempuh.",[["وَلَا","Dan jangan"],["تَنكِحُوا۟","kahwin"],["مَا","yang"],["نَكَحَ","berkahwin"],["ءَابَآؤُكُم","bapa-bapa kamu"],["مِّنَ","daripada"],["ٱلنِّسَآءِ","kaum wanita"],["إِلَّا","kecuali"],["مَا","apa"],["قَدْ","mempunyai"],["سَلَفَ ۚ","berlalu sebelum ini"],["إِنَّهُۥ","sesungguhnya ia"],["كَانَ","adalah"],["فَـٰحِشَةًۭ","suatu maksiat"],["وَمَقْتًۭا","dan penuh kebencian"],["وَسَآءَ","dan (satu) kejahatan"],["سَبِيلًا","cara"]]],"516":["(Diharamkan atas kamu ibu-ibumu) maksudnya mengawini mereka dan ini mencakup pula nenek, baik dari pihak bapak maupun dari pihak ibu (dan anak-anak perempuanmu) termasuk cucu-cucumu yang perempuan terus ke bawah (saudara-saudaramu yang perempuan) baik dari pihak bapak maupun dari pihak ibu (saudara-saudara bapakmu yang perempuan) termasuk pula saudara-saudara kakekmu (saudara-saudara ibumu yang perempuan) termasuk pula saudara-saudara nenekmu (anak-anak perempuan dari saudaramu yang laki-laki, anak-anak perempuan dari saudaramu yang perempuan) maksudnya keponakan-keponakanmu dan tercakup pula di dalamnya anak-anak mereka (ibu-ibumu yang menyusui kamu) maksudnya ibu-ibu susuan, yakni sebelum usiamu mencapai dua tahun dan sekurang-kurangnya lima kali susuan sebagaimana dijelaskan oleh hadis (saudara-saudara perempuanmu sesusuan). Kemudian dalam sunah ditambahkan anak-anak perempuan daripadanya, yaitu wanita-wanita yang disusukan oleh wanita-wanita yang telah dicampurinya, berikut saudara-saudara perempuan dari bapak dan dari ibu, serta anak-anak perempuan dari saudara laki-laki dan anak-anak perempuan dari saudara perempuannya, berdasarkan sebuah hadis yang berbunyi, \"Haram disebabkan penyusuan apa yang haram oleh sebab pertalian darah.\" Riwayat Bukhari dan Muslim. (ibu-ibu istrimu, mertua, dan anak-anak tirimu) jamak rabiibah yaitu anak perempuan istri dari suaminya yang lain (yang berada dalam asuhanmu) mereka berada dalam pemeliharaan kalian; kalimat ini berkedudukan sebagai kata sifat dari lafal rabaaib (dan istri-istrimu yang telah kamu campuri) telah kalian setubuhi (tetapi jika kamu belum lagi mencampuri mereka, maka tidaklah berdosa kamu) mengawini anak-anak perempuan mereka, jika kamu telah menceraikan mereka (dan diharamkan istri-istri anak kandungmu) yakni yang berasal dari sulbimu, berbeda halnya dengan anak angkatmu, maka kamu boleh kawin dengan janda-janda mereka (dan bahwa kamu himpun dua orang perempuan yang bersaudara) baik saudara dari pertalian darah maupun sepersusuan, dan menghimpun seorang perempuan dengan saudara perempuan bapaknya atau saudara perempuan ibunya tetapi diperbolehkan secara \"tukar lapik\" atau \"turun ranjang\" atau memiliki kedua mereka sekaligus asal yang dicampuri itu hanya salah seorang di antara mereka (kecuali) atau selain (yang telah terjadi di masa lalu) yakni di masa jahiliah sebagian dari apa yang disebutkan itu, maka kamu tidaklah berdosa karenanya. (Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang).",[["حُرِّمَتْ","Dilarang"],["عَلَيْكُمْ","kepada kamu"],["أُمَّهَـٰتُكُمْ","(adalah) ibu kamu"],["وَبَنَاتُكُمْ","dan anak perempuan kamu"],["وَأَخَوَٰتُكُمْ","dan adik-adik kamu"],["وَعَمَّـٰتُكُمْ","dan adik-beradik ayah kamu"],["وَخَـٰلَـٰتُكُمْ","dan adik-beradik ibu kamu"],["وَبَنَاتُ","dan anak perempuan"],["ٱلْأَخِ","(dari) saudara"],["وَبَنَاتُ","dan anak perempuan"],["ٱلْأُخْتِ","(daripada) saudara perempuan"],["وَأُمَّهَـٰتُكُمُ","dan (para) ibu"],["ٱلَّـٰتِىٓ","yang"],["أَرْضَعْنَكُمْ","menyusu kamu"],["وَأَخَوَٰتُكُم","dan adik-adik kamu"],["مِّنَ","daripada"],["ٱلرَّضَـٰعَةِ","kejururawatan"],["وَأُمَّهَـٰتُ","dan ibu-ibu"],["نِسَآئِكُمْ","(dari) isteri-isteri kamu"],["وَرَبَـٰٓئِبُكُمُ","dan anak-anak tirimu"],["ٱلَّـٰتِى","yang"],["فِى","(ada) dalam"],["حُجُورِكُم","penjagaan kamu"],["مِّن","daripada"],["نِّسَآئِكُمُ","wanita kamu"],["ٱلَّـٰتِى","yang"],["دَخَلْتُم","kamu mempunyai hubungan"],["بِهِنَّ","bersama mereka"],["فَإِن","tetapi jika"],["لَّمْ","tidak"],["تَكُونُوا۟","kamu ada"],["دَخَلْتُم","perhubungan"],["بِهِنَّ","bersama mereka"],["فَلَا","maka (ada) tidak"],["جُنَاحَ","dosa"],["عَلَيْكُمْ","pada kamu"],["وَحَلَـٰٓئِلُ","Dan isteri-isteri"],["أَبْنَآئِكُمُ","(dari) anak lelaki kamu"],["ٱلَّذِينَ","orang yang"],["مِنْ","(adalah) daripada"],["أَصْلَـٰبِكُمْ","pinggang kamu"],["وَأَن","dan bahawa"],["تَجْمَعُوا۟","kamu berkumpul bersama"],["بَيْنَ","[antara]"],["ٱلْأُخْتَيْنِ","dua beradik perempuan"],["إِلَّا","kecuali"],["مَا","apa"],["قَدْ","mempunyai"],["سَلَفَ ۗ","berlalu sebelum ini"],["إِنَّ","Sesungguhnya"],["ٱللَّهَ","Allah"],["كَانَ","ialah"],["غَفُورًۭا","Selalu Memaafkan"],["رَّحِيمًۭا","Maha Penyayang"]]]});